INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dc20d24-71d5-4c1a-972a-4e23ee9cc34f', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十九', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鼓打不多鳴。","一丈高懸併九尺，都虞副將驗槌聲，七拜解妖精。","（各七拜後打。","）。"]', '["城營內，鼓打不多鳴。","一丈高懸併九尺，都虞副將驗槌声，七拜解妖精。","（各七拜後打。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab4c6f2a-1c98-4ae3-bbd1-43e624b8bf18', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，鼓打不能鳴。","主將戰輸遭寇擄，早須收拾便回程，不去損其兵。","（移寨兵得。","）。"]', '["城營內，鼓打不能鳴。","主將戰輸遭寇擄，早須收拾便回程，不去損其兵。","（移寨兵得。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29da5319-74c4-4594-b185-2252029431ec', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十一', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["或晝夜，大將劍刀鳴。","刺客奸人在庭（京本作「應在」）近，急須搜捉莫教停，不信（辛本、川本作「便見」）血光成（京本作「成坑」）。"]', '["或晝夜，大將劍刀鳴。","刺客奸人在庭（京本作「應在」）近，急須搜捉莫教停，不信（辛本、川本作「便见」）血光成（京本作「成坑」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ade81606-1b07-4802-aba1-5aaa2c47c665', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十二', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["營與邑，井沸聞其（京本作「鼎沸忽聞」）聲。","或溢水泉皆是敗，更還（京本作「逢」）龍見也同情，覩此便移營。"]', '["營與邑，井沸闻其（京本作「鼎沸忽闻」）声。","或溢水泉皆是敗，更還（京本作「逢」）龙见也同情，覩此便移營。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b947b386-1aa8-430f-9fd1-3bbb9ec03a81', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十三', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營內，獨鼓（辛本、川本作「角」）自然（京本作「能」）鳴。","此兆敵人來劫我，隨鳴火急整精兵，遠探向前征。"]', '["城營內，独鼓（辛本、川本作「角」）自然（京本作「能」）鳴。","此兆敵人来劫我，隨鳴火急整精兵，远探向前征。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7b74ac2-dd8a-4be3-8da0-95bb79a3cee7', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十四', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["城營角，吹聲（辛本、川本、京本作「了」）遠而微。","韻斷聲長（京本作「哀」）人怪訝，兆當我衆有災危，固守免傾（首本作「灾」，茲從辛本、川本、京本）頹。"]', '["城營角，吹声（辛本、川本、京本作「了」）远而微。","韻斷声长（京本作「哀」）人怪訝，兆當我衆有災危，固守免傾（首本作「灾」，茲從辛本、川本、京本）頹。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a11d7c-456e-4c0f-9a0c-b6dc1aaad617', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十五', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金鼙鼓，自裂七分餘。","此是三（京本作「將」）軍囚沒兆（京本作「死」），速當求解醮移居，不可侈（辛本、川本、京本作「恣」）行誅。"]', '["金鼙鼓，自裂七分餘。","此是三（京本作「將」）軍囚沒兆（京本作「死」），速當求解醮移居，不可侈（辛本、川本、京本作「恣」）行誅。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93411893-7010-44db-acf4-1c3847a50dae', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十六', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鎗旗戟，無故倒交加。","象主病災如臥草，四門宰犬瀝田沙，子候（京本作「後」）設施佳。","（子時以犬血瀝四門地上。","）。"]', '["鎗旗戟，無故倒交加。","象主病災如臥草，四门宰犬瀝田沙，子候（京本作「後」）設施佳。","（子时以犬血瀝四门地上。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69d0f7a8-0193-46d3-ac5c-2e106aec0c1f', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十七', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鈴與鐸，風息自然鳴。","鼓角雄聲音振地，必須勝敵悅軍行（辛本、川本、京本作「情」），擁衆返回程。"]', '["鈴與鐸，风息自然鳴。","鼓角雄声音振地，必須勝敵悅軍行（辛本、川本、京本作「情」），擁衆返回程。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('512c4588-f377-4dcb-b36c-6c2b3505373c', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十八', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["或晝夜，飲宴在其中。","驀地盞鳴人總訝，賊（辛本、川本、京本作「劫」）人已起影無蹤（辛本、川本作「意忙匆」、京本作「盡忙匆」），急遣將邀衝。"]', '["或晝夜，饮宴在其中。","驀地盞鳴人總訝，賊（辛本、川本、京本作「劫」）人已起影無蹤（辛本、川本作「意忙匆」、京本作「尽忙匆」），急遣將邀衝。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0c6be3-6e21-49e1-8f17-cef589e63ea4', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十九', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["杯器內，清水忽然紅。","有似血來人盡訝，此爲祥瑞立奇功，戰急總無凶。"]', '["杯器內，清水忽然紅。","有似血来人尽訝，此爲祥瑞立奇功，戰急總無凶。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 三十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de61769c-454b-4903-af7a-c2c35554ccc4', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍營內，戰馬忽然嘶。","跑擁搖身非時亂，賊兵降伏要相欺，祭享上天知。"]', '["軍營內，戰马忽然嘶。","跑擁搖身非时亂，賊兵降伏要相欺，祭享上天知。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d99706-64ee-453d-b608-ba95e2773237', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十一', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍器甲，夜後更生光。","折毀月形方上窖，離營百步正相當，遠去更宜長（辛本作「良」）。"]', '["軍器甲，夜後更生光。","折毀月形方上窖，離營百步正相當，远去更宜长（辛本作「良」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc205dc8-d6a1-447c-8a75-ede3aa0a308d', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十二', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["風不起，旗號自飛揚。","前指敵軍幷陣次，必當我勝用心腸，得勝早回鄉。","。"]', '["风不起，旗號自飞揚。","前指敵軍幷陣次，必當我勝用心腸，得勝早回乡。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f8e8fb-a3e3-41f2-8743-e0a4c43ecaf4', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十三', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["臨陣次，馬匹忽然驚。","欲悚欲慊多退縮，牽纏不動自遲情，回首免軍驚。"]', '["臨陣次，马匹忽然驚。","欲悚欲慊多退縮，牽纏不动自遲情，回首免軍驚。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa0d630-f4c6-4576-9ee7-3373ea934bee', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十四', '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占怪異，說與衆賢知。","正是一人行踏處，當逢奇異怪逢爲，兵衆豈無知。"]', '["占怪異，说與衆賢知。","正是一人行踏处，當逢奇異怪逢爲，兵衆豈無知。"]', '诗', 'shi', '', NULL, '兵要望江南 占怪第二十三（京本作「占怪象第十四」○四十四首） 四十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d33b1c7f-a9f1-438a-b37f-429e330b6ae4', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 一', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["禳厭法，其理事情深。","首異諸般奇異怪，或逢要日要時辰，厭法要精明。"]', '["禳厭法，其理事情深。","首異諸般奇異怪，或逢要日要时辰，厭法要精明。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f1fe88-ff7e-40d7-be5c-8645400e1fe3', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 二', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍行日，春正及春分。","須用長鎗前列（京本作「作」）勝，次排弓弩在中軍，決勝定須聞。"]', '["軍行日，春正及春分。","須用长鎗前列（京本作「作」）勝，次排弓弩在中軍，決勝定須闻。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9dc21ce-37b5-47ba-88b2-dd1e51d1fddc', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 三', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍行日，立夏至皆同。","令下三軍諸將士，須排戈戟作先鋒，將士定英雄。"]', '["軍行日，立夏至皆同。","令下三軍諸將士，須排戈戟作先鋒，將士定英雄。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a07ad083-e681-42d9-94e7-16989ec4453c', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 四', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍行日，秋始與秋分。","金氣旺時須要順，先持弓矢向前行（京本作「存」），得勝遠方聞。"]', '["軍行日，秋始與秋分。","金氣旺时須要順，先持弓矢向前行（京本作「存」），得勝远方闻。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7427dea3-1bc8-4d1c-a0f5-e7b101052464', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 五', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍行日，凜冽正當冬。","得氣一陽回一候，首令刀劍向前衝，舉戰得全功。"]', '["軍行日，凜冽正當冬。","得氣一陽回一候，首令刀劍向前衝，舉戰得全功。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ba6275-f2aa-47c8-b7ec-4684be611c97', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 六', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["東方陣，角姓七人從。","純着青衣青隊伏，青旗青（京本作「驄」）馬作先鋒，木陣號青龍。"]', '["东方陣，角姓七人從。","純着青衣青隊伏，青旗青（京本作「驄」）马作先鋒，木陣號青龙。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1902148b-50aa-4f0c-aa6a-ad88121093c4', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 七', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["南方陣，徴姓最爲雄。","七箇赤衣乘赤馬，赤旗招動號長空，朱雀陣先鋒。"]', '["南方陣，徴姓最爲雄。","七箇赤衣乘赤马，赤旗招动號长空，朱雀陣先鋒。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a837ee5-c2ac-44aa-a7ca-c8b6f86d59b1', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 八', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["西方陣，商姓白衣兵。","七箇健兒乘白馬，白旗獨角（京本作「却」）引前程（京本作「行」），爲首向先行（京本作「前征」）。"]', '["西方陣，商姓白衣兵。","七箇健兒乘白马，白旗独角（京本作「却」）引前程（京本作「行」），爲首向先行（京本作「前征」）。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fb8b32-3882-4969-bd3f-d113d1448de4', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 九', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["北方陣，羽姓顯然明。","騅馬烏衣如北斗，黑旗玄武隊前行，賊將勢摧傾。"]', '["北方陣，羽姓显然明。","騅马烏衣如北斗，黑旗玄武隊前行，賊將勢摧傾。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2e75bc-f670-415c-a78d-56a1798a0133', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["中央陣，宮姓要黃衣。","七箇黃旗黃色馬，勾陣大將助堪依，敵國定橫屍。"]', '["中央陣，宮姓要黄衣。","七箇黄旗黄色马，勾陣大將助堪依，敵国定橫屍。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eb9b2bd-e6fa-45d8-b548-3d7e229d558b', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十一', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡行陣，甲子甲辰申（京本作「寅辰」）。","三箇甲頭旬日內，前驅（辛本、川本作「祛」、京本作「行」）天馬擺令真，整頓要辛勤。"]', '["凡行陣，甲子甲辰申（京本作「寅辰」）。","三箇甲头旬日內，前驱（辛本、川本作「祛」、京本作「行」）天马擺令真，整頓要辛勤。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ecde76-d131-4378-bdae-75b87cb5db05', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十二', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡行陣，甲午甲寅（京本作「申」）旬。","甲戌都來爲一處，當時（京本作「持」）刀劍在前行，其陣勒來兵。","。"]', '["凡行陣，甲午甲寅（京本作「申」）旬。","甲戌都来爲一处，當时（京本作「持」）刀劍在前行，其陣勒来兵。","。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('529d7a1e-91e6-4c71-aad9-6f174b976c4b', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十三', '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["揚兵吉（京本作「禳兵告」），頓在（辛本、川本、京本作「須向」）九天方。","諸惡不成加喜氣。","更宜上將見恩光，安得（京本作「將」）有乖張。","（《太乙式》云：「九天之上，可以陳兵，九地之下，可以潛伏。","」）。"]', '["揚兵吉（京本作「禳兵告」），頓在（辛本、川本、京本作「須向」）九天方。","諸惡不成加喜氣。","更宜上將见恩光，安得（京本作「將」）有乖張。","（《太乙式》云：「九天之上，可以陳兵，九地之下，可以潛伏。","」）。"]', '诗', 'shi', '', NULL, '兵要望江南 禳厭第二十四（京本作「占厭禳第十九」○十三首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0705a821-ea3a-41f1-80e2-bdba7bf0e1ed', '兵要望江南 占夢第二十五（京本列第十三○九首） 一', '兵要望江南 占梦第二十五（京本列第十三○九首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡占夢，本出自微茫。","得一夢來三事應，方知凶吉爲君張，神魄預知祥。"]', '["凡占梦，本出自微茫。","得一梦来三事應，方知凶吉爲君張，神魄預知祥。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4ac0fd-bbcc-412e-976d-67e477aacb3f', '兵要望江南 占夢第二十五（京本列第十三○九首） 二', '兵要望江南 占梦第二十五（京本列第十三○九首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，雲外見飛龍。","急去戰時須獲捷，不過三（辛本、川本作「百」）日帝王封，位顯立奇功。"]', '["將軍梦，云外见飞龙。","急去戰时須獲捷，不過三（辛本、川本作「百」）日帝王封，位显立奇功。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db9fa18-e023-462e-9cf9-c56bcc3abc4d', '兵要望江南 占夢第二十五（京本列第十三○九首） 三', '兵要望江南 占梦第二十五（京本列第十三○九首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，魚變作蛟龍。","百戰自然皆百勝，相敵來捉必無凶，大將職加封。"]', '["將軍梦，鱼变作蛟龙。","百戰自然皆百勝，相敵来捉必無凶，大將職加封。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a428e38-c7a5-472b-8568-8901400fffbf', '兵要望江南 占夢第二十五（京本列第十三○九首） 四', '兵要望江南 占梦第二十五（京本列第十三○九首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，打（辛本、川本、京本作「大」）鼓大聲鳴。","小鼓小聲（京本作「鳴」）軍小勝，不鳴固守莫先（京本作「前」）征，勝負取其聲。"]', '["將軍梦，打（辛本、川本、京本作「大」）鼓大声鳴。","小鼓小声（京本作「鳴」）軍小勝，不鳴固守莫先（京本作「前」）征，勝負取其声。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52548074-cf60-492a-9dfa-bc27d332afc0', '兵要望江南 占夢第二十五（京本列第十三○九首） 五', '兵要望江南 占梦第二十五（京本列第十三○九首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，夢得大魚形。","若得小魚軍（京本作「兵」）小勝，電光霹靂主軍鳴（辛本、川本、京本作「驚」），此象最爲靈。"]', '["將軍梦，梦得大鱼形。","若得小鱼軍（京本作「兵」）小勝，電光霹靂主軍鳴（辛本、川本、京本作「驚」），此象最爲靈。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b79196ab-fc6e-4213-8d3c-6f5e37287d83', '兵要望江南 占夢第二十五（京本列第十三○九首） 六', '兵要望江南 占梦第二十五（京本列第十三○九首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，見水及（京本作「夢見汲」）波濤。","或（京本作「忽」）與敵人相角（京本作「爭」）競，須來挑（京本作「排」）戰莫輕交，堅守我門橋。"]', '["將軍梦，见水及（京本作「梦见汲」）波濤。","或（京本作「忽」）與敵人相角（京本作「爭」）競，須来挑（京本作「排」）戰莫轻交，堅守我门橋。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3907a25d-5ee7-40e5-acdf-b8db4d2b48e0', '兵要望江南 占夢第二十五（京本列第十三○九首） 七', '兵要望江南 占梦第二十五（京本列第十三○九首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，天上作雷鳴。","破敵勤（辛本、川本、京本作「擒」）王有（京本作「看」）此兆，無（京本作「不」）拘明（辛本、川本、京本作「月」）暗與陰晴，擁（京本作「勇」）士向前程（京本作「征」）。"]', '["將軍梦，天上作雷鳴。","破敵勤（辛本、川本、京本作「擒」）王有（京本作「看」）此兆，無（京本作「不」）拘明（辛本、川本、京本作「月」）暗與陰晴，擁（京本作「勇」）士向前程（京本作「征」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd9d85f-2955-40e5-8391-1ed40da76e9f', '兵要望江南 占夢第二十五（京本列第十三○九首） 八', '兵要望江南 占梦第二十五（京本列第十三○九首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，身涉大高山。","遇戰必贏功顯著，相逢敵戰（京本作「鬬敵」）急攻殘，莫放片時間。"]', '["將軍梦，身涉大高山。","遇戰必贏功显著，相逢敵戰（京本作「鬬敵」）急攻殘，莫放片时间。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bef96d4-a7d1-4fce-91ee-20fd838cac5b', '兵要望江南 占夢第二十五（京本列第十三○九首） 九', '兵要望江南 占梦第二十五（京本列第十三○九首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍夢，夢見大舟船。","順水順風帆幔順，戰之獲捷獨爲先，快樂（辛本、川本作「不爾」）似神仙。","。"]', '["將軍梦，梦见大舟船。","順水順风帆幔順，戰之獲捷独爲先，快乐（辛本、川本作「不爾」）似神仙。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占夢第二十五（京本列第十三○九首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1631f0e-7f92-4aba-ab8b-5384e54563a9', '兵要望江南 《周易》占候第二十六（三十七首） 一', '兵要望江南 《周易》占候第二十六（三十七首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["聖人造，作《易》變爻辭。","擲卦要知凶與吉，切須盥手動占儀，懇意合天機。"]', '["聖人造，作《易》变爻辞。","擲卦要知凶與吉，切須盥手动占儀，懇意合天機。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f61f8d6-62c5-4c39-b779-db8919f71783', '兵要望江南 《周易》占候第二十六（三十七首） 二', '兵要望江南 《周易》占候第二十六（三十七首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡占《易》，動靜卦爻裝。","先辨剛柔分彼我，更分主客要知當，決勝自昭彰。"]', '["凡占《易》，动静卦爻裝。","先辨剛柔分彼我，更分主客要知當，決勝自昭彰。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('190bee7c-523d-49b2-ad8d-62d4c7f62989', '兵要望江南 《周易》占候第二十六（三十七首） 三', '兵要望江南 《周易》占候第二十六（三十七首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["論主客，後舉我爲尊。","旗底（辛本、川本作「低」）住坐並爲主，先身行者號爲賓，此理甚分明。"]', '["論主客，後舉我爲尊。","旗底（辛本、川本作「低」）住坐並爲主，先身行者號爲賓，此理甚分明。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15bd5c3-1751-4168-8188-a769ae993c10', '兵要望江南 《周易》占候第二十六（三十七首） 四', '兵要望江南 《周易》占候第二十六（三十七首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["入他國，我即論爲（辛本、川本作「其」）賓。","若是他來攻我寨，我爲主（辛本、川本作「賓」）者汝爲賓（辛本、川本作「尊」），此理合天文。"]', '["入他国，我即論爲（辛本、川本作「其」）賓。","若是他来攻我寨，我爲主（辛本、川本作「賓」）者汝爲賓（辛本、川本作「尊」），此理合天文。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29d7015-b8e2-4609-a997-eb5d1c3f8b17', '兵要望江南 《周易》占候第二十六（三十七首） 五', '兵要望江南 《周易》占候第二十六（三十七首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡占《易》，先論六親方。","大煞彼鄉（辛本、川本作「大謹五鄉」）比和尅，應殺世主總漂揚，官鬼子孫量。"]', '["凡占《易》，先論六親方。","大煞彼乡（辛本、川本作「大謹五乡」）比和尅，應殺世主總漂揚，官鬼子孫量。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('608132b3-d5c4-45b3-9699-c79941ea4ea9', '兵要望江南 《周易》占候第二十六（三十七首） 六', '兵要望江南 《周易》占候第二十六（三十七首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["彼與我，子鬼取爲先。","子孫旺相吾軍勝，鬼爻囚死彼（辛本、川本作「復」）遭愆，反此亦如然。"]', '["彼與我，子鬼取爲先。","子孫旺相吾軍勝，鬼爻囚死彼（辛本、川本作「复」）遭愆，反此亦如然。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a770a7c-4e5f-445a-8b25-404c31ae5556', '兵要望江南 《周易》占候第二十六（三十七首） 七', '兵要望江南 《周易》占候第二十六（三十七首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["世爲我，應象便爲他。","世尅應兮當我勝，應爻尅世我無家，比者各安家。"]', '["世爲我，應象便爲他。","世尅應兮當我勝，應爻尅世我無家，比者各安家。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d735df-675d-43b9-923a-e850afeddc47', '兵要望江南 《周易》占候第二十六（三十七首） 八', '兵要望江南 《周易》占候第二十六（三十七首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["內卦我，外卦屬他邦。","內尅外時無大損（辛本、川本作「攢捷」），子孫發動急旋（辛本、川本作「施」）張，大戰我軍強。"]', '["內卦我，外卦屬他邦。","內尅外时無大損（辛本、川本作「攢捷」），子孫發动急旋（辛本、川本作「施」）張，大戰我軍強。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9d6490e-b5c5-4887-9c2c-2ae9d06ce155', '兵要望江南 《周易》占候第二十六（三十七首） 九', '兵要望江南 《周易》占候第二十六（三十七首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["官爻動，却在內爻興。","若在子孫傍發動，未（辛本、川本作「雖」）來攻我不曾贏，彼敗怎回程？","（凡占戰，世爲我，應爲他；內爲我，外爲他；子爲我，官爲他；比和者吉。","）。"]', '["官爻动，却在內爻兴。","若在子孫傍發动，未（辛本、川本作「雖」）来攻我不曾贏，彼敗怎回程？","（凡占戰，世爲我，應爲他；內爲我，外爲他；子爲我，官爲他；比和者吉。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d7fdcfd-0d98-42ec-98ff-42c289890500', '兵要望江南 《周易》占候第二十六（三十七首） 十', '兵要望江南 《周易》占候第二十六（三十七首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["子孫動，有氣甚分明。","我若撃他全獲捷，他來攻我敗無門，我將立功勳。"]', '["子孫动，有氣甚分明。","我若撃他全獲捷，他来攻我敗無门，我將立功勳。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('386b2189-46c8-4f7c-a07d-da6e6afdc75e', '兵要望江南 《周易》占候第二十六（三十七首） 十一', '兵要望江南 《周易》占候第二十六（三十七首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占賊信，官鬼上二爻。","無氣動居爻五六，雖然已動不相遭，賊衆自（辛本、川本作「再」）回巢。"]', '["占賊信，官鬼上二爻。","無氣动居爻五六，雖然已动不相遭，賊衆自（辛本、川本作「再」）回巢。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('398e0dca-8385-4023-ac6a-69c76392da6a', '兵要望江南 《周易》占候第二十六（三十七首） 十二', '兵要望江南 《周易》占候第二十六（三十七首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占賊信，鬼發內三中。","或是官爻生有氣，賊軍來速在逡巡，急備點三軍。"]', '["占賊信，鬼發內三中。","或是官爻生有氣，賊軍来速在逡巡，急備点三軍。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028685bf-a6dd-4020-87b6-aaed2c15bff6', '兵要望江南 《周易》占候第二十六（三十七首） 十三', '兵要望江南 《周易》占候第二十六（三十七首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占賊興，卦裏子孫興。","六位官爻全不見，話中空自說來情，不見信和音。","。"]', '["占賊兴，卦裏子孫兴。","六位官爻全不见，話中空自说来情，不见信和音。","。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b8d9ee-4fe8-4057-92bb-7c16b14c1df4', '兵要望江南 《周易》占候第二十六（三十七首） 十四', '兵要望江南 《周易》占候第二十六（三十七首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占賊信，應動是（辛本、川本作「世」）爲他。","其賊來時須（辛本、川本作「雖」）是到，到時攻我將須拿，來將喪黃沙。"]', '["占賊信，應动是（辛本、川本作「世」）爲他。","其賊来时須（辛本、川本作「雖」）是到，到时攻我將須拿，来將喪黄沙。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d7bd016-d91c-468b-9d82-3457da8c8cef', '兵要望江南 《周易》占候第二十六（三十七首） 十五', '兵要望江南 《周易》占候第二十六（三十七首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占賊信，兄弟動如何。","三四爻中他（辛本、川本作「我」）尅我，逡巡來到不蹉跎，到後却安和。"]', '["占賊信，兄弟动如何。","三四爻中他（辛本、川本作「我」）尅我，逡巡来到不蹉跎，到後却安和。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af8033ed-46b2-41a0-8bac-8f9dc246be2f', '兵要望江南 《周易》占候第二十六（三十七首） 十六', '兵要望江南 《周易》占候第二十六（三十七首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占賊信，父母主文書。","若遇吉神天喜位，朝廷加祿永安和，賊智設機多。"]', '["占賊信，父母主文书。","若遇吉神天喜位，朝廷加祿永安和，賊智設機多。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a1e9b0-1385-409b-976c-ec9a46cd8588', '兵要望江南 《周易》占候第二十六（三十七首） 十七', '兵要望江南 《周易》占候第二十六（三十七首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占賊信，卦象動妻財。","天喜來交爻已動，若來相戰見兵乖，我將得和諧。"]', '["占賊信，卦象动妻財。","天喜来交爻已动，若来相戰见兵乖，我將得和諧。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd9bebde-0a00-4127-8ea6-9a7913f002c5', '兵要望江南 《周易》占候第二十六（三十七首） 十八', '兵要望江南 《周易》占候第二十六（三十七首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡占《易》，奇偶與剛柔。","陽爻爲九陰爻六，陽爻多衆我須周，柔少我（辛本作「彼」）軍憂。"]', '["凡占《易》，奇偶與剛柔。","陽爻爲九陰爻六，陽爻多衆我須周，柔少我（辛本作「彼」）軍憂。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d206014d-5ebc-4658-bd6e-267b9ff4a01e', '兵要望江南 《周易》占候第二十六（三十七首） 十九', '兵要望江南 《周易》占候第二十六（三十七首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["入他境，我却用官爻。","官旺子孫休我勝，若煞反此少功勞，術士自詳消。"]', '["入他境，我却用官爻。","官旺子孫休我勝，若煞反此少功勞，術士自詳消。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b196b0e-471a-4bb6-bc0a-ffcfe5f51c7d', '兵要望江南 《周易》占候第二十六（三十七首） 二十', '兵要望江南 《周易》占候第二十六（三十七首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["入他國，大要看財鄉。","子動才興皆出現，處處獲捷有衣糧，飽賞喜還鄉。"]', '["入他国，大要看財乡。","子动才兴皆出現，处处獲捷有衣糧，飽賞喜還乡。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e56ca0-3713-4cae-854f-485dd69f9e2d', '兵要望江南 《周易》占候第二十六（三十七首） 二十一', '兵要望江南 《周易》占候第二十六（三十七首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["爻上見，無鬼又無孫。","但有應方幷世上，以應爲他我世軍，此克定軍情。"]', '["爻上见，無鬼又無孫。","但有應方幷世上，以應爲他我世軍，此克定軍情。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc0a73f-7360-4d51-9a87-3d5ccc0fcdd6', '兵要望江南 《周易》占候第二十六（三十七首） 二十二', '兵要望江南 《周易》占候第二十六（三十七首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["世爻旺，若尅應爻宮。","速便提兵前去吉，自知天助喜重重，主將得奇功。"]', '["世爻旺，若尅應爻宮。","速便提兵前去吉，自知天助喜重重，主將得奇功。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31ee1d26-d411-4969-b35f-280836a0bbda', '兵要望江南 《周易》占候第二十六（三十七首） 二十三', '兵要望江南 《周易》占候第二十六（三十七首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兄獨發，有寇伏埋藏。","且莫提兵行遠路，急行前必有驚惶，不信見灾（辛本、川本作「遭」）殃。"]', '["兄独發，有寇伏埋藏。","且莫提兵行远路，急行前必有驚惶，不信见灾（辛本、川本作「遭」）殃。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7941d36d-53ea-45a4-ac21-76736428c7f1', '兵要望江南 《周易》占候第二十六（三十七首） 二十四', '兵要望江南 《周易》占候第二十六（三十七首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["財（辛本、川本作「賊」）爻動，便是我軍糧。","出國尋糧我軍旺（辛本、川本作「財旺發」），無財難（辛本、川本作「雖」）旺恐饑荒，仔細好推詳（辛本、川本作「半敵遇空亡」）。"]', '["財（辛本、川本作「賊」）爻动，便是我軍糧。","出国尋糧我軍旺（辛本、川本作「財旺發」），無財难（辛本、川本作「雖」）旺恐饑荒，仔細好推詳（辛本、川本作「半敵遇空亡」）。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58540232-e9b2-42bf-b475-5fe123ca2ab4', '兵要望江南 《周易》占候第二十六（三十七首） 二十五', '兵要望江南 《周易》占候第二十六（三十七首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["世若墓，我軍且默（辛本、川本作「執」）屯。","應爻被尅休囚位，來軍必敗損人兵，我衆喜忻忻。"]', '["世若墓，我軍且默（辛本、川本作「執」）屯。","應爻被尅休囚位，来軍必敗損人兵，我衆喜忻忻。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70518158-d441-49fa-8a13-745a6dbb5a39', '兵要望江南 《周易》占候第二十六（三十七首） 二十六', '兵要望江南 《周易》占候第二十六（三十七首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["官臨火，尅我應（辛本、川本作「慮」）偷營。","水立官鄉休立寨，土臨官鬼四方兵，不可（辛本、川本作「一」）亂提兵。"]', '["官臨火，尅我應（辛本、川本作「慮」）偷營。","水立官乡休立寨，土臨官鬼四方兵，不可（辛本、川本作「一」）亂提兵。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a550ebc2-3d1b-4bfe-b308-bc24fb591959', '兵要望江南 《周易》占候第二十六（三十七首） 二十七', '兵要望江南 《周易》占候第二十六（三十七首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["木官（辛本、川本作「宮」）旺，必定有雄兵。","金火不宜臨世應，兩家流血定交爭，火鬼劫吾營（辛本、川本作「軍」）。"]', '["木官（辛本、川本作「宮」）旺，必定有雄兵。","金火不宜臨世應，兩家流血定交爭，火鬼劫吾營（辛本、川本作「軍」）。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe16ed50-cbf1-4234-b238-7de83205220b', '兵要望江南 《周易》占候第二十六（三十七首） 二十八', '兵要望江南 《周易》占候第二十六（三十七首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兄爻尅，防奪我軍糧。","水動舟車火營寨，文書父母合穹蒼（辛本、川本作「倉場」），嚴令下兒郎。","。"]', '["兄爻尅，防奪我軍糧。","水动舟车火營寨，文书父母合穹蒼（辛本、川本作「倉場」），嚴令下兒郎。","。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb78b76-02f3-4844-866f-3cac50c3387d', '兵要望江南 《周易》占候第二十六（三十七首） 二十九', '兵要望江南 《周易》占候第二十六（三十七首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["爻辭位，九六號陰陽。","中半自然皆相守，比和世應兩無傷，各自主刀鎗。"]', '["爻辞位，九六號陰陽。","中半自然皆相守，比和世應兩無傷，各自主刀鎗。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4ab225-21bd-45df-946b-afc513a75078', '兵要望江南 《周易》占候第二十六（三十七首） 三十', '兵要望江南 《周易》占候第二十六（三十七首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["外卦靜，內動見兄爻。","空亡臨象虛驚事，更兼不定事無毫，固守且平交。"]', '["外卦静，內动见兄爻。","空亡臨象虛驚事，更兼不定事無毫，固守且平交。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476c9956-3aed-4176-bf85-25f295a5a850', '兵要望江南 《周易》占候第二十六（三十七首） 三十一', '兵要望江南 《周易》占候第二十六（三十七首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["歸魂卦，三四動爻凶。","若制鬼爻凶轉遂（辛本、川本作「隊」），若逢天喜好回軍，不久却抽兵。"]', '["归魂卦，三四动爻凶。","若制鬼爻凶轉遂（辛本、川本作「隊」），若逢天喜好回軍，不久却抽兵。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e98acd-9bb1-43fd-8a2c-665a18197ae4', '兵要望江南 《周易》占候第二十六（三十七首） 三十二', '兵要望江南 《周易》占候第二十六（三十七首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["《易》之位，六親與五鄉。","外卦世爻子孫旺，三般有氣我無傷，勿要落空亡。"]', '["《易》之位，六親與五乡。","外卦世爻子孫旺，三般有氣我無傷，勿要落空亡。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e369aeed-3073-48ad-958c-34248a93e989', '兵要望江南 《周易》占候第二十六（三十七首） 三十三', '兵要望江南 《周易》占候第二十六（三十七首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凡占課，內動外平安。","動爻無鬼虛驚恐，內爻凶（辛本、川本作「兄」）動稔凶張，術者細參詳。"]', '["凡占課，內动外平安。","动爻無鬼虛驚恐，內爻凶（辛本、川本作「兄」）动稔凶張，術者細參詳。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75590a5b-8562-4f4a-a9a8-2cd591c7fdc7', '兵要望江南 《周易》占候第二十六（三十七首） 三十四', '兵要望江南 《周易》占候第二十六（三十七首） 三十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["外卦動，內卦動興爻。","內外動爻俱動發，若然我戰動鎗刀，大戰殺聲高。"]', '["外卦动，內卦动兴爻。","內外动爻俱动發，若然我戰动鎗刀，大戰殺声高。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('961343e1-4c64-451e-8c6d-3ed1a08f37f6', '兵要望江南 《周易》占候第二十六（三十七首） 三十五', '兵要望江南 《周易》占候第二十六（三十七首） 三十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鬼爻旺，三四動交爻。","定主賊兵侵我陣，急須回首莫相交，動則我軍咷。"]', '["鬼爻旺，三四动交爻。","定主賊兵侵我陣，急須回首莫相交，动則我軍咷。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cffdcd13-c31f-477b-b726-a32f14215639', '兵要望江南 《周易》占候第二十六（三十七首） 三十六', '兵要望江南 《周易》占候第二十六（三十七首） 三十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["四德用，其課我軍強。","春占雷巽寅卯木，夏火巳午得離鄉，此理要知詳（辛本、川本作「當」）。"]', '["四德用，其課我軍強。","春占雷巽寅卯木，夏火巳午得離乡，此理要知詳（辛本、川本作「當」）。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dcb65a5-5c66-44c1-8a54-c19fc142ca49', '兵要望江南 《周易》占候第二十六（三十七首） 三十七', '兵要望江南 《周易》占候第二十六（三十七首） 三十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["秋乾位，申酉喜逢臨（辛本、川本作「相逢」）。","三冬亥子坎宮卦，土旺用事艮和坤，丑未辰戌冲（辛本、川本作「辰中」）。"]', '["秋乾位，申酉喜逢臨（辛本、川本作「相逢」）。","三冬亥子坎宮卦，土旺用事艮和坤，丑未辰戌冲（辛本、川本作「辰中」）。"]', '诗', 'shi', '', NULL, '兵要望江南 《周易》占候第二十六（三十七首） 三十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ed8fc8-5dea-4bbd-b058-25b2c8b6feef', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 一', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太乙式，逆順論陰陽。","五日六時成一局，八門九曜遂（辛本、川本作「逐」）時當，凶吉利門方。"]', '["太乙式，逆順論陰陽。","五日六时成一局，八门九曜遂（辛本、川本作「逐」）时當，凶吉利门方。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c78ca668-24ae-447f-9bb9-0573fd79b736', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["爲術者，太乙式（辛本、川本作「遁」）須知。","起造凶喪須得此，出行蒞任動兵機，用者得便宜。"]', '["爲術者，太乙式（辛本、川本作「遁」）須知。","起造凶喪須得此，出行蒞任动兵機，用者得便宜。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce0e7d12-750f-4d4d-9bfa-fe494a0a40e3', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["出軍日，出門向何方。","開休生門三路吉（川本作「吉路」），一奇臨合自然良，主將得安康。"]', '["出軍日，出门向何方。","开休生门三路吉（川本作「吉路」），一奇臨合自然良，主將得安康。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aed96a1-1366-4b89-a56f-77cf3b2ab346', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 四', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["乙丙丁，名曰是三奇。","天上若臨三吉路，自然神助合天機，任（辛本、川本作「恁」）往莫憂疑。"]', '["乙丙丁，名曰是三奇。","天上若臨三吉路，自然神助合天機，任（辛本、川本作「恁」）往莫憂疑。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b9c682-13e2-40df-a2fa-477a60e2bfc3', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 五', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["九星位，當位（辛本、川本作「住」）八宮方。","惟有中官寄在二，術人運式細消詳，依此我軍強。","。"]', '["九星位，當位（辛本、川本作「住」）八宮方。","惟有中官寄在二，術人運式細消詳，依此我軍強。","。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0bb7f76-0a5f-4a3f-8929-fb1d9be04d9a', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 六', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["甲加丙，龍反首（京本、川本作「首反」）爲先。","丙甲相臨鳥跌穴，時中得此自然全，得勝凱歌旋。"]', '["甲加丙，龙反首（京本、川本作「首反」）爲先。","丙甲相臨鸟跌穴，时中得此自然全，得勝凱歌旋。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9f778b-594f-426c-bd9f-c99b88aed798', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 七', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["太乙遁，月奇合生門。","下有六丁加臨者，此時攝政顯公卿，上策進書呈。"]', '["太乙遁，月奇合生门。","下有六丁加臨者，此时攝政显公卿，上策進书呈。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75b878c6-4a34-4d06-bd01-a59af9866094', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 八', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["開門合，日奇六七（辛本、川本作「乙」）方。","此爲地遁安營吉，藏兵設伏免憂殃，所獻日精長（川本作「良」）。"]', '["开门合，日奇六七（辛本、川本作「乙」）方。","此爲地遁安營吉，藏兵設伏免憂殃，所獻日精长（川本作「良」）。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ff17ac-3a3a-426a-92e9-c6a60a6fadf4', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 九', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["星奇合，休門有蔭人。","舉善薦賢求猛將，和仇說敵哲明言，此法合先賢。"]', '["星奇合，休门有蔭人。","舉善薦賢求猛將，和仇说敵哲明言，此法合先賢。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ccb075-bd23-4a9e-a0a9-648a5f252e22', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["月奇合，生門見九天。","祭禱神祇行聖術，布仇（辛本、川本作「籌」）作法此間言，神遁不虛傳。","（生門月奇合，得九天所臨之位，謂「神遁」。","宜作布籌，行聖術，祭神祇。","）。"]', '["月奇合，生门见九天。","祭禱神祇行聖術，布仇（辛本、川本作「籌」）作法此间言，神遁不虛傳。","（生门月奇合，得九天所臨之位，謂「神遁」。","宜作布籌，行聖術，祭神祇。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a07fe4-4781-4c5a-af95-94472099ad48', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十一', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日奇合，九地見開門。","探審賊機揚虛陣，遙虛設假利偷營，鬼遁隱神兵。"]', '["日奇合，九地见开门。","探審賊機揚虛陣，遙虛設假利偷營，鬼遁隐神兵。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('482d8301-b0ef-4b3c-93e2-c17dae3a6af4', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十二', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["日休幷，九地上加臨。","龍遁祭龍宜水戰，祈求雨澤（辛本、川本作「求」）奏天庭。","掩敵有才能。"]', '["日休幷，九地上加臨。","龙遁祭龙宜水戰，祈求雨澤（辛本、川本作「求」）奏天庭。","掩敵有才能。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56f179e-c94d-4743-960d-ea614aae1707', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十三', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["生門下，辛儀艮位安。","此處一方爲虎遁，招安反賊討交關，將帥總平安。"]', '["生门下，辛儀艮位安。","此处一方爲虎遁，招安反賊討交关，將帥總平安。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dd4e97f-c32c-4c7c-a554-df9ed4cb1c1f', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十四', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["論雲遁，龍走有奇門。","便把鐵礫噴噀酒，令軍佈（辛本、川本作「仰」）望必昇平，雲遁自相陳。"]', '["論云遁，龙走有奇门。","便把鐵礫噴噀酒，令軍佈（辛本、川本作「仰」）望必昇平，云遁自相陳。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d46689-522d-43b8-9e02-7f72d9979aa7', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十五', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["論風遁，白虎號張狂。","運式天星加地乙，祭風起順祝吾邦，此理合天蒼。"]', '["論风遁，白虎號張狂。","運式天星加地乙，祭风起順祝吾邦，此理合天蒼。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea062785-6d7d-4ab6-8c60-e6fe5de7ea18', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十六', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["九天上，大利我軍陳。","九地伏藏宜密事，逃潛六合避凶星，隱伏喜忻情。"]', '["九天上，大利我軍陳。","九地伏藏宜密事，逃潛六合避凶星，隐伏喜忻情。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284f1065-f3c0-4708-88c9-19e2b2beb91a', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十七', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["五不過（辛本、川本作「遇」），甲午丙從辰。","乙日已時丁日卯，更兼戌日在於寅，都是忌行軍。"]', '["五不過（辛本、川本作「遇」），甲午丙從辰。","乙日已时丁日卯，更兼戌日在於寅，都是忌行軍。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f832d4-3d5e-45b9-8afd-c20122d96ca6', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十八', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["五不撃，第一九天方。","九地直符直使位，生門通兵（辛本、川本作「共」）五般傷，此法遁中藏。"]', '["五不撃，第一九天方。","九地直符直使位，生门通兵（辛本、川本作「共」）五般傷，此法遁中藏。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac47fb5-1fbb-4e19-9f88-9921be34bdfd', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十九', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["六儀刑，謀事總難成。","遇着此時遭失陷，奇門雖有也難生（川本作「禁」），大忌用兵行。"]', '["六儀刑，謀事總难成。","遇着此时遭失陷，奇门雖有也难生（川本作「禁」），大忌用兵行。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02108b88-b2ca-43f2-adc9-b5f354e024dd', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["子符使，都忌在三宮。","戌怕冲（辛本、川本作「坤」）宮申在艮，午離酉巽必爲凶，寅與甲辰同。","。"]', '["子符使，都忌在三宮。","戌怕冲（辛本、川本作「坤」）宮申在艮，午離酉巽必爲凶，寅與甲辰同。","。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08fde33c-403a-48a9-9a27-f8341bbbd386', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十一', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["三奇墓，課是沒（辛本、川本作「設」）人多。","好事中間須減（辛本、川本作「滅」）力，奇門雖（辛本、川本作「須」）遇也難過，固守免蹉跎。"]', '["三奇墓，課是沒（辛本、川本作「設」）人多。","好事中间須減（辛本、川本作「滅」）力，奇门雖（辛本、川本作「須」）遇也难過，固守免蹉跎。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfff4e1a-ae37-49c5-a18b-01f56856b6c8', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十二', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["乙奇墓，未上望坤方。","丙奇（辛本、川本作「其」）戍地酉中是，丁奇同位戌乾（辛本、川本作「朝」）張，都是審明方。"]', '["乙奇墓，未上望坤方。","丙奇（辛本、川本作「其」）戍地酉中是，丁奇同位戌乾（辛本、川本作「朝」）張，都是審明方。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d1eb5e-de1b-4082-852c-b3b1995efb95', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十三', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["三奇將，游在六儀中。","子庚丑辛寅乾上，卯壬爲例順行蹤，八方四維宮。"]', '["三奇將，游在六儀中。","子庚丑辛寅乾上，卯壬爲例順行蹤，八方四維宮。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dfcd950-af54-45ca-93ca-9dea3078ad98', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十四', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["六癸丁，天網四張時。","舉用所謀皆不定，周天網者有高低，坎地一宮隨。"]', '["六癸丁，天網四張时。","舉用所謀皆不定，周天網者有高低，坎地一宮隨。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87958385-3d65-4b72-9ef5-abd671601e91', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十五', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["如急難，事速要（辛本、川本作「爲」）逃之。","刀刃對肩居左右，行過六十步無疑，此事要君知。"]', '["如急难，事速要（辛本、川本作「爲」）逃之。","刀刃对肩居左右，行過六十步無疑，此事要君知。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e424568c-43ac-44c0-99d2-58f19f0e85c4', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十六', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["開門照，六戊（辛本、川本作「戌」）合奇門。","前程（辛本、川本作「門」）貴客相伏（辛本、川本作「扶」）助，陰人酒肉待相迎，拜訪喜忻忻。"]', '["开门照，六戊（辛本、川本作「戌」）合奇门。","前程（辛本、川本作「门」）貴客相伏（辛本、川本作「扶」）助，陰人酒肉待相迎，拜訪喜忻忻。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c710feb4-0283-4066-b323-0f59fc3ee86c', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十七', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["休門外，喜笑得錢財。","出門（辛本、川本作「外」）三旬五十里，蛇鼠陰人及小孩，出外免無厄（辛本、川本作「定無災」）。"]', '["休门外，喜笑得錢財。","出门（辛本、川本作「外」）三旬五十里，蛇鼠陰人及小孩，出外免無厄（辛本、川本作「定無災」）。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d81ef7e7-1f00-4ee1-8839-81fff260164b', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十八', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["生門上，三奇合此門。","公吏官人生紫皂，逢之軍馬六三程，特應與軍門。"]', '["生门上，三奇合此门。","公吏官人生紫皂，逢之軍马六三程，特應與軍门。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('404ece23-7f62-4a8a-b417-9530504fb913', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十九', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["傷門內，捕盜可移趨。","杜門有難前潛吉，景門凡事不安居，獻策稍通疎。"]', '["傷门內，捕盜可移趨。","杜门有难前潛吉，景门凡事不安居，獻策稍通疎。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17ffd9fc-70ea-40e2-86df-0cd0f5a95f47', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三十', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["死門上，攻戰莫（辛本、川本作「要」）逢之。","出臘（辛本、川本作「獵」）更宜朝北（辛本、川本作「此」）向，若還征戰賊亡威（辛本、川本作「滅」），決勝要逢之。"]', '["死门上，攻戰莫（辛本、川本作「要」）逢之。","出臘（辛本、川本作「獵」）更宜朝北（辛本、川本作「此」）向，若還征戰賊亡威（辛本、川本作「滅」），決勝要逢之。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209f7d6d-0314-48cc-8d68-201ea7eba0f4', '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三十一', '兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["驚門路，捕盜捉逃亡。","出行一二十里路，路道不通鵲噪狂，論訟喜公方。"]', '["驚门路，捕盜捉逃亡。","出行一二十里路，路道不通鵲噪狂，論訟喜公方。"]', '诗', 'shi', '', NULL, '兵要望江南 太乙式第二十七（本門中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e002246c-10f7-4b41-bd15-fa624040a443', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 一', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["看行動，只取（京本作「在」）日辰推。","若在貴人前實是（京本作「是實」），三傳同去此（辛本、川本作「此去」）無（京本作「此不須」）疑，反此却難移。"]', '["看行动，只取（京本作「在」）日辰推。","若在貴人前實是（京本作「是實」），三傳同去此（辛本、川本作「此去」）無（京本作「此不須」）疑，反此却难移。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc5c611-cd5c-45f2-abc6-d0e59d4dc8d3', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["看天馬，辰戌亦同前。","（京本注：「魁罡也。","」）若在支干（京本作「干支」）應空（辛本、川本、京本作「定」）發，更還加季不（京本作「主」）留連，人馬鬧（京本作「更」）喧喧。"]', '["看天马，辰戌亦同前。","（京本注：「魁罡也。","」）若在支干（京本作「干支」）應空（辛本、川本、京本作「定」）發，更還加季不（京本作「主」）留連，人马鬧（京本作「更」）喧喧。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('777fbb30-9ab6-4252-85a7-921107be99bf', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占虛實，後六作天空。","若在干支虛事定，天空爲煞最朦朧，虛妄禍（辛本、川本作「更」、京本作「更望更」）重重。"]', '["占虛實，後六作天空。","若在干支虛事定，天空爲煞最朦朧，虛妄禍（辛本、川本作「更」、京本作「更望更」）重重。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de86e2da-d617-4388-991b-64b40579a109', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占主客，勝負蚤須知。","甲乙丙丁幷戊子（辛本、川本作「己」、京本作「字」），陽時出戰主凶危，此事決（京本作「定」）無疑。"]', '["占主客，勝負蚤須知。","甲乙丙丁幷戊子（辛本、川本作「己」、京本作「字」），陽时出戰主凶危，此事決（京本作「定」）無疑。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03135240-a4ea-440c-87bd-787b6841ad98', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 五', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占宿次，今夜定如何。","太乙天罡太衝上，支干見者恐奔過（京本作「波」），準（辛本、川本、京本作「整」）備禦兵戈（京本作「預防他」）。"]', '["占宿次，今夜定如何。","太乙天罡太衝上，支干见者恐奔過（京本作「波」），準（辛本、川本、京本作「整」）備禦兵戈（京本作「預防他」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba6df73c-7f11-4349-b541-4d022c50eadc', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 六', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["看歲月，沖破時（辛本、川本、京本作「下」）推之。","上將行年居此位（辛本、川本、京本作「下」），師行（辛本、京本作「侯」）身必有凶危，禳厭始無虧。","（月將加所得之時，看支干上見魁罡星者主驚潰。","將帥行年上見魁罡者宜禳之。","）。"]', '["看歲月，沖破时（辛本、川本、京本作「下」）推之。","上將行年居此位（辛本、川本、京本作「下」），師行（辛本、京本作「侯」）身必有凶危，禳厭始無虧。","（月將加所得之时，看支干上见魁罡星者主驚潰。","將帥行年上见魁罡者宜禳之。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f452bbbe-1dea-450a-810f-330a74ce0687', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 七', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["看六害，用將及傳中。","若見定知他捷（京本作「健」）利，更兼惡（京本作「月」）將定重凶，不鬬却無凶（京本作「爲雄」）。"]', '["看六害，用將及傳中。","若见定知他捷（京本作「健」）利，更兼惡（京本作「月」）將定重凶，不鬬却無凶（京本作「爲雄」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a418ef09-25a8-43b8-8fac-d5cde587cfb4', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 八', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["後三五，前四將年辰。","若被日衝兼被（辛本、川本作「破」）害，被刑之（辛本、川本作「亡」）者負於人，好記認爲真。"]', '["後三五，前四將年辰。","若被日衝兼被（辛本、川本作「破」）害，被刑之（辛本、川本作「亡」）者負於人，好記認爲真。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc9db9f-295b-4355-88be-8284a84d8359', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 九', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["參詳取，太歲頭上（京本作「上頭」）神。","若尅貴（京本作「能責」）人虛詐事，太陰六合（辛本、川本作「後」、京本作「神后」）僞爲（京本作「非」）真，防備見傷人。"]', '["參詳取，太歲头上（京本作「上头」）神。","若尅貴（京本作「能責」）人虛詐事，太陰六合（辛本、川本作「後」、京本作「神后」）僞爲（京本作「非」）真，防備见傷人。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a39bd9e-b4f6-40a5-9659-c5a132ce3b4e', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["聞賊去，大吉是其元。","若在干（辛本、川本、京本作「前」）時應末去，若臨干（辛本、川本、京本作「賊」）後是虛傳，勿聽此狂言。"]', '["闻賊去，大吉是其元。","若在干（辛本、川本、京本作「前」）时應末去，若臨干（辛本、川本、京本作「賊」）後是虛傳，勿听此狂言。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01ba13c4-f92b-4e21-aaa8-95774338efb4', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十一', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["他軍走（京本作「是」），虛實（辛本、川本、京本作「的」）好參陳。","神克日辰天馬併，傳揚定去必無人，此兆決然真。","。"]', '["他軍走（京本作「是」），虛實（辛本、川本、京本作「的」）好參陳。","神克日辰天马併，傳揚定去必無人，此兆決然真。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8632507-aa54-4001-82c4-3b019dca004e', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十二', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["經險路，惟是（京本作「則」、辛本、川本作「爲則」）忌天罡。","加孟前行喜（辛本、川本、京本作「應」）不喜，罡臨四仲己中傷，加季後（京本作「復」）逃亡。"]', '["經險路，惟是（京本作「則」、辛本、川本作「爲則」）忌天罡。","加孟前行喜（辛本、川本、京本作「應」）不喜，罡臨四仲己中傷，加季後（京本作「复」）逃亡。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('369b3459-b0b8-4a70-bff3-512c49cfcaf6', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十三', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["兵行次，四季獄神凶。","春卯（京本注：「夏午。","」）順（京本注：「四季。","」）雷（京本作「來」）居震位，辰年艮（京本作「日辰年」）上忌相逢，臨着失勳功。"]', '["兵行次，四季獄神凶。","春卯（京本注：「夏午。","」）順（京本注：「四季。","」）雷（京本作「来」）居震位，辰年艮（京本作「日辰年」）上忌相逢，臨着失勳功。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2240606e-3a57-4c58-9715-07ed58db181d', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十四', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["遊都將，併殺又重傷。","若遇德鄉神幷合（京本、辛本、川本作「神幷合將」），加臨不尅又加（京本作「有嘉」）祥，降虜我軍強。"]', '["游都將，併殺又重傷。","若遇德乡神幷合（京本、辛本、川本作「神幷合將」），加臨不尅又加（京本作「有嘉」）祥，降虜我軍強。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d62d1b8-0a13-44dd-acb5-f315c4e3deec', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十五', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["遊都將，克日至行年。","約束（京本作「若屬」）我軍牢固守，若（辛本、川本作「莫」）教見陣必遭愆（京本作「邅」），不鬬却爲賢。"]', '["游都將，克日至行年。","約束（京本作「若屬」）我軍牢固守，若（辛本、川本作「莫」）教见陣必遭愆（京本作「邅」），不鬬却爲賢。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76277381-48a2-4877-8d10-d8888b095f6e', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十六', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["主年上，須要克遊都。","克得此宮爲大勝，多應擒捉賊（京本作「客」）酋徒，半虜半降誅。"]', '["主年上，須要克游都。","克得此宮爲大勝，多應擒捉賊（京本作「客」）酋徒，半虜半降誅。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357175b0-2bd6-452d-ae04-7d352f6482ac', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十七', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["遊都將，玄武與勾陳。","白虎年將須穩審（辛本、川本作「害」），休囚絕氣不傷人，旺相却（京本作「即」）殘身。"]', '["游都將，玄武與勾陳。","白虎年將須穩審（辛本、川本作「害」），休囚絕氣不傷人，旺相却（京本作「即」）殘身。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae10c43d-4e22-43b6-b210-30296061b400', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十八', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["玄武將，斷例與前同。","無克後三皆大勝，後三來（京本作「未」）克主皆凶，却是（京本作「試」）審其中。"]', '["玄武將，斷例與前同。","無克後三皆大勝，後三来（京本作「未」）克主皆凶，却是（京本作「試」）審其中。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d9b3d3-37af-4bc5-90a6-941f18f97686', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十九', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["勾陳將，忌克主行年。","若克行年多敗死，行年無（京本作「多」）克見勳全，審細去參詮。","（勾陳克玄武，主勝。","）。"]', '["勾陳將，忌克主行年。","若克行年多敗死，行年無（京本作「多」）克见勳全，審細去參詮。","（勾陳克玄武，主勝。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09dac101-b2aa-43a7-b0aa-e38ba138db83', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["凶神將，又克主行年。","若遇行年克前四，此是交戰（京本作「勝」）勝當先，喜躍信（京本作「作」）超（辛本、川本作「趨」）前。"]', '["凶神將，又克主行年。","若遇行年克前四，此是交戰（京本作「勝」）勝當先，喜躍信（京本作「作」）超（辛本、川本作「趨」）前。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61938ab1-52eb-420d-87a8-73939b7a8229', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十一', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍勝負，六害卦中凶。","更作惡神幷惡將，直須固守候時（辛本、川本、京本作「晴」）風，懼（辛本、川本、京本作「俱」）慎莫前沖。"]', '["軍勝負，六害卦中凶。","更作惡神幷惡將，直須固守候时（辛本、川本、京本作「晴」）风，懼（辛本、川本、京本作「俱」）慎莫前沖。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e93eb489-0ea7-474f-bade-5e099c68c168', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十二', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["遊都將，臨日在如今。","辰上見之明日是，支干不見（辛本、川本作「是」）用前神，三二是朝迍。","。"]', '["游都將，臨日在如今。","辰上见之明日是，支干不见（辛本、川本作「是」）用前神，三二是朝迍。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cb113d7-2a97-465c-91a4-4a72d1a642dc', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十三', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["聞賊去，仔細驗天罡。","若在孟方猶未去，忽然加仲已商量，加季發他鄉。"]', '["闻賊去，仔細驗天罡。","若在孟方猶未去，忽然加仲已商量，加季發他乡。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3263917a-5d1c-4a26-832a-51e6c141a37f', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十四', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["三傳將，遙日（辛本、川本、京本作「見」）覓支干。","將見支干休進戰，三神被克我軍（京本作「神」）安，必獲彼旗旛。"]', '["三傳將，遙日（辛本、川本、京本作「见」）覓支干。","將见支干休進戰，三神被克我軍（京本作「神」）安，必獲彼旗旛。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b1e300e-3e78-419a-ba1d-a6bd1dc1bdb6', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十五', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["課中惡，忌見戰雌神。","傳送是春登明夏，秋寅冬巳愛傷人，日與喜神親（京本作「發動愈重迍」）。"]', '["課中惡，忌见戰雌神。","傳送是春登明夏，秋寅冬巳愛傷人，日與喜神親（京本作「發动愈重迍」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84776017-62ac-47a9-a21d-337aedd316a9', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十六', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["行軍（京本作「兵」）課，惟有伏吟時。","兵伏自然軍勿進，預憂中道有儉（京本作「陰」）奇，審課要知機。"]', '["行軍（京本作「兵」）課，惟有伏吟时。","兵伏自然軍勿進，預憂中道有儉（京本作「陰」）奇，審課要知機。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64374d95-ecca-49c0-a7d4-21799f40d96d', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十七', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["行兵（京本作「軍」）課，切忌反吟凶。","若遇喜神應解退，惡神立敗禍來衝。","反覆我軍中。"]', '["行兵（京本作「軍」）課，切忌反吟凶。","若遇喜神應解退，惡神立敗禍来衝。","反覆我軍中。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f6f315-92d9-4065-82ee-80fb707c65fc', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十八', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["熒惑煞，只是丙丁神。","加在金方兵已退，亦無征戰不傷人，發動愈重迍（京本作「日與喜神親」）。"]', '["熒惑煞，只是丙丁神。","加在金方兵已退，亦無征戰不傷人，發动愈重迍（京本作「日與喜神親」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c94f1ae-2f4d-449d-9370-bf7f57b358e9', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十九', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["看課內，太白是庚辛。","若在東方奸賊至，天罡加孟急（京本作「疾」）如神，警備要專勤。"]', '["看課內，太白是庚辛。","若在东方奸賊至，天罡加孟急（京本作「疾」）如神，警備要專勤。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c56f4d4-9234-4669-8da4-c311ce9dc7e0', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["課中聖，惟是戰雄併。","四季孟神雄將位（與戰對沖是也），若居喜將得相生，旺相更爲榮。"]', '["課中聖，惟是戰雄併。","四季孟神雄將位（與戰对沖是也），若居喜將得相生，旺相更爲榮。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de11146d-c043-4f8d-a844-07d74af0d495', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十一', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["看課上，與下要相生。","上克下兮須損失，逢占惡將（京本作「要逢虛將」）必須驚，喜（京本作「吉」）將喜無爭。"]', '["看課上，與下要相生。","上克下兮須損失，逢占惡將（京本作「要逢虛將」）必須驚，喜（京本作「吉」）將喜無爭。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bfe5e0f-202a-4643-9f1c-eb05197ef4df', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十二', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["何煞重，天狗是其殃。","無殺福神相次惡，天雷併者是（京本作「也」）無妨，三殺可商量（京本作「參商」）。"]', '["何煞重，天狗是其殃。","無殺福神相次惡，天雷併者是（京本作「也」）無妨，三殺可商量（京本作「參商」）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1471a437-1fa8-4ece-9cc7-455fffaf4180', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十三', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["勾陳將，玄武共相親。","帶煞併加爲惡煞，若逢相克不宜軍（京本作「君」），有煞便相侵。"]', '["勾陳將，玄武共相親。","带煞併加爲惡煞，若逢相克不宜軍（京本作「君」），有煞便相侵。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284653cc-cc67-4c0f-afbb-0db0e95a12d8', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十四', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["三刑內，最惡是天罡。","或是季兮爲日上，沖加四煞必相傷，夜即恐驚忙（京本作「亡」。","魁罡臨日，主大將死，臨辰，主小將死，日辰俱臨，俱死。","）。"]', '["三刑內，最惡是天罡。","或是季兮爲日上，沖加四煞必相傷，夜即恐驚忙（京本作「亡」。","魁罡臨日，主大將死，臨辰，主小將死，日辰俱臨，俱死。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e657157b-7b10-45d2-ad5c-376615c5dbc1', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十五', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["課驚怖，日上細尋推。","辰巳太沖加日上，若逢蛇雀見凶危，復手也如之。","（大吉加日，宜急去，不可住，辰上見太沖，夜必有風雨，若神後太乙加日辰，夜有賊盜。","旺相必見，無氣則不見。","）。"]', '["課驚怖，日上細尋推。","辰巳太沖加日上，若逢蛇雀见凶危，复手也如之。","（大吉加日，宜急去，不可住，辰上见太沖，夜必有风雨，若神後太乙加日辰，夜有賊盜。","旺相必见，無氣則不见。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2700df4c-abd8-44ab-8f2d-0ef7366f0a2d', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十六', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["課驚怖，辰巳卯三辰。","無殺相併天馬併，用之發課不宜人，虛殺總相親。","。"]', '["課驚怖，辰巳卯三辰。","無殺相併天马併，用之發課不宜人，虛殺總相親。","。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f03456b-9336-4846-a3f0-71c948cd38c0', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十七', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["移伏起，陽日在中傳。","陰則未傳君記取，覺知如此見由緣，照處是推源。"]', '["移伏起，陽日在中傳。","陰則未傳君記取，覺知如此见由緣，照处是推源。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55b78f4-2cdd-4efd-b3a2-bc56f6c8ad37', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十八', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["欲捕捉，玄武定三傳。","相克三傳皆捉得，相生不克是無緣，好記不虛言。"]', '["欲捕捉，玄武定三傳。","相克三傳皆捉得，相生不克是無緣，好記不虛言。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364ddf96-46b0-4a68-ac1d-7539eb0f1754', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十九', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["三傳克，克日易前擒。","快（京本作「決」）出疾行方始得，奸人移伏恐軍侵，離日却難尋。"]', '["三傳克，克日易前擒。","快（京本作「決」）出疾行方始得，奸人移伏恐軍侵，離日却难尋。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06389191-622a-4062-8ed0-1c8a7cf07da5', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["傳課中（京本作「內」），蛇雀與勾陳。","蛇主虛驚雀主火，亦兼音信又公文。","仔細好推論。"]', '["傳課中（京本作「內」），蛇雀與勾陳。","蛇主虛驚雀主火，亦兼音信又公文。","仔細好推論。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e716b96f-6f82-463e-94de-f9823af86e21', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十一', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["傳白虎，相克戰傷人。","無氣不傷途死損，天空依舊（京本作「積」）是空陳，旺處是窮貧。"]', '["傳白虎，相克戰傷人。","無氣不傷途死損，天空依旧（京本作「積」）是空陳，旺处是窮貧。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4980e95-6646-491a-b1d6-182f73e05657', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十二', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["占行路，逐日定占之。","有氣青龍並六合，錢財倉庫定無疑，多獲綵縑持。"]', '["占行路，逐日定占之。","有氣青龙並六合，錢財倉庫定無疑，多獲綵縑持。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c2e07b9-7dcf-4949-9a7a-e26df13bf74b', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十三', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將一二，兼持（京本作「赤」）忌勾陳。","若見後三幷五六，因爲發卦不宜軍，進步必遭迍。"]', '["將一二，兼持（京本作「赤」）忌勾陳。","若见後三幷五六，因爲發卦不宜軍，進步必遭迍。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b0e4a7-ac47-46f8-ba79-9889c9c475fa', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十四', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["將軍吏，支干審占之。","大吉小吉支干上，天罡加孟以同推，不戰兩無疑。"]', '["將軍吏，支干審占之。","大吉小吉支干上，天罡加孟以同推，不戰兩無疑。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69715966-13be-4153-99c8-8a60809e7f3e', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十五', '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["後五六，即是我軍傷。","六帥有人虛詐說，日辰不克也無妨，克日不宜良。"]', '["後五六，即是我軍傷。","六帥有人虛詐说，日辰不克也無妨，克日不宜良。"]', '诗', 'shi', '', NULL, '兵要望江南 占六壬第二十八（京本列第十七○四十五首） 四十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1798594-95a6-451d-b08c-825e64c48fba', '兵要望江南 醫方第二十九（十六首） 一', '兵要望江南 醫方第二十九（十六首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["衆軍聚，駐札已經時。","多有相蒸人（辛本、川本作「多」）氣鬱，使軍疫瘴見灾危，一一與君知。"]', '["衆軍聚，駐札已經时。","多有相蒸人（辛本、川本作「多」）氣鬱，使軍疫瘴见灾危，一一與君知。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11956ec-1a97-43e5-abb7-2e404d2cdb46', '兵要望江南 醫方第二十九（十六首） 二', '兵要望江南 醫方第二十九（十六首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["如瘴氣，鶻骨火燒將。","便去上風焚此物，衆人聞此滅灾殃，從此得安康。"]', '["如瘴氣，鶻骨火燒將。","便去上风焚此物，衆人闻此滅灾殃，從此得安康。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755657ab-2ab8-43a5-aa4e-e96e69e36205', '兵要望江南 醫方第二十九（十六首） 三', '兵要望江南 醫方第二十九（十六首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["轉筋脚，急去使生薑。","新水一鍾煎五合，飲之即去總無妨，主將記心腸。"]', '["轉筋脚，急去使生薑。","新水一鍾煎五合，饮之即去總無妨，主將記心腸。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a00607cf-9e22-45a6-9b4c-84ecee29a78f', '兵要望江南 醫方第二十九（十六首） 四', '兵要望江南 醫方第二十九（十六首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金刃重，速翦馬牛毛。","二件一同燒作末，敷之血止自然消，皮血便堅牢。"]', '["金刃重，速翦马牛毛。","二件一同燒作末，敷之血止自然消，皮血便堅牢。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b723dc0b-6ed2-4667-96c3-54df580cbf81', '兵要望江南 醫方第二十九（十六首） 五', '兵要望江南 醫方第二十九（十六首） 五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金傷者，香白芷爲靈。","細嚼噀敷瘡口上，更將暖酒飲七分（辛本作「酒下七分功」），細說與君聽。"]', '["金傷者，香白芷爲靈。","細嚼噀敷瘡口上，更將暖酒饮七分（辛本作「酒下七分功」），細说與君听。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc37ac38-c3a4-47e8-9317-58cb95f825f8', '兵要望江南 醫方第二十九（十六首） 六', '兵要望江南 醫方第二十九（十六首） 六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金傷者，甚渴急（辛本作「即」）非常。","切忌休將水與飲，飲之必定有乖張，肥膩即無妨。","。"]', '["金傷者，甚渴急（辛本作「即」）非常。","切忌休將水與饮，饮之必定有乖張，肥膩即無妨。","。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bddad09-d383-45c4-abe1-24d1fe299a5d', '兵要望江南 醫方第二十九（十六首） 七', '兵要望江南 醫方第二十九（十六首） 七', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金傷處，傷腦及天蒼（辛本作「倉」）。","臂中脈跳幷心內，鳩尾五臟小腹胱。","醫者不能當。"]', '["金傷处，傷腦及天蒼（辛本作「倉」）。","臂中脈跳幷心內，鳩尾五臟小腹胱。","醫者不能當。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 七 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b5499d5-9639-4494-808c-bad8cb1f4593', '兵要望江南 醫方第二十九（十六首） 八', '兵要望江南 醫方第二十九（十六首） 八', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金傷者，腦髓出非常。","頸咽喉中聲沸者，兩目直視痛難當，血似水流（辛本作「泉」）塘。","（似此，皆不治而難醫也。","）。"]', '["金傷者，腦髓出非常。","頸咽喉中声沸者，兩目直視痛难當，血似水流（辛本作「泉」）塘。","（似此，皆不治而难醫也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 八 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4580e857-17d3-4c58-a726-b3b5532b69c4', '兵要望江南 醫方第二十九（十六首） 九', '兵要望江南 醫方第二十九（十六首） 九', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["金瘡法，閒時備急方。","五月五日平明節，採其諸草搗成漿，石灰共作湯。"]', '["金瘡法，閒时備急方。","五月五日平明節，採其諸草捣成漿，石灰共作湯。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 九 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c85799-9170-4748-956e-53d63dff1509', '兵要望江南 醫方第二十九（十六首） 十', '兵要望江南 醫方第二十九（十六首） 十', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["遭毒箭，更兼馬汗方。","大頭蝱蟲端午取，去翅陰乾爲末霜。","挑破藥敷瘡。","（次用醋打麵糊紙壓瘡口上，即追出毒氣也。","）。"]', '["遭毒箭，更兼马汗方。","大头蝱蟲端午取，去翅陰乾爲末霜。","挑破藥敷瘡。","（次用醋打麵糊紙壓瘡口上，即追出毒氣也。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 十 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77936bc9-00a0-4cb7-9998-624a6243727f', '兵要望江南 醫方第二十九（十六首） 十一', '兵要望江南 醫方第二十九（十六首） 十一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍或患，發背及癰疽。","人屎糞盤下潤土，碾細篩羅貼敷之，猪膽共調施。"]', '["軍或患，發背及癰疽。","人屎糞盤下潤土，碾細篩羅貼敷之，猪膽共調施。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 十一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bebf91b-4f4d-4ed1-8dda-7eec48762cb8', '兵要望江南 醫方第二十九（十六首） 十二', '兵要望江南 醫方第二十九（十六首） 十二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["人霍亂，吐瀉有方高。","生薑二（辛本作「三」）兩須炮過，芭蕉一兩去皮熬，五兩大黃燒。","（大黃炒過爲末，蜜爲丸，如梧桐子大，每服三丸，以利爲度；如不利，以米粥投藥。","）。"]', '["人霍亂，吐瀉有方高。","生薑二（辛本作「三」）兩須炮過，芭蕉一兩去皮熬，五兩大黄燒。","（大黄炒過爲末，蜜爲丸，如梧桐子大，每服三丸，以利爲度；如不利，以米粥投藥。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 十二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29242f6-2a91-48cc-940d-c29cddc2d35a', '兵要望江南 醫方第二十九（十六首） 十三', '兵要望江南 醫方第二十九（十六首） 十三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["急喉閉，青艾汁須靈。","滴下自消血破出，逡巡不救損於人，切記在心勤。"]', '["急喉閉，青艾汁須靈。","滴下自消血破出，逡巡不救損於人，切記在心勤。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 十三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ac9c74-e9ba-44d6-b6f4-7239b9ed836d', '兵要望江南 醫方第二十九（十六首） 十四', '兵要望江南 醫方第二十九（十六首） 十四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["冬月內，無葉艾枝枯。","草內急尋蛇牀子，燒烟入中自消除，速救免灾虞。"]', '["冬月內，無葉艾枝枯。","草內急尋蛇牀子，燒烟入中自消除，速救免灾虞。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 十四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db486195-0b9d-490f-bf3a-178ad1c3d657', '兵要望江南 醫方第二十九（十六首） 十五', '兵要望江南 醫方第二十九（十六首） 十五', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["軍人衆，涉水冒霜多。","手脚面皮皆裂拆，麥葉濃煮汁相過，熱洗即安和。"]', '["軍人衆，涉水冒霜多。","手脚面皮皆裂拆，麦葉濃煮汁相過，熱洗即安和。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 十五 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ec9908-c73b-4201-9a70-f20d32701ef6', '兵要望江南 醫方第二十九（十六首） 十六', '兵要望江南 醫方第二十九（十六首） 十六', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["山瘴氣，嵐谷用恒山。","獨頭大蒜烏梅肉，速將酒煮便能痊，謹記此良言。","（恒山二兩，獨頭蒜一兩，烏梅二十枚，咬咀，用酒二盞，煎至一大盞，分爲二服。","初一服未發時喫，次一服已發時喫。","）。"]', '["山瘴氣，嵐谷用恒山。","独头大蒜烏梅肉，速將酒煮便能痊，謹記此良言。","（恒山二兩，独头蒜一兩，烏梅二十枚，咬咀，用酒二盞，煎至一大盞，分爲二服。","初一服未發时喫，次一服已發时喫。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 醫方第二十九（十六首） 十六 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7faa53a-2be6-4161-8a2f-b71c43964a6e', '兵要望江南 馬藥方第三十（四首） 一', '兵要望江南 马藥方第三十（四首） 一', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["常灌馬，黃柏與黃連。","升麻大黃山梔子，胡鹽青黛鬱金仙，等分勿令偏。"]', '["常灌马，黄柏與黄連。","升麻大黄山梔子，胡鹽青黛鬱金仙，等分勿令偏。"]', '诗', 'shi', '', NULL, '兵要望江南 馬藥方第三十（四首） 一 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4ece68-68da-403f-b499-bedcd0bc001d', '兵要望江南 馬藥方第三十（四首） 二', '兵要望江南 马藥方第三十（四首） 二', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["相馬法，要試歲年何。","鼻上金字十八歲，四字八歲不年多，八字四年過。","。"]', '["相马法，要試歲年何。","鼻上金字十八歲，四字八歲不年多，八字四年過。","。"]', '诗', 'shi', '', NULL, '兵要望江南 馬藥方第三十（四首） 二 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8ed22d-69ba-48ae-bf84-006d15394f1f', '兵要望江南 馬藥方第三十（四首） 三', '兵要望江南 马藥方第三十（四首） 三', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["鼻上赤，二十歲無零。","馬鼻若青三十歲，公字雖（辛本作「須」）當念五乘，此象最（辛本作「甚」）分明。"]', '["鼻上赤，二十歲無零。","马鼻若青三十歲，公字雖（辛本作「須」）當念五乘，此象最（辛本作「甚」）分明。"]', '诗', 'shi', '', NULL, '兵要望江南 馬藥方第三十（四首） 三 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('347beee2-bdc1-488b-b7c6-4cd4c6b06816', '兵要望江南 馬藥方第三十（四首） 四', '兵要望江南 马藥方第三十（四首） 四', 'e51d2eb3-c4d9-429b-abb8-6ada87be9fe9', '唐', '["馬瘟病，急取獺之肝。","肚內將來去屎洗，煮汁啖灌便平安。","牢記在心間。","（按：以上易靜詞四卷，凡七百二十一首，均見於《兵要望江南》一書。","《崇文總目》卷三著錄於《子部·兵家類》：「《神機武略兵要望江南詞》一卷。","」《郡齋讀書後志》卷二《兵類》云：「《兵要望江南》一卷。","右題云黃石公以授張良者。","按其書雜占行軍吉凶，寓聲於《望江南》詞，取其易記憶。","《總目》云：『武安軍左押衙易靜撰。","』蓋唐人也。","」《總目》即《崇文總目》，今本已失解題，錢侗校本據以補出。","檢《新唐書》卷六九《方鎮表》：光啓元年「改欽化軍節度爲武安軍節度使」。","因知易靜應爲唐末人。","今所據凡四本：其一爲明辛自修刊本〖簡稱辛本〗，刊於萬曆十年，今藏北京圖書館；其二爲四川省圖書館藏清初鈔本〖簡稱川本〗，此本錯別字較多，文字較近於辛本；其三，首都圖書館藏鈔本〖簡稱首本〗，題作《李衛公望江南》，分上下兩卷；其四爲北京圖書館收藏前京師圖書館舊鈔本〖簡稱京本〗，附跋云：「此從明督浙江都御史晉江蘇茂相校本錄出，題作《白猿奇書兵法雜占彖詞》，唐開府儀同三司衛公三原李靖著。","」首本、川本、辛本均爲足本，但均有所殘缺。","京本則僅存五百首，但有十餘首不見於前三本，文字亦差異較大。","今以首本爲底本，以辛本、川本、京本校補。","首本、辛本、川本皆據任半塘先生與王小盾同志合編《隋唐五代燕樂雜言歌辭集》〖稿本〗轉引，京本則轉引自張璋、黃畬編《全唐五代詞》。","）。"]', '["马瘟病，急取獺之肝。","肚內將来去屎洗，煮汁啖灌便平安。","牢記在心间。","（按：以上易静词四卷，凡七百二十一首，均见於《兵要望江南》一书。","《崇文總目》卷三著錄於《子部·兵家類》：「《神機武略兵要望江南词》一卷。","」《郡斋读书後志》卷二《兵類》云：「《兵要望江南》一卷。","右題云黄石公以授張良者。","按其书杂占行軍吉凶，寓声於《望江南》词，取其易記憶。","《總目》云：『武安軍左押衙易静撰。","』蓋唐人也。","」《總目》即《崇文總目》，今本已失解題，錢侗校本據以補出。","檢《新唐书》卷六九《方鎮表》：光啓元年「改欽化軍節度爲武安軍節度使」。","因知易静應爲唐末人。","今所據凡四本：其一爲明辛自修刊本〖簡稱辛本〗，刊於万曆十年，今藏北京圖书館；其二爲四川省圖书館藏清初鈔本〖簡稱川本〗，此本錯別字較多，文字較近於辛本；其三，首都圖书館藏鈔本〖簡稱首本〗，題作《李衛公望江南》，分上下兩卷；其四爲北京圖书館收藏前京師圖书館旧鈔本〖簡稱京本〗，附跋云：「此從明督浙江都御史晉江蘇茂相校本錄出，題作《白猿奇书兵法杂占彖词》，唐开府儀同三司衛公三原李靖著。","」首本、川本、辛本均爲足本，但均有所殘缺。","京本則僅存五百首，但有十餘首不见於前三本，文字亦差異較大。","今以首本爲底本，以辛本、川本、京本校補。","首本、辛本、川本皆據任半塘先生與王小盾同志合編《隋唐五代燕乐杂言歌辞集》〖稿本〗轉引，京本則轉引自張璋、黄畬編《全唐五代词》。","）。"]', '诗', 'shi', '', NULL, '兵要望江南 馬藥方第三十（四首） 四 易靜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f770cb-afc3-42e9-9592-d85c65313841', '鳴山', '鳴山', '9b9fb2c9-99a7-48b8-97b4-5e291abf1f0c', '唐', '["天下名山有，未聞山自鳴。","昂藏如許濶，爾何亦不平。","（見同治丙寅刊齊召南等纂《溫州府志》卷四《山川》。","）（按：《宋詩紀事補遺》卷八八誤收羅袞此詩入事迹無考作者。","）。"]', '["天下名山有，未闻山自鳴。","昂藏如許濶，爾何亦不平。","（见同治丙寅刊齊召南等纂《溫州府志》卷四《山川》。","）（按：《宋诗紀事補遺》卷八八誤收羅袞此诗入事迹無考作者。","）。"]', '诗', 'shi', '', NULL, '鳴山 羅袞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5191f558-339e-4d52-b6e4-651659e8f22e', '句', '句', '9b9fb2c9-99a7-48b8-97b4-5e291abf1f0c', '唐', '["此心不向常人說。","（《江湖小集》卷二十一李龏《剪綃集》引。","）。"]', '["此心不向常人说。","（《江湖小集》卷二十一李龏《剪綃集》引。","）。"]', '诗', 'shi', '', NULL, '句 羅袞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a05b7b-7b32-47e9-9b5d-73624d6edf1d', '公讌詩', '公讌诗', 'a14517f7-62ed-4099-83d0-ed84131af31f', '唐', '["簾前淡泊雲頭日，座上蕭騷兩脚風。","（見《吟窗雜錄》卷二五《歷代吟譜》。","）（按：《全唐詩》卷七三四收二句，缺題，今重錄。","）。"]', '["簾前淡泊云头日，座上蕭騷兩脚风。","（见《吟窗杂錄》卷二五《歷代吟譜》。","）（按：《全唐诗》卷七三四收二句，缺題，今重錄。","）。"]', '诗', 'shi', '', NULL, '公讌詩 羅紹威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec157f71-c18b-4188-8f30-8024077ca1b1', '答王福娘紅箋題詩（題擬）', '答王福娘紅箋題诗（題擬）', 'f3d7fa26-3950-4615-9d8b-5482a32e4fe9', '唐', '["韶妙如何有遠圖，未能相爲信非夫。","泥中蓮子雖無染，移入家園未得無。","（見《北里志》。","）。"]', '["韶妙如何有远圖，未能相爲信非夫。","泥中蓮子雖無染，移入家园未得無。","（见《北里志》。","）。"]', '诗', 'shi', '', NULL, '答王福娘紅箋題詩（題擬） 孫棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f8f22b7-4ff2-4a5e-acc1-1b5625b883ea', '句', '句', '8fd07562-1107-4100-9c7e-b6a5acfde3c6', '唐', '["志大惟憂國，恩深豈顧身。","（見明黃佐《廣州人物傳》卷四、清黃子高輯《粤詩蒐逸》卷一引《連州志》。","）。"]', '["志大惟憂国，恩深豈顧身。","（见明黄佐《廣州人物傳》卷四、清黄子高輯《粤诗蒐逸》卷一引《連州志》。","）。"]', '诗', 'shi', '', NULL, '句 黃匪躬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00691e9b-ba75-4b11-805e-d55437b76867', '偈', '偈', 'a3c3e32f-cb30-467a-9620-49f94d8f874a', '唐', '["吾有一寶琴，寄之在曠野。","不是不解彈，未遇知音者。","（見《五燈會元》卷十三。","）。"]', '["吾有一寶琴，寄之在曠野。","不是不解彈，未遇知音者。","（见《五灯會元》卷十三。","）。"]', '诗', 'shi', '', NULL, '偈 匡仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a95981ae-0f7d-4f09-a8bd-83b7c3336db0', '臨遷化時偈（《江西詩徴》題作《詩》）', '臨遷化时偈（《江西诗徴》題作《诗》）', 'a3c3e32f-cb30-467a-9620-49f94d8f874a', '唐', '["我路碧空外，白雲無處閑。","世有無根樹，黃葉送風（《景德傳燈錄》、《五燈會元》作「風送」，《江西詩徴》作「風吹黃葉」）還。","（見《祖堂集》卷八、《景德傳燈錄》卷十七、《五燈會元》卷十三、《江西詩徴》卷八七。","）。"]', '["我路碧空外，白云無处闲。","世有無根樹，黄葉送风（《景德傳灯錄》、《五灯會元》作「风送」，《江西诗徴》作「风吹黄葉」）還。","（见《祖堂集》卷八、《景德傳灯錄》卷十七、《五灯會元》卷十三、《江西诗徴》卷八七。","）。"]', '诗', 'shi', '', NULL, '臨遷化時偈（《江西詩徴》題作《詩》） 匡仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c7bdb8e-68d3-4558-96d6-4505702b7337', '擲瓦果悟道偈（題擬）', '擲瓦果悟道偈（題擬）', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["一挃（一作「撃」）忘所知，更不自（一作「假」）修持（一作「治」）。","[動容揚古路，不墮悄然機]（二句據《景德傳燈錄》卷十一補。","）處處無蹤跡，聲色外威儀。","十（《五燈會元》卷九作「諸」）方達道者，咸言上上機。"]', '["一挃（一作「撃」）忘所知，更不自（一作「假」）修持（一作「治」）。","[动容揚古路，不墮悄然機]（二句據《景德傳灯錄》卷十一補。","）处处無蹤跡，声色外威儀。","十（《五灯會元》卷九作「諸」）方達道者，咸言上上機。"]', '诗', 'shi', '', NULL, '擲瓦果悟道偈（題擬） 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa71e5b-c923-43b2-858f-53c7561959d7', '對仰山問作偈（題擬）', '对仰山问作偈（題擬）', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["去年未是貧，今年始是貧。","去年無卓錐之地，今年錐也無。","（《五燈會元》卷九作：「去年貧未是貧，今年貧始是貧。","去年貧猶有卓錐之地，今年貧，錐也無。","」）。"]', '["去年未是貧，今年始是貧。","去年無卓錐之地，今年錐也無。","（《五灯會元》卷九作：「去年貧未是貧，今年貧始是貧。","去年貧猶有卓錐之地，今年貧，錐也無。","」）。"]', '诗', 'shi', '', NULL, '對仰山問作偈（題擬） 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea48d03-1043-4468-9569-9b6e9fe1443a', '勵學吟', '勵学吟', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["滿口語，無處說，明明向道人（一作「人道」）不決。","急著力，勤咬囓，無常到來救不徹。","口裏話（一作「語」），暗嗟（一作「瑳」）切，快磨古錐淨挑揭。","理盡覺，自護持，此生事，吾（一作「終」）不說，玄旨（一作「學」）求他古老吟，禪學須窮心影絕。"]', '["满口語，無处说，明明向道人（一作「人道」）不決。","急著力，勤咬囓，無常到来救不徹。","口裏話（一作「語」），暗嗟（一作「瑳」）切，快磨古錐淨挑揭。","理尽覺，自護持，此生事，吾（一作「終」）不说，玄旨（一作「学」）求他古老吟，禪学須窮心影絕。"]', '诗', 'shi', '', NULL, '勵學吟 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b5f82b-0c49-4cdb-915f-90082f71cccc', '誡宗教接物頌', '誡宗教接物頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["三句語，究人玄。","迅面目，示豁然。","開兩路，備機緣。","投不遇，說多年。"]', '["三句語，究人玄。","迅面目，示豁然。","开兩路，備機緣。","投不遇，说多年。"]', '诗', 'shi', '', NULL, '誡宗教接物頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144cd2bf-a39d-43f5-a228-929e21fbee64', '最後頌（一作「語」）', '最後頌（一作「語」）', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["有一語，全規矩，休思量（一作「惟」），不自許。","路逢同（一作「達」）道人，楊眉省來處。","踏不著，多疑慮，却思量（一作「看」），帶伴侶。","一生參學事無成，慇懃抱得栴檀樹。"]', '["有一語，全規矩，休思量（一作「惟」），不自許。","路逢同（一作「達」）道人，楊眉省来处。","踏不著，多疑慮，却思量（一作「看」），带伴侶。","一生參学事無成，慇懃抱得栴檀樹。"]', '诗', 'shi', '', NULL, '最後頌（一作「語」） 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56818450-fb78-484e-ba6f-63ba3db40838', '修行頌', '修行頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["天寒宜曝日，歸堂一食傾。","思著未生時，宜然任他清。","只摩尋[□]時，明鏡非明鏡。","獨坐覺虛涼，行時也只寧。"]', '["天寒宜曝日，归堂一食傾。","思著未生时，宜然任他清。","只摩尋[□]时，明镜非明镜。","独坐覺虛涼，行时也只寧。"]', '诗', 'shi', '', NULL, '修行頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('777082a8-4b03-47b3-94cf-5cc0613b862e', '發機頌答鄭郎中又問', '發機頌答鄭郎中又问', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["語裏埋筋骨，音聲染道容。","即時纔妙會，拍手趁乘（一作「乖」）龍。"]', '["語裏埋筋骨，音声染道容。","即时纔妙會，拍手趁乘（一作「乖」）龙。"]', '诗', 'shi', '', NULL, '發機頌答鄭郎中又問 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab97aec1-cc2b-489c-b1e1-cdf0f2d79205', '清思頌', '清思頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["盡日坐虛堂，靜思絕參詳。","更無迴顧意，爭肯置平常。"]', '["尽日坐虛堂，静思絕參詳。","更無迴顧意，爭肯置平常。"]', '诗', 'shi', '', NULL, '清思頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e978331e-e99a-41c1-9bd3-cfab534d5a56', '談玄頌（一作「譚道頌」）', '談玄頌（一作「譚道頌」）', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["的的無兼帶，獨運何依賴。","路逢達道人，莫將語嘿對。"]', '["的的無兼带，独運何依賴。","路逢達道人，莫將語嘿对。"]', '诗', 'shi', '', NULL, '談玄頌（一作「譚道頌」） 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f38624-123f-4834-b7a2-612a419f1d6f', '渾{山/淪}語頌', '渾{山/淪}語頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["一束茆，草六分，蓋得庵，無子門。","藏頭人，入去却，轉頭來，語渾{山/淪}。"]', '["一束茆，草六分，蓋得庵，無子门。","藏头人，入去却，轉头来，語渾{山/淪}。"]', '诗', 'shi', '', NULL, '渾{山/淪}語頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23123d31-c7fc-4cda-85f4-106db94ea0d5', '明古頌（一作「授指」）', '明古頌（一作「授指」）', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["古人骨，多靈異。","賢子孫。","密安置。","此一門，成孝義。","人未達，莫差池。","須志固，遣狐疑。","得安靜，不傾危。","向即遠，求即離。","取即失（一作「急」），急（一作「失」）即遲。","無計校，忘覺知。","濁流識，今古僞。","一剎那，通變異。","嵯峨山，石火起（一作「氣」）。","內裏發，焚巔𡻭。","無遮攔，燒海底。","決網疎，靈焰細。","六月臥，去被衣（一作「衣被」）。","蓋不得，無假僞。","達道人，習（一作「唱」）祖意。","我師宗，古來諱。","唯此人，善安置。","足法財，去（一作「具」）慙愧。","不虛施，用處諦。","有人問，小（一作「少」）呵氣。","更尋（一作「審」）來，說米貴。"]', '["古人骨，多靈異。","賢子孫。","密安置。","此一门，成孝義。","人未達，莫差池。","須志固，遣狐疑。","得安静，不傾危。","向即远，求即離。","取即失（一作「急」），急（一作「失」）即遲。","無計校，忘覺知。","濁流識，今古僞。","一剎那，通变異。","嵯峨山，石火起（一作「氣」）。","內裏發，焚巔𡻭。","無遮攔，燒海底。","決網疎，靈焰細。","六月臥，去被衣（一作「衣被」）。","蓋不得，無假僞。","達道人，習（一作「唱」）祖意。","我師宗，古来諱。","唯此人，善安置。","足法財，去（一作「具」）慙愧。","不虛施，用处諦。","有人问，小（一作「少」）呵氣。","更尋（一作「審」）来，说米貴。"]', '诗', 'shi', '', NULL, '明古頌（一作「授指」） 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5349801-e247-433d-b3b0-358ac4297f74', '與崔大夫暢玄頌', '與崔大夫暢玄頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["達人多隱顯，不定露形儀。","語下不遺跡，密密潛護持。","動容揚古路，明妙乃方知。","應求俱（一作「物但」）施設，莫道不思議。"]', '["達人多隐显，不定露形儀。","語下不遺跡，密密潛護持。","动容揚古路，明妙乃方知。","應求俱（一作「物但」）施設，莫道不思議。"]', '诗', 'shi', '', NULL, '與崔大夫暢玄頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8303ce52-47bd-4512-a012-d89329ce8ff5', '寶明頌', '寶明頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["思清人少慮，風規自然足。","影落在音容，孤明絕撑觸。"]', '["思清人少慮，风規自然足。","影落在音容，孤明絕撑觸。"]', '诗', 'shi', '', NULL, '寶明頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b8e8f9d-95a5-4215-a1e8-d34e2df7f4cb', '出家頌', '出家頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["從來求出家，未詳出家稱。","起坐只尋常，更無小（《宗鏡錄》卷二四作「少」）殊勝。"]', '["從来求出家，未詳出家稱。","起坐只尋常，更無小（《宗镜錄》卷二四作「少」）殊勝。"]', '诗', 'shi', '', NULL, '出家頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4634ad48-2906-4448-90c8-13d963d8d125', '寄法堂頌', '寄法堂頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["東間裏入寂，西間裏語話。","中間裏睡眠，通間裏行道。","向前即撿校，向後即隱形。","。"]', '["东间裏入寂，西间裏語話。","中间裏睡眠，通间裏行道。","向前即撿校，向後即隐形。","。"]', '诗', 'shi', '', NULL, '寄法堂頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5711b6b4-e2dd-4247-aeba-795ffee01e25', '時人都不措問什麽精靈答曰', '时人都不措问什麽精靈答曰', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["淨地上皷怒，怡然中伴嗔。","平坦處不守，危嶮中藏身。","盲聾遇之眼開，僧瑤駐筆通神。"]', '["淨地上皷怒，怡然中伴嗔。","平坦处不守，危嶮中藏身。","盲聾遇之眼开，僧瑤駐笔通神。"]', '诗', 'shi', '', NULL, '時人都不措問什麽精靈答曰 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a6ab558-c1fd-4af4-8652-7d323f9801a0', '玄旨頌', '玄旨頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["去去無標的，來來只摩（一作「麽」）來。","有人相借問，不語笑咳咳。"]', '["去去無標的，来来只摩（一作「麽」）来。","有人相借问，不語笑咳咳。"]', '诗', 'shi', '', NULL, '玄旨頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae0c98fc-0de3-4746-ab30-7754d315bad0', '贈同住歸寂頌（一作《歸寂吟贈同住》）', '贈同住归寂頌（一作《归寂吟贈同住》）', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["同住道人七十餘，共辭城郭樂山居。","身如寒木心芽（一作「牙」）絕，不話唐言休梵書。","心期盡處身雖喪，如來弟子沙門樣。","深信共崇鉢塔成，巍巍置在青山嶂（一作「掌」）。","觀夫參道不虛然，脫去形骸惎（一作「甚」）高上。","從來不說今朝事，暗裏埋頭隱玄暢。","不留蹤跡異人間，深妙神光飽明亮。"]', '["同住道人七十餘，共辞城郭乐山居。","身如寒木心芽（一作「牙」）絕，不話唐言休梵书。","心期尽处身雖喪，如来弟子沙门樣。","深信共崇鉢塔成，巍巍置在青山嶂（一作「掌」）。","观夫參道不虛然，脫去形骸惎（一作「甚」）高上。","從来不说今朝事，暗裏埋头隐玄暢。","不留蹤跡異人间，深妙神光飽明亮。"]', '诗', 'shi', '', NULL, '贈同住歸寂頌（一作《歸寂吟贈同住》） 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76c19c1b-2848-46c0-8d9a-d253b24d2c39', '勸學頌', '勸学頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["出家修道莫求安，失念求安學道難。","未得直須求大道，覺了無安無不安。"]', '["出家修道莫求安，失念求安学道难。","未得直須求大道，覺了無安無不安。"]', '诗', 'shi', '', NULL, '勸學頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4b5b92-afac-4d1d-a422-d46ee9f2882b', '志守得破頌', '志守得破頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["十五日已前，師僧莫離此間。","十五日已後，師僧莫住此間。","去即打汝頭破，住即亦復如然。"]', '["十五日已前，師僧莫離此间。","十五日已後，師僧莫住此间。","去即打汝头破，住即亦复如然。"]', '诗', 'shi', '', NULL, '志守得破頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf66848-655a-46a8-a896-4230dc0bbe4b', '辭見聞頌', '辞见闻頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["好住逕分離，幽宗人跡稀。","從來未登陟，無許遣狐疑。"]', '["好住逕分離，幽宗人跡稀。","從来未登陟，無許遣狐疑。"]', '诗', 'shi', '', NULL, '辭見聞頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b278cbd-b084-49be-9f50-2efb4c8ae1cf', '遵古路頌與郎中', '遵古路頌與郎中', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["虛心越境淨思量，句裏無蹤聲外詳。","文字影像駭驚覺，動容彈指飽馨香。","。"]', '["虛心越境淨思量，句裏無蹤声外詳。","文字影像駭驚覺，动容彈指飽馨香。","。"]', '诗', 'shi', '', NULL, '遵古路頌與郎中 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d7b01b0-690d-4790-b0eb-0a6253083639', '與董兵馬使說示偈', '與董兵马使说示偈', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["宿靜心意到山中，爲求半偈契神蹤。","向道却思思不得，却將尋思㝵（疑即「礙」之俗寫字）不通。"]', '["宿静心意到山中，爲求半偈契神蹤。","向道却思思不得，却將尋思㝵（疑即「礙」之俗寫字）不通。"]', '诗', 'shi', '', NULL, '與董兵馬使說示偈 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cff6ad1-4f44-4dc6-b53b-29261b2fc66a', '與學人宗教宗如', '與学人宗教宗如', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["滿寺釋迦子，未詳釋迦經。","喚來試共語，開口雜音聲。"]', '["满寺釋迦子，未詳釋迦經。","喚来試共語，开口杂音声。"]', '诗', 'shi', '', NULL, '與學人宗教宗如 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f685dbf1-8933-4d18-b648-aa127faa8924', '三句後意頌', '三句後意頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["書出語多虛，虛中帶有無。","却向書前會，放却意中珠。","（以上均見《祖堂集》卷十九。","注「一作」者，爲《景德傳燈錄》卷二九之異文。","）。"]', '["书出語多虛，虛中带有無。","却向书前會，放却意中珠。","（以上均见《祖堂集》卷十九。","注「一作」者，爲《景德傳灯錄》卷二九之異文。","）。"]', '诗', 'shi', '', NULL, '三句後意頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98b03d81-40e0-4db4-9390-e85dbeaaa859', '達道場與城陰行者頌', '達道場與城陰行者頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["理奧絕思量，根尋徑路長。","因茲知隔濶，無那被封疆。","人生須特達，起坐覺馨香。","清淨如來子，安然坐道場。"]', '["理奧絕思量，根尋徑路长。","因茲知隔濶，無那被封疆。","人生須特達，起坐覺馨香。","清淨如来子，安然坐道場。"]', '诗', 'shi', '', NULL, '達道場與城陰行者頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('665938ac-d4c1-4a6e-86fc-898de497ebe9', '顯旨頌', '显旨頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["思遠神儀奧，精虛履踐通。","見聞離影像，密際語前蹤。","得意塵中妙，投機露道容。","藏明照驚覺，肯可達真宗。"]', '["思远神儀奧，精虛履踐通。","见闻離影像，密際語前蹤。","得意塵中妙，投機露道容。","藏明照驚覺，肯可達真宗。"]', '诗', 'shi', '', NULL, '顯旨頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aefcc1d-13ee-425c-acf5-636d99e9f119', '明道頌', '明道頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["思思似有蹤，明明不知處。","借問示宗賓，徐徐暗迴顧。","。"]', '["思思似有蹤，明明不知处。","借问示宗賓，徐徐暗迴顧。","。"]', '诗', 'shi', '', NULL, '明道頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9d69bb5-ff88-4166-9540-8eabf978ba0b', '與鄧州行者頌', '與鄧州行者頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["林下覺身愚，緣不帶心珠。","開口無言說，筆頭無可書。","人問香嚴旨，莫道在山居。"]', '["林下覺身愚，緣不带心珠。","开口無言说，笔头無可书。","人问香嚴旨，莫道在山居。"]', '诗', 'shi', '', NULL, '與鄧州行者頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4f3c6c-e4c1-4f40-b717-956b235e5553', '三跳後頌', '三跳後頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["三門前合掌，兩廊下行道。","中庭上作舞，後門外搖頭。"]', '["三门前合掌，兩廊下行道。","中庭上作舞，後门外搖头。"]', '诗', 'shi', '', NULL, '三跳後頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1368791b-7ffc-4e37-9546-3dd9390f0fbe', '破法身見頌', '破法身见頌', 'fdd6808c-5ade-4077-9ff5-73beb023386e', '唐', '["向上無父孃，向下無男女。","獨自一個身，切須了却去。","聞我有此言，人人競來取。","對他一句子，不話無言語。","（以上六首均見《景德傳燈錄》卷二十九。","）（按：敦煌遺書斯五五五八卷收「龍興寺香嚴和尚《嗟世三傷吟》」，存二首。","《鑑誡錄》卷十收伏牛上人〖即自在〗《三傷頌》，其前二首與敦煌本大致相同。","詳《全唐詩外編》〖修訂本〗，茲不重收。","）。"]', '["向上無父孃，向下無男女。","独自一個身，切須了却去。","闻我有此言，人人競来取。","对他一句子，不話無言語。","（以上六首均见《景德傳灯錄》卷二十九。","）（按：敦煌遺书斯五五五八卷收「龙兴寺香嚴和尚《嗟世三傷吟》」，存二首。","《鑑誡錄》卷十收伏牛上人〖即自在〗《三傷頌》，其前二首與敦煌本大致相同。","詳《全唐诗外編》〖修訂本〗，茲不重收。","）。"]', '诗', 'shi', '', NULL, '破法身見頌 智閑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea64cc15-3637-43fd-9da2-245b354562b0', '問香巖和尚（題擬）', '问香巖和尚（題擬）', 'dc787108-41f3-49a2-be01-ebfa3c99e837', '唐', '["來無他[轍]（徹）跡，去是非我途。","併逐猿猴盡，山川境在無？","（見《祖堂集》卷十九。","）。"]', '["来無他[轍]（徹）跡，去是非我途。","併逐猿猴尽，山川境在無？","（见《祖堂集》卷十九。","）。"]', '诗', 'shi', '', NULL, '問香巖和尚（題擬） 鄭郎中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4fb073-5fa9-48be-a419-260231ef0617', '', '', 'd4c08cff-2d36-4143-b57b-bb3914346c29', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 敬新磨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b894919-2e8a-4c81-b375-60cd1e6dfe07', '六目龜口號（題擬）', '六目龟口號（題擬）', 'd4c08cff-2d36-4143-b57b-bb3914346c29', '唐', '["不要鬧，不要鬧，聽取龜兒口號。","六隻眼兒睡一覺，抵別人三覺。","（見宋張世南《遊宦紀聞》卷二。","）（按：《遊宦紀聞》謂此詩爲東坡謁呂微仲時述，張端義《貴耳集》卷上徑作東坡代龜作，恐非。","《東臯雜錄》卷一僅作「六隻眼兒分明，睡一覺抵別人三覺。","」）。"]', '["不要鬧，不要鬧，听取龟兒口號。","六隻眼兒睡一覺，抵別人三覺。","（见宋張世南《游宦紀闻》卷二。","）（按：《游宦紀闻》謂此诗爲东坡謁呂微仲时述，張端義《貴耳集》卷上徑作东坡代龟作，恐非。","《东臯杂錄》卷一僅作「六隻眼兒分明，睡一覺抵別人三覺。","」）。"]', '诗', 'shi', '', NULL, '六目龜口號（題擬） 敬新磨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72df84c1-042d-480f-9c3b-3893217d0ae1', '遺詩 一', '遺诗 一', 'ccdba343-4864-4502-a1f9-5c8fed15637e', '唐', '["三十年前賣卜，化得一間茅屋。"]', '["三十年前賣卜，化得一间茅屋。"]', '诗', 'shi', '', NULL, '遺詩 一 盧道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eedfb0e2-f0aa-448b-8ee8-f47ac9164db2', '遺詩 二', '遺诗 二', 'ccdba343-4864-4502-a1f9-5c8fed15637e', '唐', '["撒手永超三界，一去定無反復。","（見鄭方坤《五代詩話》卷九引《粵西通志》。","）（〖1〗《粵西通志》云：「盧道者精於卜，後唐同光二年，有郡倅因內孕歲餘不產，求盧道者卜之。","書一『酷』字，遂不踰月二十一日酉時娩。","倅以爲神，建塔居之。","後坐化，遺詩云〖略〗。","末云：〖略〗。","」）。"]', '["撒手永超三界，一去定無反复。","（见鄭方坤《五代诗話》卷九引《粵西通志》。","）（〖1〗《粵西通志》云：「盧道者精於卜，後唐同光二年，有郡倅因內孕歲餘不產，求盧道者卜之。","书一『酷』字，遂不踰月二十一日酉时娩。","倅以爲神，建塔居之。","後坐化，遺诗云〖略〗。","末云：〖略〗。","」）。"]', '诗', 'shi', '', NULL, '遺詩 二 盧道者 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9345096d-69c8-49e5-b5d1-ffe85cb2be1d', '皇帝癸未年膺運滅梁再興（缺）迎太后七言詩', '皇帝癸未年膺運滅梁再兴（缺）迎太后七言诗', '55b07c8f-578a-4263-a271-ce3a9ce1d7ff', '唐', '["禁煙節假賞幽閑，迎奉傾心樂貴顏。","䴏語雕樑聲猗狔，鸚吟[綠]（淥）樹韻開關。","爲安家國千場戰，思憶慈親兩鬢斑。","孝道未能全報得，直須頂戴遶彌山。","（〖1〗劉銘恕《斯坦因劫經錄》云：「按《全唐文》一零四唐莊宗《親至懷州奉迎太后敕》，略謂天下已定，理應到汾州親迎太后，不得已只到懷州迎接，是知迎太后詩，即爲此時作品。","」）。"]', '["禁煙節假賞幽闲，迎奉傾心乐貴顏。","䴏語雕樑声猗狔，鸚吟[綠]（淥）樹韻开关。","爲安家国千場戰，思憶慈親兩鬢斑。","孝道未能全報得，直須頂戴遶彌山。","（〖1〗劉銘恕《斯坦因劫經錄》云：「按《全唐文》一零四唐莊宗《親至懷州奉迎太后敕》，略謂天下已定，理應到汾州親迎太后，不得已只到懷州迎接，是知迎太后诗，即爲此时作品。","」）。"]', '诗', 'shi', '', NULL, '皇帝癸未年膺運滅梁再興（缺）迎太后七言詩 李存勗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfeac7cd-e93a-44d0-8f9f-f1a39aa9eb14', '題北京西山童子寺七言', '題北京西山童子寺七言', '55b07c8f-578a-4263-a271-ce3a9ce1d7ff', '唐', '["昔時童子[慕]（募）清閑，今古猶傳在此山。","百派崢嶸流海內，千溪{山|穴/大}屼透雲間。","猿啼嶺上深幽靜，虎笑（應即「嘯」字）巖邊去復還。","愐想翠花崚谷變，空留禪室喜登攀。"]', '["昔时童子[慕]（募）清闲，今古猶傳在此山。","百派崢嶸流海內，千溪{山|穴/大}屼透云间。","猿啼嶺上深幽静，虎笑（應即「嘯」字）巖邊去复還。","愐想翠花崚谷变，空留禪室喜登攀。"]', '诗', 'shi', '', NULL, '題北京西山童子寺七言 李存勗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a34be74a-6063-454f-85e1-61826724f40b', '題南嶽山七言（直在江南）', '題南嶽山七言（直在江南）', '55b07c8f-578a-4263-a271-ce3a9ce1d7ff', '唐', '["融峰絕頂九霄邊，獨立孤巒勢近天。","北眺洞庭千里浪，南觀石{石禀}萬坡煙。","雲藏碧澗泉聲遠，僧迫金烏耳伴喧。","唯有此山侵上界，姮娥吹瑟古松前。"]', '["融峰絕頂九霄邊，独立孤巒勢近天。","北眺洞庭千里浪，南观石{石禀}万坡煙。","云藏碧澗泉声远，僧迫金烏耳伴喧。","唯有此山侵上界，姮娥吹瑟古松前。"]', '诗', 'shi', '', NULL, '題南嶽山七言（直在江南） 李存勗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b43ac66-0e38-42a3-aed8-b9074bcccd62', '題幽州盤山七言（在幽州北）', '題幽州盤山七言（在幽州北）', '55b07c8f-578a-4263-a271-ce3a9ce1d7ff', '唐', '["衝過浮雲數千重，經霄始到最高峰。","日出近觀滄海水，齋時遙聽梵天鐘。","千年松樹巢仙鶴，五个盆池隱毒龍。","下方乞食上方去，塵俗難尋道者蹤。"]', '["衝過浮云數千重，經霄始到最高峰。","日出近观滄海水，斋时遙听梵天鐘。","千年松樹巢仙鹤，五个盆池隐毒龙。","下方乞食上方去，塵俗难尋道者蹤。"]', '诗', 'shi', '', NULL, '題幽州盤山七言（在幽州北） 李存勗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08f36941-5476-412b-98d1-9b9cfc3e2b5d', '題幽州石經山（在南）', '題幽州石經山（在南）', '55b07c8f-578a-4263-a271-ce3a9ce1d7ff', '唐', '["閑棄五馬謁真宗，來入山門問遠公。","雲起亂峰朝古寺，鳥巢高處戀晴空。","碧蘿引蔓枝枝到，石溜穿渠院院通。","佛境不離人境內，人心不與佛心同。","（均見斯三七三卷。","）。"]', '["闲棄五马謁真宗，来入山门问远公。","云起亂峰朝古寺，鸟巢高处戀晴空。","碧蘿引蔓枝枝到，石溜穿渠院院通。","佛境不離人境內，人心不與佛心同。","（均见斯三七三卷。","）。"]', '诗', 'shi', '', NULL, '題幽州石經山（在南） 李存勗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('762fdbd8-8e9b-42be-8c8b-97e68ca48086', '句', '句', '703e6a20-01b8-4ce2-bafb-ab8c16c44ddc', '唐', '["印將金鏁鏁，簾用玉鉤鉤。","（見《北夢瑣言》卷七。","）（按：《全唐詩》卷七○○誤收此二句爲韋莊詩，今移正。","）。"]', '["印將金鏁鏁，簾用玉鉤鉤。","（见《北梦瑣言》卷七。","）（按：《全唐诗》卷七○○誤收此二句爲韋莊诗，今移正。","）。"]', '诗', 'shi', '', NULL, '句 韋說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da87bda5-b585-4530-8705-756e153a3ad2', '句', '句', '24fd5fcd-1515-4c44-8914-e93476d5ca1c', '唐', '["鴛鴦分品秩，龍袞耀簪裾。","（見《吟窗雜錄》卷十三王夢簡《進士王氏詩要格律》。","）。"]', '["鴛鴦分品秩，龙袞耀簪裾。","（见《吟窗杂錄》卷十三王梦簡《進士王氏诗要格律》。","）。"]', '诗', 'shi', '', NULL, '句 郄殷象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68095482-4881-4447-9025-2dca7989fe94', '寒食（題擬）', '寒食（題擬）', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["雲濃雲淡半陰春，禁火天時欲灑塵。","花艷有枝還怕雨，柳煙無賴尚重人。","畫毬輕蹴壺中地，綵索高飛掌上身。","一路綠莎東郭外，也寬情抱也傷神。","（見《古今合璧事類備要前集》卷十六。","）（按：《唐音戊籤》九八據《事文類聚》收五六兩句，《全唐詩》卷七二○已收入。","）。"]', '["云濃云淡半陰春，禁火天时欲灑塵。","花艷有枝還怕雨，柳煙無賴尚重人。","畫毬轻蹴壺中地，綵索高飞掌上身。","一路綠莎东郭外，也寬情抱也傷神。","（见《古今合璧事類備要前集》卷十六。","）（按：《唐音戊籤》九八據《事文類聚》收五六兩句，《全唐诗》卷七二○已收入。","）。"]', '诗', 'shi', '', NULL, '寒食（題擬） 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1b2da3-4ec6-4281-a004-4553e7ac8789', '客中重陽', '客中重陽', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["避地逢佳節，窮愁強不知。","十年猶亂過，九日又奚爲？","況借他蝸舍，兼無自菊籬。","登高轉惆悵，回首也風吹。","（見前書卷十七。","）。"]', '["避地逢佳節，窮愁強不知。","十年猶亂過，九日又奚爲？","況借他蝸舍，兼無自菊籬。","登高轉惆悵，回首也风吹。","（见前书卷十七。","）。"]', '诗', 'shi', '', NULL, '客中重陽 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24741cfe-81cf-4dfb-ab07-dfdc1af0dcf9', '送小白上人歸華頂（一作云守恭作）', '送小白上人归华頂（一作云守恭作）', '9dcfc055-b999-4696-a278-0361f6f8b56f', '唐', '["瀑濺安禪石，秋雲鎖碧層。","一峰如卓筆，幾日策孤藤。","樹偃前朝蓋，星輝下界燈。","超然歸此處，心已契南能。"]', '["瀑濺安禪石，秋云鎖碧層。","一峰如卓笔，幾日策孤藤。","樹偃前朝蓋，星輝下界灯。","超然归此处，心已契南能。"]', '诗', 'shi', '', NULL, '送小白上人歸華頂（一作云守恭作） 秀登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fcf7918-70a4-4e0a-b5ca-11788ea2d4f8', '朝海峰', '朝海峰', '9dcfc055-b999-4696-a278-0361f6f8b56f', '唐', '["萬仞朝滄海，秋層上碧虛。","峭欹雲盡後，寒綺月生初。","影落陽侯宅，根連覺帝居。","誰能謝塵迹，向此結茅廬。"]', '["万仞朝滄海，秋層上碧虛。","峭欹云尽後，寒綺月生初。","影落陽侯宅，根連覺帝居。","誰能謝塵迹，向此結茅廬。"]', '诗', 'shi', '', NULL, '朝海峰 秀登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8801dfd-b58d-435c-8ce2-4d8be46c4f3e', '送貫微歸天台', '送貫微归天台', '9dcfc055-b999-4696-a278-0361f6f8b56f', '唐', '["秋歸赤城寺，幽興唯相同。","迹與片雲合，心向萬境空。","傾耳霜樹猿，吹衣瀑布風。","後夜越溪上，夢斷寒猿中。","（《增廣聖宋高僧詩選後集》卷上。","）（按：秀登事迹無考。","小白爲唐僧，《全唐詩續補遺》收其詩三首；貫微爲齊己之友，《白蓮集》中有《荆門病中寄懷貫微上人》、《擬嵇康絕交寄湘中貫微》〖均卷四〗、《謝貫微上人寄示古風今體四軸》〖卷七〗、《荆川寄貫微上人》〖卷八〗、《寄武陵貫微上人二首》〖卷九〗等詩。","知秀登與齊己同時，爲五代時人。","《宋詩紀事》卷九一收入，無事迹，似誤。","）。"]', '["秋归赤城寺，幽兴唯相同。","迹與片云合，心向万境空。","傾耳霜樹猿，吹衣瀑布风。","後夜越溪上，梦斷寒猿中。","（《增廣聖宋高僧诗選後集》卷上。","）（按：秀登事迹無考。","小白爲唐僧，《全唐诗續補遺》收其诗三首；貫微爲齊己之友，《白蓮集》中有《荆门病中寄懷貫微上人》、《擬嵇康絕交寄湘中貫微》〖均卷四〗、《謝貫微上人寄示古风今體四軸》〖卷七〗、《荆川寄貫微上人》〖卷八〗、《寄武陵貫微上人二首》〖卷九〗等诗。","知秀登與齊己同时，爲五代时人。","《宋诗紀事》卷九一收入，無事迹，似誤。","）。"]', '诗', 'shi', '', NULL, '送貫微歸天台 秀登 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c33aeefe-bb4b-4417-a8c7-52fb1898d693', '夢中獻南楚國王夜宴詩（題擬）', '梦中獻南楚国王夜宴诗（題擬）', '5dec9617-2df3-4a7b-8aa2-709c0646563c', '唐', '["妙樂佳人數步隨，殿堂高敞盛威儀。","鳳笙品弄檀脣散，鼉鼓喧鍧錦袖垂。","寶帳珍華光煦灼，玳筵花燭影參差。","酒酣回顧清歌妓。","粉面皆言某在斯。","（《燈下閑談》卷下《夢與神交》。","）。"]', '["妙乐佳人數步隨，殿堂高敞盛威儀。","鳳笙品弄檀脣散，鼉鼓喧鍧錦袖垂。","寶帳珍华光煦灼，玳筵花燭影參差。","酒酣回顧清歌妓。","粉面皆言某在斯。","（《灯下闲談》卷下《梦與神交》。","）。"]', '诗', 'shi', '', NULL, '夢中獻南楚國王夜宴詩（題擬） 史松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd863420-2ebf-4d17-b271-84394caca6f8', '翛公上人草書歌（題從《書苑菁華》）', '翛公上人草书歌（題從《书苑菁华》）', '5dec9617-2df3-4a7b-8aa2-709c0646563c', '唐', '["真蹤草聖今古有，翛公學得誰及否？","古人今人一手書，師今書成在兩手。","書時須飲一斗酒，醉後掃成龍虎吼。","風雨飄（《書苑菁華》作「驚」）兮魍魎走。","千尺松枝如蠹朽，欲折不折橫（《書苑菁華》作「掛」）巖口。","張旭骨，懷素筋，筋骨一時傳斯人，斯人傳得（《書苑菁華》作「是」）[妙]通神。","攘臂縱橫草復真，一身疑是兩人身。","（同前，原缺一字。","又見《書苑菁華》卷十七，作者署「史邕」，今據以校補。","）。"]', '["真蹤草聖今古有，翛公学得誰及否？","古人今人一手书，師今书成在兩手。","书时須饮一斗酒，醉後掃成龙虎吼。","风雨飄（《书苑菁华》作「驚」）兮魍魎走。","千尺松枝如蠹朽，欲折不折橫（《书苑菁华》作「掛」）巖口。","張旭骨，懷素筋，筋骨一时傳斯人，斯人傳得（《书苑菁华》作「是」）[妙]通神。","攘臂縱橫草复真，一身疑是兩人身。","（同前，原缺一字。","又见《书苑菁华》卷十七，作者署「史邕」，今據以校補。","）。"]', '诗', 'shi', '', NULL, '翛公上人草書歌（題從《書苑菁華》） 史松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c1e8167-2679-45fd-a7ed-00388a22304b', '詠魏王繼岌羹丞相盧澄粥（題擬）', '詠魏王繼岌羹丞相盧澄粥（題擬）', '2eaf4b0d-d02e-4399-84ee-1a5117bb2770', '唐', '["王羹亥卯未，相粥白玄黃。","（《說郛》卷六一引《清異錄》。","）。"]', '["王羹亥卯未，相粥白玄黄。","（《说郛》卷六一引《清異錄》。","）。"]', '诗', 'shi', '', NULL, '詠魏王繼岌羹丞相盧澄粥（題擬） 後唐廚官 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4248a124-50d8-43bd-8f77-64f8cca093a8', '和呂知柔終南山詩（題擬）', '和呂知柔終南山诗（題擬）', '6db98fe4-5738-4333-99d4-f8e951d8c827', '唐', '["料伊直擬衝霄漢，賴有青天壓着頭。","（見《冊府元龜》卷九三九、卷九五四、《舊五代史》卷六五。","）。"]', '["料伊直擬衝霄漢，賴有青天壓着头。","（见《冊府元龟》卷九三九、卷九五四、《旧五代史》卷六五。","）。"]', '诗', 'shi', '', NULL, '和呂知柔終南山詩（題擬） 王思同 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e4dc89-1d1f-44ee-9975-e36455e53119', '', '', '1c71e68b-d0ed-43ea-99ac-d8a55d484e94', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287a6687-8493-40a9-ba6c-24a13e29f01e', '述懷', '述懷', '1c71e68b-d0ed-43ea-99ac-d8a55d484e94', '唐', '["奉職常如履薄冰，屢看斜日下觚稜。","鹽梅且讓當朝傑，粥飯甘爲退院僧。","虛負紫宸思寵渥，自傷白髮病侵凌。","明年便向燕南去，竹塢雲菴獨枕肱。","（見民國十四年刊張方墀纂《無棣縣志》卷二十三。","）。"]', '["奉職常如履薄冰，屢看斜日下觚稜。","鹽梅且讓當朝傑，粥飯甘爲退院僧。","虛負紫宸思寵渥，自傷白髮病侵凌。","明年便向燕南去，竹塢云菴独枕肱。","（见民国十四年刊張方墀纂《無棣縣志》卷二十三。","）。"]', '诗', 'shi', '', NULL, '述懷 李愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2c09dc6-734b-44ab-8e39-f44fb64e7a8b', '戲程紫霄登華山偶顛僕（題擬）', '戲程紫霄登华山偶顛僕（題擬）', '92877d95-de0f-4578-ad6e-4bf726ab690f', '唐', '["不知上得不得，且怪懸之又懸。","（見《類說》卷四十一《北夢瑣言》。","紫霄，原作「子霄」。","）。"]', '["不知上得不得，且怪懸之又懸。","（见《類说》卷四十一《北梦瑣言》。","紫霄，原作「子霄」。","）。"]', '诗', 'shi', '', NULL, '戲程紫霄登華山偶顛僕（題擬） 宇文翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e420597b-ed63-4465-8ca3-4c94ebede940', '', '', '3757acfb-b91e-49d3-a8ef-e3c8576dc027', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 程遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88571e6e-7ac9-4089-b8cb-17df82fff9a4', '詩', '诗', '3757acfb-b91e-49d3-a8ef-e3c8576dc027', '唐', '["幽室有時聞鴈叫，空庭無路見蟾光。","（見《冊府元龜》卷九五一《總錄·咎徴》二。","）（〖1〗《冊府元龜》：「程遜爲太[常]〖嘗〗卿奉使吳越，仲秋之夕，陰暝如晦。","遜嘗爲詩曰〖略〗。","同僚見之，訝其詩語稍異。","及使迴，遭風水而溺焉。","」）。"]', '["幽室有时闻鴈叫，空庭無路见蟾光。","（见《冊府元龟》卷九五一《總錄·咎徴》二。","）（〖1〗《冊府元龟》：「程遜爲太[常]〖嘗〗卿奉使吳越，仲秋之夕，陰暝如晦。","遜嘗爲诗曰〖略〗。","同僚见之，訝其诗語稍異。","及使迴，遭风水而溺焉。","」）。"]', '诗', 'shi', '', NULL, '詩 程遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d11f5cc3-722b-48a5-bc1d-3560ae7770ec', '閒居', '閒居', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["深逢野草皆爲藥，靜見樵人恐是仙。","（見《增修詩話總龜前集》卷十三《雅言雜載》。","）（按：《全唐詩》卷七三七收二句，缺題，今重錄。","）。"]', '["深逢野草皆爲藥，静见樵人恐是仙。","（见《增修诗話總龟前集》卷十三《雅言杂載》。","）（按：《全唐诗》卷七三七收二句，缺題，今重錄。","）。"]', '诗', 'shi', '', NULL, '閒居 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b62355a5-50af-4abe-b6e4-479b585f4efc', '題案上詩（題擬）', '題案上诗（題擬）', 'c087d694-7afc-468e-9adf-3029d59c1db0', '唐', '["數年叨內署，衫色儼然傾。","任贊字希度，知君是火精。","（見《類說》卷五四《玉堂閑話》。","）（〖1〗《玉堂閑話》：「梁朝翰林學士任贊居職數年，猶着朱紱，於案上題詩。","梁主知之，命賜紫袍金章。","」）。"]', '["數年叨內署，衫色儼然傾。","任贊字希度，知君是火精。","（见《類说》卷五四《玉堂闲話》。","）（〖1〗《玉堂闲話》：「梁朝翰林学士任贊居職數年，猶着朱紱，於案上題诗。","梁主知之，命賜紫袍金章。","」）。"]', '诗', 'shi', '', NULL, '題案上詩（題擬） 任贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f551169-87bd-4329-9795-b203c825a578', '送賓', '送賓', '0ad57d0c-ba9c-461a-9ab1-80045385d1a5', '唐', '["蟾桂三春捷，雞林一國榮。"]', '["蟾桂三春捷，雞林一国榮。"]', '诗', 'shi', '', NULL, '送賓 徐巡官 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0732dd85-a413-4a2e-b22f-d6b82e3a5add', '貽友生', '貽友生', '0ad57d0c-ba9c-461a-9ab1-80045385d1a5', '唐', '["詩道長年樂，生來貧却閑。","（均見宋龔鼎臣《東原錄》引李崧《論詩答徐巡官》引。","）（按：李崧事跡，詳《舊五代史》卷一○八，《全唐文》及陸輯二書均失收此文。","）。"]', '["诗道长年乐，生来貧却闲。","（均见宋龔鼎臣《东原錄》引李崧《論诗答徐巡官》引。","）（按：李崧事跡，詳《旧五代史》卷一○八，《全唐文》及陸輯二书均失收此文。","）。"]', '诗', 'shi', '', NULL, '貽友生 徐巡官 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0b21f6-fb55-44f3-aabe-f57746fd6185', '冷金亭賞菊分韻賦秋鴈（題擬）', '冷金亭賞菊分韻賦秋鴈（題擬）', '17f11f92-bb96-48bb-9603-77cf9e54dec3', '唐', '["天掃閑雲秋淨時，書空匠者最相宜。","（見《說郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「乾祐中冷金亭賞菊，分韻賦秋鴈，族子秘書丞敞先就，詩曰〖略〗。","」）（按：《清異錄》一書，舊題陶穀擢，然自陳振孫以來，多疑爲僞託，近人王國維《庚辛之間讀書志》、余嘉錫《四庫提要辨證》卷十八力證不出穀手，究爲誰作，尚難考詳。","今敞姓姑從陶姓，確否待考。","鄭方坤《五代詩話》卷二以爲韓敞，未列證，今不取。","）。"]', '["天掃闲云秋淨时，书空匠者最相宜。","（见《说郛》卷六一《清異錄》。","）（〖1〗《清異錄》：「乾祐中冷金亭賞菊，分韻賦秋鴈，族子秘书丞敞先就，诗曰〖略〗。","」）（按：《清異錄》一书，旧題陶穀擢，然自陳振孫以来，多疑爲僞託，近人王国維《庚辛之间读书志》、余嘉錫《四庫提要辨證》卷十八力證不出穀手，究爲誰作，尚难考詳。","今敞姓姑從陶姓，確否待考。","鄭方坤《五代诗話》卷二以爲韓敞，未列證，今不取。","）。"]', '诗', 'shi', '', NULL, '冷金亭賞菊分韻賦秋鴈（題擬） 陶敞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4faf1c4e-84fa-43eb-82bc-335f55c96520', '題洪陽洞', '題洪陽洞', '0ec6c591-e6d0-40c2-83cd-e41c904a00fa', '唐', '["天窗通月影，地穴通江津。","（見《輿地紀勝》卷二八《袁州》。","）（按：《歐陽文忠公文集》卷三四《贈太子太傅胡公墓誌》云胡宿之祖名徽，推其時，亦約爲五代末人，疑即本詩作者。","）。"]', '["天窗通月影，地穴通江津。","（见《輿地紀勝》卷二八《袁州》。","）（按：《歐陽文忠公文集》卷三四《贈太子太傅胡公墓誌》云胡宿之祖名徽，推其时，亦約爲五代末人，疑即本诗作者。","）。"]', '诗', 'shi', '', NULL, '題洪陽洞 胡徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd355ba-c067-4e51-bccc-6f1c0ee7e2c9', '郢州白雪樓（題擬）', '郢州白雪楼（題擬）', '5aac0b07-9601-4259-a31b-7f875e2ef45e', '唐', '["美人莫唱《陽春曲》，白盡湖南太守頭。","（宋王之望《漢濱集》卷二《郢守喬民瞻寄襄陽雪中三絕因追述前過石城杯酒登臨之勝爲和》其三自注引。","）（王之望詩注云：「僕舊遊白雪樓，見張休詩石刻，尾章云〖詩略〗。","今石已亡，民瞻詢於老吏，遂得其全篇，云將復刻）（諸石。","」）。"]', '["美人莫唱《陽春曲》，白尽湖南太守头。","（宋王之望《漢濱集》卷二《郢守喬民瞻寄襄陽雪中三絕因追述前過石城杯酒登臨之勝爲和》其三自注引。","）（王之望诗注云：「僕旧游白雪楼，见張休诗石刻，尾章云〖诗略〗。","今石已亡，民瞻詢於老吏，遂得其全篇，云將复刻）（諸石。","」）。"]', '诗', 'shi', '', NULL, '郢州白雪樓（題擬） 張休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ec683f-2820-4496-a3b7-d6dd85c688b1', '題敦煌千龕窟（題擬）', '題敦煌千龕窟（題擬）', '4d5ac266-8078-4948-bc1a-8e816e50e66f', '唐', '["久事公門奉駈馳，累沐鴻恩納效微。","昨登長坡上大阪，走下深谷覩花池。","傍通重開千龕窟，此谷昔聞萬佛輝。","瑞草芳芬而錦繡，祥鳥每常遶樹飛。","愚情從今歸真教，世間濁濫誓不歸。","（乾祐二年六月廿三日節度押衙張盈潤題。","見敦煌莫高窟第一○八窟窟檐南壁外側題壁，據《敦煌莫高窟供養人題記》。","）。"]', '["久事公门奉駈驰，累沐鴻恩納效微。","昨登长坡上大阪，走下深谷覩花池。","傍通重开千龕窟，此谷昔闻万佛輝。","瑞草芳芬而錦繡，祥鸟每常遶樹飞。","愚情從今归真教，世间濁濫誓不归。","（乾祐二年六月廿三日節度押衙張盈潤題。","见敦煌莫高窟第一○八窟窟檐南壁外側題壁，據《敦煌莫高窟供養人題記》。","）。"]', '诗', 'shi', '', NULL, '題敦煌千龕窟（題擬） 張盈潤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bdce0ca-080f-4101-ab42-f151d8c0beac', '句', '句', '03097b3a-f4c5-439e-bcd4-71b92437bced', '唐', '["三十年來塵撲面，如今始得一塗（施元之注《蘇東坡詩》《和張子野見寄三絕句》注引《小說》作「杴」）泥。","（見曾慥《類說》卷二六《後史補》。","）（〖1〗《後史補》云：「梁園有富家子杜四郎，好接文士，愛爲詩篇，時號杜荀鴨，以比荀鶴。","每有詩即題壁，親賓或汙漫之，即云〖略〗。","」《直齋書錄解題》小說家類載《後史補》爲「前進士高欲拙擢」。","因知四郎當爲唐末五代間人。","）。"]', '["三十年来塵撲面，如今始得一塗（施元之注《蘇东坡诗》《和張子野见寄三絕句》注引《小说》作「杴」）泥。","（见曾慥《類说》卷二六《後史補》。","）（〖1〗《後史補》云：「梁园有富家子杜四郎，好接文士，愛爲诗篇，时號杜荀鴨，以比荀鹤。","每有诗即題壁，親賓或汙漫之，即云〖略〗。","」《直斋书錄解題》小说家類載《後史補》爲「前進士高欲拙擢」。","因知四郎當爲唐末五代间人。","）。"]', '诗', 'shi', '', NULL, '句 杜四郎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26fe68e-7686-493c-96ad-faa5336cee5d', '體殻歌', '體殻歌', '92526c9a-6c65-4fa1-a10e-2ad74023a6a5', '唐', '["我今責這憨軀殻，只爲從前愛乖角。","三尸業鬼縱交往，一片身心難把捉。","六賊使得終朝亂，見色逢財將命𢬵。","身軀不覺業來纏，人前賣弄樓羅漢。","更說圖謀誇好手，資財營運磨星斗。","富如王愷與石崇，死後幽泉獨自走。","苦愛腥羶與穢濁，壞得身軀如刻削。","口中獨道得便宜，您是一場愚蠢朴。","蠢朴暫時聽我語，無限荒郊堆塚墓。","哀哉白骨被塵漫，往日英雄歸甚處？","不如聞早身心誨，免使沉埋爲下鬼。","時人一死無復生，浩浩東流如逝水。","我今求得長生訣，等閑休向他人說。","忽然誤慢泄天機，必遭神明暗地折。","（宋石泰輯《修真十書》卷十八《雜著捷徑》。","）。"]', '["我今責這憨軀殻，只爲從前愛乖角。","三尸業鬼縱交往，一片身心难把捉。","六賊使得終朝亂，见色逢財將命𢬵。","身軀不覺業来纏，人前賣弄楼羅漢。","更说圖謀誇好手，資財營運磨星斗。","富如王愷與石崇，死後幽泉独自走。","苦愛腥羶與穢濁，壞得身軀如刻削。","口中独道得便宜，您是一場愚蠢朴。","蠢朴暫时听我語，無限荒郊堆塚墓。","哀哉白骨被塵漫，往日英雄归甚处？","不如闻早身心誨，免使沉埋爲下鬼。","时人一死無复生，浩浩东流如逝水。","我今求得长生訣，等闲休向他人说。","忽然誤慢泄天機，必遭神明暗地折。","（宋石泰輯《修真十书》卷十八《杂著捷徑》。","）。"]', '诗', 'shi', '', NULL, '體殻歌 煙蘿子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('681d6234-a3f7-460e-ace7-c1c7ce662677', '', '', '00d22e6e-c211-43a6-8ac0-180df00e99d7', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b7e21d-cb17-47db-9800-4d015f9fa63c', '雞鳴', '雞鳴', '00d22e6e-c211-43a6-8ac0-180df00e99d7', '唐', '["一聲天欲曙，萬里客心行。","（《吟窗雜錄》卷十四正字王玄《詩中旨格》。","）。"]', '["一声天欲曙，万里客心行。","（《吟窗杂錄》卷十四正字王玄《诗中旨格》。","）。"]', '诗', 'shi', '', NULL, '雞鳴 李鶚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a091ae8d-a8dc-469f-9a63-380e5d1ef16f', '妙樂寺重修舍利塔碑附偈', '妙乐寺重修舍利塔碑附偈', '6a97fef4-524d-4381-bd69-8d9c3b36c96d', '唐', '["□□大聖尊，濁世中出現。","能化百億身，非論十八變。","欲調庶彙情，先與羣魔戰。","法鼓震祥雲，□□□□電。","衆生業重身，幾個遭逢見。","□緣聞佛名，□□覩佛面。","久居在世間，□衆懷厭賤。","是故現湼槃，□□□慕戀。","皆爲實滅度，豈識真方便。","□□靈鷲山，或游沙界遍。","國王得舍利，造塔餘八萬。","劫□□□□，此□重修建。","一心構勝緣，□載□弘願。","表剎既興隆，善緣□□□。","□志劫修業，虔誠禮供養。","□□□□主，□獲皆無量。","果位從此興，菩提漸無上。","今告衆多人，願欽衆妙相。","所陳簡直辭，□□□□□，無非居因緣，無非居典則。","審諦聽是言，勉勵植衆德。","願同□□□，當來遇彌勒。","（道光《武陟縣志》卷二一。","）。"]', '["□□大聖尊，濁世中出現。","能化百億身，非論十八变。","欲調庶彙情，先與羣魔戰。","法鼓震祥云，□□□□電。","衆生業重身，幾個遭逢见。","□緣闻佛名，□□覩佛面。","久居在世间，□衆懷厭賤。","是故現湼槃，□□□慕戀。","皆爲實滅度，豈識真方便。","□□靈鷲山，或游沙界遍。","国王得舍利，造塔餘八万。","劫□□□□，此□重修建。","一心構勝緣，□載□弘願。","表剎既兴隆，善緣□□□。","□志劫修業，虔誠禮供養。","□□□□主，□獲皆無量。","果位從此兴，菩提漸無上。","今告衆多人，願欽衆妙相。","所陳簡直辞，□□□□□，無非居因緣，無非居典則。","審諦听是言，勉勵植衆德。","願同□□□，當来遇彌勒。","（道光《武陟縣志》卷二一。","）。"]', '诗', 'shi', '', NULL, '妙樂寺重修舍利塔碑附偈 蘇允平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7905001-4bac-4624-9a8f-8077f369703d', '與監修國史趙瑩詩', '與監修国史趙瑩诗', '3f1b613d-d3c0-4095-a1ef-f332c3d1ae05', '唐', '["滿（《吟窗雜錄》作「清」）朝唯我相，秉柄無親讎。","三年司大董，最切是編修。","史才不易得，勤勤處處求。","愚從年始立，東[觀]（望）思優遊。","昔時人未許，今來虛白頭。","春臺與秋閣，往往興歸愁。","信運北闕下，不繫如虛舟。","綿蕝非所好，一日疑三秋。","何當適所願，便如適瀛洲。","（見中華書局校點本《舊五代史》卷一三一《賈緯傳》。","《吟窗雜錄》卷二十八錄首四句。","）。"]', '["满（《吟窗杂錄》作「清」）朝唯我相，秉柄無親讎。","三年司大董，最切是編修。","史才不易得，勤勤处处求。","愚從年始立，东[观]（望）思優游。","昔时人未許，今来虛白头。","春台與秋閣，往往兴归愁。","信運北闕下，不繫如虛舟。","綿蕝非所好，一日疑三秋。","何當適所願，便如適瀛洲。","（见中华书局校点本《旧五代史》卷一三一《賈緯傳》。","《吟窗杂錄》卷二十八錄首四句。","）。"]', '诗', 'shi', '', NULL, '與監修國史趙瑩詩 賈緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a05d43e7-48a3-44f2-93a2-2abfcf77124e', '', '', 'e465938f-8ecd-4baa-8d41-f4f7e01840be', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 徐台符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f25d159-1b38-4113-9748-bcfb919773fa', '哀韓璆（題擬）', '哀韓璆（題擬）', 'e465938f-8ecd-4baa-8d41-f4f7e01840be', '唐', '["穹昊何事教埋玉，朋友無由繼斷金。","（《安陽集》卷四六《叙先考令公遺事與尹龍圖書》引。","）。"]', '["穹昊何事教埋玉，朋友無由繼斷金。","（《安陽集》卷四六《叙先考令公遺事與尹龙圖书》引。","）。"]', '诗', 'shi', '', NULL, '哀韓璆（題擬） 徐台符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3564eb6-c166-4e54-b4fc-a3d450a93bed', '平日自詠（題擬）', '平日自詠（題擬）', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["公事之餘喜坐禪，少曾將脅到牀眠。","雖然現出宰官相，長老之名天下傳。","（見宋金盈之八卷本《醉翁談錄》卷六。","）（〖1〗《醉翁談錄》：「近代馮相於中書退朝之暇，未始不以坐禪爲念。","故天下萬口一詞，遂以馮長老之名歸之，況馮相平日自有詩曰〖略〗。","」）。"]', '["公事之餘喜坐禪，少曾將脅到牀眠。","雖然現出宰官相，长老之名天下傳。","（见宋金盈之八卷本《醉翁談錄》卷六。","）（〖1〗《醉翁談錄》：「近代馮相於中书退朝之暇，未始不以坐禪爲念。","故天下万口一词，遂以馮长老之名归之，況馮相平日自有诗曰〖略〗。","」）。"]', '诗', 'shi', '', NULL, '平日自詠（題擬） 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b928d9-6859-4bad-bd84-de2f1bb1b3e3', '使虜詩', '使虜诗', '1753125f-3024-4c68-9740-55d160b396e0', '唐', '["曾叨臘月牛頭賜。","（見宋程大昌《演繁露》卷十三《牛魚》。","）。"]', '["曾叨臘月牛头賜。","（见宋程大昌《演繁露》卷十三《牛鱼》。","）。"]', '诗', 'shi', '', NULL, '使虜詩 馮道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b1c5af-6284-48b7-ad51-32052ec9b6ac', '判酒務吏乞以家財修夫子廟（題擬）', '判酒務吏乞以家財修夫子廟（題擬）', 'ceeb6aea-985b-48bf-a5fd-9598f82755a1', '唐', '["荆棘森森遶杏壇，儒官高貴盡偷安。","若教酒務修夫子，覺我慚惶也大難。","（見宋陶岳《五代史補》卷三。","）（按：《全唐詩》卷八七○據《古今詩話》收此詩歸馮道幕客，廿八字中有十八字不同，雖爲一詩，而輾轉相傳，已失初）（貌。","今據最早記錄該詩的《五代史補》重錄。","）。"]', '["荆棘森森遶杏壇，儒官高貴尽偷安。","若教酒務修夫子，覺我慚惶也大难。","（见宋陶岳《五代史補》卷三。","）（按：《全唐诗》卷八七○據《古今诗話》收此诗归馮道幕客，廿八字中有十八字不同，雖爲一诗，而輾轉相傳，已失初）（貌。","今據最早記錄該诗的《五代史補》重錄。","）。"]', '诗', 'shi', '', NULL, '判酒務吏乞以家財修夫子廟（題擬） 同州判官 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf5b1bd-f7eb-4dd8-bdfe-90ed1fce831c', '放魚歌', '放鱼歌', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["骨鱗骨□皆龍子。","（見宋龔鼎臣《東原錄》。","）。"]', '["骨鱗骨□皆龙子。","（见宋龔鼎臣《东原錄》。","）。"]', '诗', 'shi', '', NULL, '放魚歌 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dc0ab82-e7d6-4b8e-9014-c7d77fec8048', '宮詞（第九十首）', '宮词（第九十首）', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["邊藩開宴賀休征，細仗初排舜日明。","坐定兩重呈百戲，樂臣低折賀昇平。","（《全五代詩》卷十一。","）（按：《全唐詩》卷七三五錄此詩缺一字，今重錄。","）。"]', '["邊藩开宴賀休征，細仗初排舜日明。","坐定兩重呈百戲，乐臣低折賀昇平。","（《全五代诗》卷十一。","）（按：《全唐诗》卷七三五錄此诗缺一字，今重錄。","）。"]', '诗', 'shi', '', NULL, '宮詞（第九十首） 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81463a95-62a7-4f2e-9a51-e77ce5f79b90', '洋川 一', '洋川 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["華夷圖上見洋川，知在青山綠水邊。","[□□□□□□□，□□□□□□□]。","官閑最好遊僧舍，江近應須買釣船，更待浹旬無事後，徧題清景作詩仙。","（見王象之《輿地紀勝》卷一九○。","）。"]', '["华夷圖上见洋川，知在青山綠水邊。","[□□□□□□□，□□□□□□□]。","官闲最好游僧舍，江近應須買釣船，更待浹旬無事後，徧題清景作诗仙。","（见王象之《輿地紀勝》卷一九○。","）。"]', '诗', 'shi', '', NULL, '洋川 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284fdf24-d14b-46d2-9218-6b84944cd2f5', '洋川 二', '洋川 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["自陪台旆到洋川，兩載優遊漢水邊。","（同前。","）（按：《全唐詩》卷七三五以「華夷」、「官閑」二聯爲七絕一首，係據《唐音戊籤餘》四轉錄，後者又係輯自宋祝穆《方輿勝覽》卷六八。","今據《輿地紀勝》所載及詩律推之，原詩當爲七律，頷聯二句已佚。","《全唐詩續補遺》卷十四將「自陪」二句接於「官閑」四句前，實誤，今重錄之。","）。"]', '["自陪台旆到洋川，兩載優游漢水邊。","（同前。","）（按：《全唐诗》卷七三五以「华夷」、「官闲」二聯爲七絕一首，係據《唐音戊籤餘》四轉錄，後者又係輯自宋祝穆《方輿勝覽》卷六八。","今據《輿地紀勝》所載及诗律推之，原诗當爲七律，頷聯二句已佚。","《全唐诗續補遺》卷十四將「自陪」二句接於「官闲」四句前，實誤，今重錄之。","）。"]', '诗', 'shi', '', NULL, '洋川 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a711bd60-1595-4014-b534-d9e878a0db91', '懷荆州諸友', '懷荆州諸友', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["王粲南遊後，年年事轉新。","應無故國夢，誰怨武陵春。","信杳愁歸鴈，書成問去人。","中心不可寄，綠水與紅塵。","（影印本《詩淵》第一冊第二四五頁。","）。"]', '["王粲南游後，年年事轉新。","應無故国梦，誰怨武陵春。","信杳愁归鴈，书成问去人。","中心不可寄，綠水與紅塵。","（影印本《诗淵》第一冊第二四五頁。","）。"]', '诗', 'shi', '', NULL, '懷荆州諸友 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2b9d035-3faf-422d-9b74-7341002eae5f', '南遊有懷', '南游有懷', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["懷才非獨步，驅馬出荆州。","親老未歸去，路長何處遊？","鳥啼雲夢曉，葉落洞庭秋。","襟抱誰相問？西風吹客愁。","（同前書第二六九頁。","）。"]', '["懷才非独步，驱马出荆州。","親老未归去，路长何处游？","鸟啼云梦晓，葉落洞庭秋。","襟抱誰相问？西风吹客愁。","（同前书第二六九頁。","）。"]', '诗', 'shi', '', NULL, '南遊有懷 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27f933e-f756-415f-90e5-ed8471af0ca4', '秋日途中', '秋日途中', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["滿眼水吾土，征輪尚遠遊。","田園虛自廢，禾黍美□秋。","日暮烏猶返，風高雲自收。","因循不歸去，歧路猶何求？","（同前第三冊第二二一○頁。","）。"]', '["满眼水吾土，征輪尚远游。","田园虛自廢，禾黍美□秋。","日暮烏猶返，风高云自收。","因循不归去，歧路猶何求？","（同前第三冊第二二一○頁。","）。"]', '诗', 'shi', '', NULL, '秋日途中 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a09db32a-c134-4447-a2b3-51a409ff5567', '再宿友生郊居', '再宿友生郊居', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["終日走歧路，唯君守草堂。","重來身若舊，相見話偏長。","夜半四鄰靜，雨餘羣本香。","不能同此住，名利自茫茫。","（同前第五冊第三一五八頁。","）。"]', '["終日走歧路，唯君守草堂。","重来身若旧，相见話偏长。","夜半四鄰静，雨餘羣本香。","不能同此住，名利自茫茫。","（同前第五冊第三一五八頁。","）。"]', '诗', 'shi', '', NULL, '再宿友生郊居 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa361bc-ddee-45f2-8fd0-8c9eec45d06d', '宿彈琴張處士所居', '宿彈琴張处士所居', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["聞君鼓七絲，□我暫忘機。","莫謂知音少，都緣能□稀。","無風過竹檻，有月照柴扉。","一弄一杯酒，坐來霜□衣。","（同前第三五○四頁。","）。"]', '["闻君鼓七絲，□我暫忘機。","莫謂知音少，都緣能□稀。","無风過竹檻，有月照柴扉。","一弄一杯酒，坐来霜□衣。","（同前第三五○四頁。","）。"]', '诗', 'shi', '', NULL, '宿彈琴張處士所居 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954cae91-578d-4641-9c2b-064d019836c9', '擬古', '擬古', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["涼風搖翠袂，倚檻恨難平。","遠路人無信，西樓月又生。","菱花消舊態，瑤瑟續新聲。","暗覺新聲苦，夫誰知此情？","（同前第六冊第三八九七頁）。"]', '["涼风搖翠袂，倚檻恨难平。","远路人無信，西楼月又生。","菱花消旧態，瑤瑟續新声。","暗覺新声苦，夫誰知此情？","（同前第六冊第三八九七頁）。"]', '诗', 'shi', '', NULL, '擬古 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e7a34e-13e6-4867-828d-c3dbc28dc61c', '送進士董位', '送進士董位', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["送君偏起恨，醲酒亦難消。","爲客日己久，還家路各遙。","雲繁天欲雪，林迥野初燒。","何處期相見，春風滿路招。","（同前第四三三七頁。","）。"]', '["送君偏起恨，醲酒亦难消。","爲客日己久，還家路各遙。","云繁天欲雪，林迥野初燒。","何处期相见，春风满路招。","（同前第四三三七頁。","）。"]', '诗', 'shi', '', NULL, '送進士董位 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a5bc1b0-68e3-4b92-a93b-04a70b89cf71', '送友人歸荆', '送友人归荆', '25b7a736-f7c2-45d3-a813-01b115c4f1bd', '唐', '["帝城多美酒，不醉別離人。","北海謀歸晚，東門送客頻。","燕啼迎館樹，草色逐征輪。","到日逢鄉友，如何話此身？","（同前第四三八三頁。","）。"]', '["帝城多美酒，不醉別離人。","北海謀归晚，东门送客頻。","燕啼迎館樹，草色逐征輪。","到日逢乡友，如何話此身？","（同前第四三八三頁。","）。"]', '诗', 'shi', '', NULL, '送友人歸荆 龔霖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b981de-6096-4e5f-981e-06a461c70c62', '謝學士遺茶（題擬）', '謝学士遺茶（題擬）', '5ed511ec-9b8d-4614-99f8-b389567e2142', '唐', '["粗官乞與真虛擲，賴有詩情合得嘗。","（《青瑣高議前集》卷五。","）。"]', '["粗官乞與真虛擲，賴有诗情合得嘗。","（《青瑣高議前集》卷五。","）。"]', '诗', 'shi', '', NULL, '謝學士遺茶（題擬） 五代外鎮官 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5398cb-69f4-4c1f-b785-c988a8dc3c79', '長興中題杜光寺（題擬）', '长兴中題杜光寺（題擬）', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["上爾高僧更不疑，夢乘龍駕落沉暉。","寒暄暈映琉璃殿，曉夜摧殘毳衲衣。","金體幾生傳有漏，玉容三界自無非。","莓苔滿院人稀到，松畔香臺野鶴飛。","（見元駱天驤《類編長安志》寺觀類杜光寺條，云長興中王仁裕題詩云云。","據《中國古都研究》收黃永年先生《述〈類編長安志〉》轉錄。","）。"]', '["上爾高僧更不疑，梦乘龙駕落沉暉。","寒暄暈映琉璃殿，晓夜摧殘毳衲衣。","金體幾生傳有漏，玉容三界自無非。","莓苔满院人稀到，松畔香台野鹤飞。","（见元駱天驤《類編长安志》寺观類杜光寺條，云长兴中王仁裕題诗云云。","據《中国古都研究》收黄永年先生《述〈類編长安志〉》轉錄。","）。"]', '诗', 'shi', '', NULL, '長興中題杜光寺（題擬） 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10729560-27b1-4513-93e6-688956213ea2', '戮後主出降詩', '戮後主出降诗', '0f43bbed-4f41-40c9-b69f-c4217c5bf3e4', '唐', '["蜀朝昏主出降時，銜璧牽羊倒繫旗。","二十萬軍高拱手，更無一箇是男兒。","（涵芬樓排印本《說郛》卷三十四《豪異秘纂》引王仁裕《蜀石》。","）（按：此詩《鑑誡錄》卷五《徐后事》謂王承旨作，《後山詩話》則以爲花蕊夫人作，文字略異。","《全唐詩》卷七九八收花蕊名下，另注「一作蜀臣王承旨詩」。","《全唐詩續補遺》卷十七據《鑑誡錄》收歸王承旨。","今檢《說郛》所引，與《鑑誡錄》所載較相似，而於此詩作者，則云爲「興聖太子隨軍仁裕」。","王仁裕初仕前蜀，嘗隨侍王衍作詩，蜀亡入洛，仕後唐。","《說郛》所載可從，今爲移正。","）。"]', '["蜀朝昏主出降时，銜璧牽羊倒繫旗。","二十万軍高拱手，更無一箇是男兒。","（涵芬楼排印本《说郛》卷三十四《豪異秘纂》引王仁裕《蜀石》。","）（按：此诗《鑑誡錄》卷五《徐后事》謂王承旨作，《後山诗話》則以爲花蕊夫人作，文字略異。","《全唐诗》卷七九八收花蕊名下，另注「一作蜀臣王承旨诗」。","《全唐诗續補遺》卷十七據《鑑誡錄》收归王承旨。","今檢《说郛》所引，與《鑑誡錄》所載較相似，而於此诗作者，則云爲「兴聖太子隨軍仁裕」。","王仁裕初仕前蜀，嘗隨侍王衍作诗，蜀亡入洛，仕後唐。","《说郛》所載可從，今爲移正。","）。"]', '诗', 'shi', '', NULL, '戮後主出降詩 王仁裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d4a0bed-8324-435f-8863-b95d2d95b502', '芭蕉詩', '芭蕉诗', '7754a32e-5145-4419-a1c3-9e888c866296', '唐', '["野人無帳幄，愛此綠參差。","。"]', '["野人無帳幄，愛此綠參差。","。"]', '诗', 'shi', '', NULL, '芭蕉詩 胡嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c13de63-748a-4c90-aa03-bdbe68d1476b', '句', '句', '7754a32e-5145-4419-a1c3-9e888c866296', '唐', '["瓶裏數枝婪尾春。","（均見《說郛》卷六一《清異錄》。","）。"]', '["瓶裏數枝婪尾春。","（均见《说郛》卷六一《清異錄》。","）。"]', '诗', 'shi', '', NULL, '句 胡嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('373fe4b1-af0a-4e65-bd79-d517c610720d', '起居帖', '起居帖', '8077d785-889a-4445-9266-15e590cb382a', '唐', '["行住坐臥處，手摩脅與肚，心腹通快時，兩手腸下踞。","踞之徹膀腰，背拳摩腎部。","纔覺力倦來，即使家人助。","行之不厭頻，晝夜無窮數，歲久積功成，漸入神仙路。","（見明刻本朱存理輯《鐵網珊瑚·書品》卷一。","）（按：詩後題云：「乾祐元年冬殘臘暮，華陽焦上人尊師處傳，楊凝式。","」又附米友仁跋云：「右楊凝式書神仙起居法八行，臣米友仁鑒定真蹟跋。","」）。"]', '["行住坐臥处，手摩脅與肚，心腹通快时，兩手腸下踞。","踞之徹膀腰，背拳摩腎部。","纔覺力倦来，即使家人助。","行之不厭頻，晝夜無窮數，歲久積功成，漸入神仙路。","（见明刻本朱存理輯《鐵網珊瑚·书品》卷一。","）（按：诗後題云：「乾祐元年冬殘臘暮，华陽焦上人尊師处傳，楊凝式。","」又附米友仁跋云：「右楊凝式书神仙起居法八行，臣米友仁鑒定真蹟跋。","」）。"]', '诗', 'shi', '', NULL, '起居帖 楊凝式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('471b4145-59f8-458c-91c3-47993c61073a', '偈', '偈', '2f38d749-d3ce-4d20-92ce-8a0e1fa41d03', '唐', '["我有一間舍，父母爲修蓋。","住來八十年，近來覺損壞。","早擬移住（《五燈會元》作「別」）處，事涉有憎愛。","待他摧毀時，彼此無相礙。","（見《景德傳燈錄》卷二十、《五燈會元》卷十三。","）。"]', '["我有一间舍，父母爲修蓋。","住来八十年，近来覺損壞。","早擬移住（《五灯會元》作「別」）处，事涉有憎愛。","待他摧毀时，彼此無相礙。","（见《景德傳灯錄》卷二十、《五灯會元》卷十三。","）。"]', '诗', 'shi', '', NULL, '偈 智暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb547c5b-fec2-417a-8066-65f5e3e818fa', '贈同居友人', '贈同居友人', 'f00e1f75-dc09-4d86-a67e-02f9ad15c6bb', '唐', '["有情天地內，多感是詩人。","見月長憐夜，看花又惜春。","愁爲終日客，閑過少年身。","寂寞正相對，笙歌滿四隣。","（影印本《詩淵》，第一冊第三七七頁。","）。"]', '["有情天地內，多感是诗人。","见月长怜夜，看花又惜春。","愁爲終日客，闲過少年身。","寂寞正相对，笙歌满四隣。","（影印本《诗淵》，第一冊第三七七頁。","）。"]', '诗', 'shi', '', NULL, '贈同居友人 符蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da75362-561b-4bbf-aba3-e0118fd518e2', '贈張山人', '贈張山人', 'f00e1f75-dc09-4d86-a67e-02f9ad15c6bb', '唐', '["五字誰能摘？一枝猶未攀。","始知無價玉，出自有名山。","春靜煙花秀，夜深風月閑。","如何恃高節，垂老住雲間？","（同上書第四三五頁。","）。"]', '["五字誰能摘？一枝猶未攀。","始知無價玉，出自有名山。","春静煙花秀，夜深风月闲。","如何恃高節，垂老住云间？","（同上书第四三五頁。","）。"]', '诗', 'shi', '', NULL, '贈張山人 符蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad723459-4752-488b-a69f-461f0cab20ae', '春日潛溪寓居', '春日潛溪寓居', 'f00e1f75-dc09-4d86-a67e-02f9ad15c6bb', '唐', '["衆山圍四合，月色到門遲。","石面和雲坐，花根帶土移。","竹斜當徑筍，松斫逼樓枝。","正抱流年恨，芳春不我知。","（同前第五冊第三五○○頁。","）。"]', '["衆山圍四合，月色到门遲。","石面和云坐，花根带土移。","竹斜當徑筍，松斫逼楼枝。","正抱流年恨，芳春不我知。","（同前第五冊第三五○○頁。","）。"]', '诗', 'shi', '', NULL, '春日潛溪寓居 符蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da28da86-4bcc-4030-887e-01ac52353c23', '贈山翁', '贈山翁', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["松蘿深處住，閑野不生愁。","鳥語煙嵐靜，水聲門戶秋。","花間歸洞路，山下釣魚舟。","沐浴聖王化，自憐絲滿頭。","（影印本《詩淵》第一冊第四九一頁。","）。"]', '["松蘿深处住，闲野不生愁。","鸟語煙嵐静，水声门戶秋。","花间归洞路，山下釣鱼舟。","沐浴聖王化，自怜絲满头。","（影印本《诗淵》第一冊第四九一頁。","）。"]', '诗', 'shi', '', NULL, '贈山翁 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8c560f-c7d3-4d76-9fb6-d6d787ad7344', '題處士林亭', '題处士林亭', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["帝里高人宅，蒼苔遶徑深。","卷簾山入戶，摘菓鳥移林。","石沼養龜水，月臺留客琴。","生涯一樽酒，名利不關心。","（同前第五冊第三一二三頁。","）。"]', '["帝里高人宅，蒼苔遶徑深。","卷簾山入戶，摘菓鸟移林。","石沼養龟水，月台留客琴。","生涯一樽酒，名利不关心。","（同前第五冊第三一二三頁。","）。"]', '诗', 'shi', '', NULL, '題處士林亭 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ec168c3-7af5-4262-b6bb-64b9fc7f0d53', '抄逆刺占後題（題擬） 一', '抄逆刺占後題（題擬） 一', 'e70917bd-ee2b-4188-abfc-2772549ebb83', '唐', '["三端俱全大丈夫，六藝堂堂世上無。","男兒不學讀詩賦，恰似肥菜根盡枯。"]', '["三端俱全大丈夫，六藝堂堂世上無。","男兒不学读诗賦，恰似肥菜根尽枯。"]', '诗', 'shi', '', NULL, '抄逆刺占後題（題擬） 一 翟奉達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9dc35a-c7e9-4a2c-a62e-879790f461cd', '抄逆刺占後題（題擬） 二', '抄逆刺占後題（題擬） 二', 'e70917bd-ee2b-4188-abfc-2772549ebb83', '唐', '["軀體堂堂六尺餘，走筆橫波紙上飛。","執筆題篇須意用，後任將身選文知。"]', '["軀體堂堂六尺餘，走笔橫波紙上飞。","執笔題篇須意用，後任將身選文知。"]', '诗', 'shi', '', NULL, '抄逆刺占後題（題擬） 二 翟奉達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37b75e42-c41f-4d87-9da2-06342bd1dffd', '抄逆刺占後題（題擬） 三', '抄逆刺占後題（題擬） 三', 'e70917bd-ee2b-4188-abfc-2772549ebb83', '唐', '["哽噎卑末手，抑塞多不謬。","嵯峨難遙望，恐怕年終朽。","（見向達《唐代長安與西域文明·記敦煌石室出晉天福十年寫本壽昌縣地境》引敦煌所出天復二年翟奉達寫《逆刺占》卷末題詩。","原卷流落敦煌某氏，今不詳所在。","）（按：向達同書《西征小記》云《逆刺占》末翟題云：「于時天復貳載歲在壬戌四月丁丑朔七日，河西燉煌郡州學上足子弟翟再溫記。","」姓名旁注曰：「再溫字奉達也。","」其後錄詩三首。","前引文錄詩後復題云：「幼年作之，多不當路。","今笑，）（今笑。","已前達走筆題撰之耳。","年廿作，今年邁見此詩，羞煞人，羞煞人。","」）。"]', '["哽噎卑末手，抑塞多不謬。","嵯峨难遙望，恐怕年終朽。","（见向達《唐代长安與西域文明·記敦煌石室出晉天福十年寫本壽昌縣地境》引敦煌所出天复二年翟奉達寫《逆刺占》卷末題诗。","原卷流落敦煌某氏，今不詳所在。","）（按：向達同书《西征小記》云《逆刺占》末翟題云：「于时天复貳載歲在壬戌四月丁丑朔七日，河西燉煌郡州学上足子弟翟再溫記。","」姓名旁注曰：「再溫字奉達也。","」其後錄诗三首。","前引文錄诗後复題云：「幼年作之，多不當路。","今笑，）（今笑。","已前達走笔題撰之耳。","年廿作，今年邁见此诗，羞煞人，羞煞人。","」）。"]', '诗', 'shi', '', NULL, '抄逆刺占後題（題擬） 三 翟奉達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7841b212-63a1-41a9-b073-2484254085a5', '贈李昉（題擬）', '贈李昉（題擬）', '2a3ebd9f-6eee-41d0-9919-5f90dee97803', '唐', '["反觀西里盛，世世秉鈞衡。","（見《增修詩話總龜》卷三引《翰府名談》。","）（〖1〗《翰府名談》：「丞相李文正公昉少年時嘗以詩呈叔侍中，覽而喜，贈之詩曰〖略〗。","後文正果大用，詔賜所居爲謝元卿秉鈞里。","」）。"]', '["反观西里盛，世世秉鈞衡。","（见《增修诗話總龟》卷三引《翰府名談》。","）（〖1〗《翰府名談》：「丞相李文正公昉少年时嘗以诗呈叔侍中，覽而喜，贈之诗曰〖略〗。","後文正果大用，詔賜所居爲謝元卿秉鈞里。","」）。"]', '诗', 'shi', '', NULL, '贈李昉（題擬） 李沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c79ac3d-f8a6-47a2-9fc7-2fb1e3cbdb19', '柬范丞相質', '柬范丞相質', '8ce03e0e-0b03-4a28-a3b5-0397d67bd213', '唐', '["禁秘同依日月光，分宣政拙得遐方。","半生報國心猶赤，萬里籌邊鬢已蒼。","却憶西陲誇短馭，曾陪東閣賦長楊。","迢迢雲樹今如許，謂朔春深正渺茫。","（見清戚鶴泉編《三台詩錄》卷一。","張靖龍云：「見清王魏《安洲詩錄》卷一。","」）。"]', '["禁秘同依日月光，分宣政拙得遐方。","半生報国心猶赤，万里籌邊鬢已蒼。","却憶西陲誇短馭，曾陪东閣賦长楊。","迢迢云樹今如許，謂朔春深正渺茫。","（见清戚鹤泉編《三台诗錄》卷一。","張靖龙云：「见清王魏《安洲诗錄》卷一。","」）。"]', '诗', 'shi', '', NULL, '柬范丞相質 張文伏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a87ff6-c2e1-4441-a317-3985176f1af2', '賀李昉除翰林學士（題擬）', '賀李昉除翰林学士（題擬）', 'e74fd3a3-902d-4fe9-9d98-b3113de59f9f', '唐', '["翰苑重求李謫仙，詞鋒穎利勝龍泉。","朝趨建禮霞烘日，夜直承明月映天。","聖主重知緣國士。","相公多喜爲同年。","青春才子金門貴。","蜀錦袍新奪日鮮。","（周本淳校點本《詩話總龜》卷二七引《古今詩話》。","此詩爲周世宗征淮南間作。","）。"]', '["翰苑重求李謫仙，词鋒穎利勝龙泉。","朝趨建禮霞烘日，夜直承明月映天。","聖主重知緣国士。","相公多喜爲同年。","青春才子金门貴。","蜀錦袍新奪日鲜。","（周本淳校点本《诗話總龟》卷二七引《古今诗話》。","此诗爲周世宗征淮南间作。","）。"]', '诗', 'shi', '', NULL, '賀李昉除翰林學士（題擬） 范質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08f44c2b-8133-438a-847d-e831ea50cb58', '岳陽樓詩（題擬） 一', '岳陽楼诗（題擬） 一', 'e74fd3a3-902d-4fe9-9d98-b3113de59f9f', '唐', '["煙容雲態四溟濛，州在波濤洶湧東。"]', '["煙容云態四溟濛，州在波濤洶湧东。"]', '诗', 'shi', '', NULL, '岳陽樓詩（題擬） 一 范質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc559065-ec17-4856-b643-fc4e812c64f7', '岳陽樓詩（題擬） 二', '岳陽楼诗（題擬） 二', 'e74fd3a3-902d-4fe9-9d98-b3113de59f9f', '唐', '["地收楚蜀西南水，天與江湖旦暮風。","（按：以上兩聯屬同一首詩。","原詩應爲七律。","）。"]', '["地收楚蜀西南水，天與江湖旦暮风。","（按：以上兩聯屬同一首诗。","原诗應爲七律。","）。"]', '诗', 'shi', '', NULL, '岳陽樓詩（題擬） 二 范質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085b20bb-eef6-45ea-bf2c-8de7280fd94f', '岳陽樓詩（題擬） 三', '岳陽楼诗（題擬） 三', 'e74fd3a3-902d-4fe9-9d98-b3113de59f9f', '唐', '["可笑祖龍遊不得，欲於何處訪蓬萊。","（見《輿地紀勝》卷六九《岳州》。","）（按：范質入宋後，均在汴京。","詩爲其早年作。","）。"]', '["可笑祖龙游不得，欲於何处訪蓬萊。","（见《輿地紀勝》卷六九《岳州》。","）（按：范質入宋後，均在汴京。","诗爲其早年作。","）。"]', '诗', 'shi', '', NULL, '岳陽樓詩（題擬） 三 范質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b698638e-858b-4a85-8591-176bd67e25cc', '宗風頌', '宗风頌', '846dda29-9077-4163-9218-cc10cef1489d', '唐', '["從上綱宗事最奇，卷舒生殺切須知。","臨機便有威雄勢，賓主相呈縱奪時。","不若食龍金翅鳥，當鋒一撮更難支。","現成公案睦州斷，四門有路趙州機。","仰山插鍬猶因地，雲門關捩幾人知？","鏡清失利多風措，高亭送客看臨歧。","本分家風依時節，夾山典座得便宜。","唯有龍潭吹滅燭，德山諦實更無疑。","不是等閑虛妄說，呵佛駡祖天下知。","自古綱宗難隱跡，如今著眼直須窺。","秖道尋常記得徹，洎乎把住眼如{目虽}。","敵磕便須大哮吼，莫作埜犴狐兔兒。","斯吒落水休吐氣，密嘌智深誰瞻伊。","提綱盡有同風事，好看雲門顧鑒咦。","（《天聖廣燈錄》卷二十。","）。"]', '["從上綱宗事最奇，卷舒生殺切須知。","臨機便有威雄勢，賓主相呈縱奪时。","不若食龙金翅鸟，當鋒一撮更难支。","現成公案睦州斷，四门有路趙州機。","仰山插鍬猶因地，云门关捩幾人知？","镜清失利多风措，高亭送客看臨歧。","本分家风依时節，夾山典座得便宜。","唯有龙潭吹滅燭，德山諦實更無疑。","不是等闲虛妄说，呵佛駡祖天下知。","自古綱宗难隐跡，如今著眼直須窺。","秖道尋常記得徹，洎乎把住眼如{目虽}。","敵磕便須大哮吼，莫作埜犴狐兔兒。","斯吒落水休吐氣，密嘌智深誰瞻伊。","提綱尽有同风事，好看云门顧鑒咦。","（《天聖廣灯錄》卷二十。","）。"]', '诗', 'shi', '', NULL, '宗風頌 法覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbbb05d0-5570-4963-b9f3-25bb7d93998f', '偈', '偈', '56331095-f6fd-434e-9f05-c02abbe36028', '唐', '["纔到洪山便跥跟，四方八面不言論。","他家自有眠雲志，蘆管橫吹宇宙喧。","（《景德傳燈錄》卷二十、《五燈會元》卷十四。","）（按：《五燈會元》作「義禪師」，其師作「延禪師」，今從《景德傳燈錄》及《天聖廣燈錄》卷二十四目錄。","）。"]', '["纔到洪山便跥跟，四方八面不言論。","他家自有眠云志，蘆管橫吹宇宙喧。","（《景德傳灯錄》卷二十、《五灯會元》卷十四。","）（按：《五灯會元》作「義禪師」，其師作「延禪師」，今從《景德傳灯錄》及《天聖廣灯錄》卷二十四目錄。","）。"]', '诗', 'shi', '', NULL, '偈 延禪師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f1a99e-34f3-4660-9171-888be53ebb10', '', '', 'dddf9f2f-df91-461a-a2a0-fdd2b316339e', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 竇儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c97977-ced5-4a8f-a5eb-bfcdded3e4f6', '賀李昉除翰林學士（題擬）', '賀李昉除翰林学士（題擬）', 'dddf9f2f-df91-461a-a2a0-fdd2b316339e', '唐', '["廐馬牽來噦噦嘶，馬蹄隨步躡雲梯。","新街錦帳達三字，舊制星垣放五題。","視草健毫從席遠，受降恩詔待公批。","仙才已在神仙地，逢見劉晨爲指迷。","（周本淳校本《詩話總龜》卷二七引《古今詩話》。","爲後周時作。","）。"]', '["廐马牽来噦噦嘶，马蹄隨步躡云梯。","新街錦帳達三字，旧制星垣放五題。","視草健毫從席远，受降恩詔待公批。","仙才已在神仙地，逢见劉晨爲指迷。","（周本淳校本《诗話總龟》卷二七引《古今诗話》。","爲後周时作。","）。"]', '诗', 'shi', '', NULL, '賀李昉除翰林學士（題擬） 竇儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453c1257-d259-4482-9eb8-2674e5f17b79', '北海題渚宮', '北海題渚宮', '36a94896-a4ee-4850-9e29-4e2e844cba51', '唐', '["紀南南望水城寬，水色天光混一般。","大抵江鄉足詩景，詠吟如把畫圖看。","（見《輿地紀勝》卷六五《江陵府》。","）。"]', '["紀南南望水城寬，水色天光混一般。","大抵江乡足诗景，詠吟如把畫圖看。","（见《輿地紀勝》卷六五《江陵府》。","）。"]', '诗', 'shi', '', NULL, '北海題渚宮 竇儼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c615de4-40a9-469a-bbf4-4f341bdb6d57', '石橋', '石橋', '06d0f8f9-5146-427a-8d69-ba7b869b2afc', '唐', '["重重翠嶂聳雲端，玉殿金樓縹緲間。","聖境不容凡俗到，故將飛瀑隔塵寰。","（見《天台續集》卷中。","）。"]', '["重重翠嶂聳云端，玉殿金楼縹緲间。","聖境不容凡俗到，故將飞瀑隔塵寰。","（见《天台續集》卷中。","）。"]', '诗', 'shi', '', NULL, '石橋 陶穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93182151-805b-4116-9f71-aee07fcae386', '謝吳越王贈金鐘（題擬）', '謝吳越王贈金鐘（題擬）', '06d0f8f9-5146-427a-8d69-ba7b869b2afc', '唐', '["乞與金鐘病眼明。","。"]', '["乞與金鐘病眼明。","。"]', '诗', 'shi', '', NULL, '謝吳越王贈金鐘（題擬） 陶穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66796089-b8a1-42ad-a6ff-32e1878eae6b', '使吳越臨出境賦詩於郵亭（題擬）', '使吳越臨出境賦诗於郵亭（題擬）', '06d0f8f9-5146-427a-8d69-ba7b869b2afc', '唐', '["井蛙休恃重溟險，澤馬曾嘶九曲濱。","（均見《百川學海》本夷門君玉《國老談苑》。","）（按：以上一首三句均爲陶穀自宋使吳越時作，姑附存。","）。"]', '["井蛙休恃重溟險，澤马曾嘶九曲濱。","（均见《百川学海》本夷门君玉《国老談苑》。","）（按：以上一首三句均爲陶穀自宋使吳越时作，姑附存。","）。"]', '诗', 'shi', '', NULL, '使吳越臨出境賦詩於郵亭（題擬） 陶穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91fab729-0ac2-428d-a7eb-e86ac81cc464', '句', '句', '06d0f8f9-5146-427a-8d69-ba7b869b2afc', '唐', '["尖簷帽子卑凡廝，短靿靴兒末厥兵。","（《六一詩話》。","）。"]', '["尖簷帽子卑凡廝，短靿靴兒末厥兵。","（《六一诗話》。","）。"]', '诗', 'shi', '', NULL, '句 陶穀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5dcddd-59f7-4e4a-a2e3-e20c2a0e3d47', '日詩', '日诗', 'cbe26bad-6b1f-495d-9ef7-462d58904aa9', '唐', '["欲出未出光辣達（一作「太陽初出光赫赫」），千山萬山如火發，須臾走向天下來（一作「一輪頃刻上天衢」），逐却（一作「退」）殘（一作「羣」）星趕却（一作「與殘」）月。","（見《說郛》卷五陳郁《藏一話腴》，校以陳巖肖《庚溪詩話》卷上。","）。"]', '["欲出未出光辣達（一作「太陽初出光赫赫」），千山万山如火發，須臾走向天下来（一作「一輪頃刻上天衢」），逐却（一作「退」）殘（一作「羣」）星趕却（一作「與殘」）月。","（见《说郛》卷五陳郁《藏一話腴》，校以陳巖肖《庚溪诗話》卷上。","）。"]', '诗', 'shi', '', NULL, '日詩 趙匡胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe288826-38b3-4e3c-b350-e7b87aa610c6', '華陰道中逢月出', '华陰道中逢月出', 'cbe26bad-6b1f-495d-9ef7-462d58904aa9', '唐', '["未離海底（《藏一話腴》作「嶠」）千山黑（《捫蝨新話》作「暗」），纔到天中（《捫蝨新話》作「中天」、《藏一話腴》作「天心」）萬國明。","（見《後山詩話》，校以《說郛》本《藏一話腴》、陳善《捫蝨新話》卷二。","題從《捫蝨新話》。","《藏一話腴》謂此二句係國史據《日詩》）潤色之。","（按：宋人均記載匡胤二詩爲其微時作。","若可信，當作於晉漢之際。","）。"]', '["未離海底（《藏一話腴》作「嶠」）千山黑（《捫蝨新話》作「暗」），纔到天中（《捫蝨新話》作「中天」、《藏一話腴》作「天心」）万国明。","（见《後山诗話》，校以《说郛》本《藏一話腴》、陳善《捫蝨新話》卷二。","題從《捫蝨新話》。","《藏一話腴》謂此二句係国史據《日诗》）潤色之。","（按：宋人均記載匡胤二诗爲其微时作。","若可信，當作於晉漢之際。","）。"]', '诗', 'shi', '', NULL, '華陰道中逢月出 趙匡胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e44eb0-d2b5-4367-a398-7ee2a7833e1d', '和座主王公仁裕見賀入相詩（題擬）', '和座主王公仁裕见賀入相诗（題擬）', '28024555-039f-423d-ae55-581c5e3a9023', '唐', '["揮毫文戰偶搴旗，待詔金華亦偶爲。","白社遽當宗伯選，赤心旋遇聖人知。","九霄得路榮雖極，三接承恩出每遲。","職在台司多少暇，親師不及舞雩時。","（見《廣卓異記》卷六，又見《增修詩話總龜》卷十四引。","）。"]', '["揮毫文戰偶搴旗，待詔金华亦偶爲。","白社遽當宗伯選，赤心旋遇聖人知。","九霄得路榮雖極，三接承恩出每遲。","職在台司多少暇，親師不及舞雩时。","（见《廣卓異記》卷六，又见《增修诗話總龟》卷十四引。","）。"]', '诗', 'shi', '', NULL, '和座主王公仁裕見賀入相詩（題擬） 王溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a68eb22-a928-4310-90d3-96f0393dbbf6', '寄鄧洵美', '寄鄧洵美', '28024555-039f-423d-ae55-581c5e3a9023', '唐', '["衡陽歸鴈別重湖，衘到同人一紙書。","忽見姓名雙淚落，不知消息十年餘。","綵衣我已登黃閤，白社君猶葺舊居。","南望荆門千里外，暮雲重疊滿晴虛。","（見前書同卷引《雅言系述》。","）。"]', '["衡陽归鴈別重湖，衘到同人一紙书。","忽见姓名雙泪落，不知消息十年餘。","綵衣我已登黄閤，白社君猶葺旧居。","南望荆门千里外，暮云重叠满晴虛。","（见前书同卷引《雅言系述》。","）。"]', '诗', 'shi', '', NULL, '寄鄧洵美 王溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c35795-4d2f-4edc-a4e2-66cce92cc39e', '在翰林時作', '在翰林时作', '28024555-039f-423d-ae55-581c5e3a9023', '唐', '["兩制職官三十客，自憐榮耀老萊衣。","（見樂史《廣卓異記》卷五。","）。"]', '["兩制職官三十客，自怜榮耀老萊衣。","（见乐史《廣卓異記》卷五。","）。"]', '诗', 'shi', '', NULL, '在翰林時作 王溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43cc1c64-6a04-477c-8870-70169b64eeb0', '答西蜀歐陽侍郎頌（題擬）', '答西蜀歐陽侍郎頌（題擬）', '96ad77bd-6e1f-4290-9275-70efda953f04', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '答西蜀歐陽侍郎頌（題擬） 延沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b090f8a7-622a-45ae-a8d1-b9010163e0e1', '答西蜀歐陽侍郎頌（題擬） 一', '答西蜀歐陽侍郎頌（題擬） 一', '96ad77bd-6e1f-4290-9275-70efda953f04', '唐', '[]', '[]', '诗', 'shi', '', NULL, '答西蜀歐陽侍郎頌（題擬） 一 延沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4509753e-7731-4f28-bd9e-3767c6862427', '答西蜀歐陽侍郎頌（題擬） 二', '答西蜀歐陽侍郎頌（題擬） 二', '96ad77bd-6e1f-4290-9275-70efda953f04', '唐', '["甘露臺前靡不逢，免將明暗諕盲聾。","當初貶着文殊處，笑殺寒山者老翁。"]', '["甘露台前靡不逢，免將明暗諕盲聾。","當初貶着文殊处，笑殺寒山者老翁。"]', '诗', 'shi', '', NULL, '答西蜀歐陽侍郎頌（題擬） 二 延沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6fbd907-c0cd-41f1-96f0-a3a29e179d4a', '答西蜀歐陽侍郎頌（題擬） 三', '答西蜀歐陽侍郎頌（題擬） 三', '96ad77bd-6e1f-4290-9275-70efda953f04', '唐', '["密密堂堂觸處周，都緣妄識提浮漚。","三千多澤狂華掩，俊矣天然遇石頭。"]', '["密密堂堂觸处周，都緣妄識提浮漚。","三千多澤狂华掩，俊矣天然遇石头。"]', '诗', 'shi', '', NULL, '答西蜀歐陽侍郎頌（題擬） 三 延沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d732852-e1e4-4585-b494-13596a9f6b8e', '因僧問話有頌（二首） 一', '因僧问話有頌（二首） 一', '96ad77bd-6e1f-4290-9275-70efda953f04', '唐', '["萬法虛無實際深，凝然妄肯絕踈親。","斷常妙理修途者，鏡像宜扶覺照頻。"]', '["万法虛無實際深，凝然妄肯絕踈親。","斷常妙理修途者，镜像宜扶覺照頻。"]', '诗', 'shi', '', NULL, '因僧問話有頌（二首） 一 延沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cecf2024-af7a-4134-bcae-aace25f514d4', '因僧問話有頌（二首） 二', '因僧问話有頌（二首） 二', '96ad77bd-6e1f-4290-9275-70efda953f04', '唐', '["萬種方圓在月前，低頭思慮萬重[關]（開）。","吹毛莫比鏌鎁利，一點舒光遍大千。","（以上五首均見《天聖廣燈錄》卷十五）。"]', '["万種方圓在月前，低头思慮万重[关]（开）。","吹毛莫比鏌鎁利，一点舒光遍大千。","（以上五首均见《天聖廣灯錄》卷十五）。"]', '诗', 'shi', '', NULL, '因僧問話有頌（二首） 二 延沼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9d80a7-77ab-46dc-bd12-7620709844fc', '贈鄧洵美', '贈鄧洵美', 'ff01fb75-c92d-4a5e-a9b8-da557c8ca673', '唐', '["憶昔詞場共着鞭，當時鶯谷喜同遷。","關河契闊三千里，音信稀踈二十年。","君遇已知依玉帳，我無才藻步花磚。","時情人事堪惆悵，天外相逢一泫然。","（見《增修詩話總龜》卷十四引《雅言系述》。","）。"]', '["憶昔词場共着鞭，當时鶯谷喜同遷。","关河契闊三千里，音信稀踈二十年。","君遇已知依玉帳，我無才藻步花磚。","时情人事堪惆悵，天外相逢一泫然。","（见《增修诗話總龟》卷十四引《雅言系述》。","）。"]', '诗', 'shi', '', NULL, '贈鄧洵美 李昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfabd999-693c-47a5-8941-f9691b81fc7d', '', '', '8a2679f1-96b9-4280-9aa9-146281861d1d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 駱仲舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3051a42c-b9bd-4ea8-949c-d41281e00dc5', '句', '句', '8a2679f1-96b9-4280-9aa9-146281861d1d', '唐', '["張鴻詩在楞伽峽，韓愈碑留燕喜亭。","（《輿地紀勝》卷九二《連州》。","）。"]', '["張鴻诗在楞伽峽，韓愈碑留燕喜亭。","（《輿地紀勝》卷九二《連州》。","）。"]', '诗', 'shi', '', NULL, '句 駱仲舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae4fd3c8-3eb6-46ec-80d2-68cee5deb8a0', '登昇元閣賦詩 一', '登昇元閣賦诗 一', '12438d9c-f757-4875-ae57-6f71a1c39b15', '唐', '["朝宗海浪拱星辰。","（《宋史》卷二七○《魏丕傳》。","）。"]', '["朝宗海浪拱星辰。","（《宋史》卷二七○《魏丕傳》。","）。"]', '诗', 'shi', '', NULL, '登昇元閣賦詩 一 魏丕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d48c607-d4a0-4592-9e8c-83533cfe6d47', '登昇元閣賦詩 二', '登昇元閣賦诗 二', '12438d9c-f757-4875-ae57-6f71a1c39b15', '唐', '["莫教雷雨損基扃。","（《入蜀記》卷二。","）（按：以上二句爲魏丕奉使南唐時作，故錄出之。","）。"]', '["莫教雷雨損基扃。","（《入蜀記》卷二。","）（按：以上二句爲魏丕奉使南唐时作，故錄出之。","）。"]', '诗', 'shi', '', NULL, '登昇元閣賦詩 二 魏丕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd1ba265-3ab7-4348-b997-fa2ec04243b5', '周世宗時被召作（題擬）', '周世宗时被召作（題擬）', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["草澤吾皇詔，圖南摶姓陳。","三峰十年客。","四海一閑人。","世態從來薄，詩情自得真。","超然居物外，何必使爲臣。","（見陶岳《五代史補》卷五。","）。"]', '["草澤吾皇詔，圖南摶姓陳。","三峰十年客。","四海一闲人。","世態從来薄，诗情自得真。","超然居物外，何必使爲臣。","（见陶岳《五代史補》卷五。","）。"]', '诗', 'shi', '', NULL, '周世宗時被召作（題擬） 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec1331d-18bb-4bdb-8141-9b2a90ef827b', '對御歌', '对御歌', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["臣愛睡，臣愛睡，不臥氈，不蓋被。","片石枕頭，蓑衣鋪地，震雷掣電鬼神驚，臣當其時正酣睡。","閑思張郎，悶想范蠡，說甚孟德，休言劉備，三四君子，只是爭此閑氣。","爭如臣向青山頂頭，白雲堆裏，展開眉頭，解放肚皮，且一覺睡。","管什（一作「甚」）玉兔東生，紅輪西墜。","（見足本《詩話總龜》卷四七、元蔡正孫《詩林廣記後集》卷九引龐元英《談藪》。","）（〖1〗《談藪》云：「陳摶隱武當山，後居華州雲臺觀，多閉戶獨臥，或累月不起。","周世宗召入禁中，扃戶試之，月餘始開，摶熟寐如故。","嘗對御歌此詩云。","」）。"]', '["臣愛睡，臣愛睡，不臥氈，不蓋被。","片石枕头，蓑衣鋪地，震雷掣電鬼神驚，臣當其时正酣睡。","闲思張郎，悶想范蠡，说甚孟德，休言劉備，三四君子，只是爭此闲氣。","爭如臣向青山頂头，白云堆裏，展开眉头，解放肚皮，且一覺睡。","管什（一作「甚」）玉兔东生，紅輪西墜。","（见足本《诗話總龟》卷四七、元蔡正孫《诗林廣記後集》卷九引龐元英《談藪》。","）（〖1〗《談藪》云：「陳摶隐武當山，後居华州云台观，多閉戶独臥，或累月不起。","周世宗召入禁中，扃戶試之，月餘始开，摶熟寐如故。","嘗对御歌此诗云。","」）。"]', '诗', 'shi', '', NULL, '對御歌 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284b98ff-e5e4-4f76-bd54-b2fe621ddba3', '題俞公巖', '題俞公巖', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["萬事若在手，百年聊稱情。","他時南[面]（嶽）去，記得此巖名。","（見《輿地紀勝》卷八五《均州》。","）（〖1〗《邵氏聞見錄》卷七云：「華山隱士陳摶，字圖南，唐長興中進士，遊四方，有大志，隱武當山詩云：『他年南面去，記得此山名。","』本朝張鄧公改『南面』爲『南嶽』，題其後云：『蘚壁題詩志何大，可憐今老華圖南。","』蓋唐末時詩也。","」）。"]', '["万事若在手，百年聊稱情。","他时南[面]（嶽）去，記得此巖名。","（见《輿地紀勝》卷八五《均州》。","）（〖1〗《邵氏闻见錄》卷七云：「华山隐士陳摶，字圖南，唐长兴中進士，游四方，有大志，隐武當山诗云：『他年南面去，記得此山名。","』本朝張鄧公改『南面』爲『南嶽』，題其後云：『蘚壁題诗志何大，可怜今老华圖南。","』蓋唐末时诗也。","」）。"]', '诗', 'shi', '', NULL, '題俞公巖 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b9a238-87a3-4bb9-8e86-aff3241e7a96', '題華山', '題华山', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["半夜天香入巖谷，西風吹落嶺頭蓮。","空愛掌痕侵碧漢，無人曾歎巨靈仙。","（《增修詩話總龜》卷十六、卷四十六引《翰府名談》。","）。"]', '["半夜天香入巖谷，西风吹落嶺头蓮。","空愛掌痕侵碧漢，無人曾歎巨靈仙。","（《增修诗話總龟》卷十六、卷四十六引《翰府名談》。","）。"]', '诗', 'shi', '', NULL, '題華山 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df075835-a1e8-4c11-b83e-c64799d11866', '贈金勵睡詩 一', '贈金勵睡诗 一', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["常人無所重，惟睡乃爲重。","舉世皆爲息，魂離神不動。","覺來無所知，貪求心愈用。","堪笑塵中人（《事文類聚》作「塵世中」），不知夢是夢。","。"]', '["常人無所重，惟睡乃爲重。","舉世皆爲息，魂離神不动。","覺来無所知，貪求心愈用。","堪笑塵中人（《事文類聚》作「塵世中」），不知梦是梦。","。"]', '诗', 'shi', '', NULL, '贈金勵睡詩 一 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c20d9ae-d642-45e3-baf2-5a3662cb722a', '贈金勵睡詩 二', '贈金勵睡诗 二', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["至人本無夢，其夢本游仙。","真人本無睡，睡則浮雲烟。","爐裏近（《事今類聚》作「名」）爲藥，壺中別有天。","欲知睡夢裏，人間第一玄。","（《增修詩話總龜》卷四六引《翰府名談》、《事文類聚後集》卷二一。","）。"]', '["至人本無梦，其梦本游仙。","真人本無睡，睡則浮云烟。","爐裏近（《事今類聚》作「名」）爲藥，壺中別有天。","欲知睡梦裏，人间第一玄。","（《增修诗話總龟》卷四六引《翰府名談》、《事文類聚後集》卷二一。","）。"]', '诗', 'shi', '', NULL, '贈金勵睡詩 二 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd525bdc-7113-4411-93cf-65eb72ce5bff', '冬日晚望', '冬日晚望', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["山鬼暖或呼，溪魚寒不跳。","晚景愈堪觀，危峰露殘照。","（《增修詩話總龜》卷四六引《翰府名談》。","）。"]', '["山鬼暖或呼，溪鱼寒不跳。","晚景愈堪观，危峰露殘照。","（《增修诗話總龟》卷四六引《翰府名談》。","）。"]', '诗', 'shi', '', NULL, '冬日晚望 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54624af6-d304-4172-99f6-3dd0e5bf54c0', '句', '句', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["山色滿庭供畫障，松聲萬壑即琴絃。","（《記纂淵海》卷二十四。","）。"]', '["山色满庭供畫障，松声万壑即琴絃。","（《記纂淵海》卷二十四。","）。"]', '诗', 'shi', '', NULL, '句 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce00b3f8-0f46-4161-aaf6-659232f93ffe', '詩', '诗', '32e894f6-f2a1-4381-bf0f-1a8b07e17e42', '唐', '["我見世人忙，箇箇忙如火。","忙者不爲身，爲身忙却可。","（元王惲《秋澗大全集》卷九六《玉堂嘉話》卷四。","）（按：摶詩今存者尚多，張格《太華希夷志》〖《道藏》本〗存其宋太宗時詩十數首。","今僅錄其作於五代及作年尚難確定者。","）。"]', '["我见世人忙，箇箇忙如火。","忙者不爲身，爲身忙却可。","（元王惲《秋澗大全集》卷九六《玉堂嘉話》卷四。","）（按：摶诗今存者尚多，張格《太华希夷志》〖《道藏》本〗存其宋太宗时诗十數首。","今僅錄其作於五代及作年尚难確定者。","）。"]', '诗', 'shi', '', NULL, '詩 陳摶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27349732-2fd3-4fd5-8414-5792e4824da4', '句', '句', '371ef212-ee41-40c7-b9cf-66b11132a188', '唐', '["虛飣玲瓏石鎮羊。","（見《惜陰軒叢書》本《清異錄》卷上。","）（按：五代封晉王者有數人，士藻所從，未詳爲誰。","）。"]', '["虛飣玲瓏石鎮羊。","（见《惜陰軒叢书》本《清異錄》卷上。","）（按：五代封晉王者有數人，士藻所從，未詳爲誰。","）。"]', '诗', 'shi', '', NULL, '句 游士藻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a437222a-edee-43b4-9ff9-9726bca4e2ee', '臘月雨', '臘月雨', 'a65b4ad9-159b-49af-b263-ea9b83d9d23c', '唐', '["且雨且凍山徑滑，是誰作此琉璃變？","（同前。","）。"]', '["且雨且凍山徑滑，是誰作此琉璃变？","（同前。","）。"]', '诗', 'shi', '', NULL, '臘月雨 劉東叔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e4e43d-8316-47ab-8fa8-03ed061d9b7c', '頌', '頌', 'efab334b-b3d7-44cb-b54f-fab3a0eb1122', '唐', '["撞來好箇寄生囊。","（同前。","）。"]', '["撞来好箇寄生囊。","（同前。","）。"]', '诗', 'shi', '', NULL, '頌 梓潼雙燈寺僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79fef416-5d32-403f-8b0c-7267a6d09047', '芭蕉歌', '芭蕉歌', '036ac750-1153-485f-b957-668e941adee0', '唐', '["草中一種無倫比，瑣屑蒿萊望帝尊。","（同前。","）。"]', '["草中一種無倫比，瑣屑蒿萊望帝尊。","（同前。","）。"]', '诗', 'shi', '', NULL, '芭蕉歌 謝調 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebf261b1-6523-4bd7-a85c-5a61c84316dd', '賞酴醿', '賞酴醿', '02b2a3d7-a75a-43c5-b483-a95970ac1cba', '唐', '["香瓊綬帶雪纓絡。","（同前。","）。"]', '["香瓊綬带雪纓絡。","（同前。","）。"]', '诗', 'shi', '', NULL, '賞酴醿 薛熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c761a18-876e-4552-9e8e-5e8bbd021b6f', '謝陶穀餉鴨卵及蓮枝一捻紅（題擬）', '謝陶穀餉鴨卵及蓮枝一捻紅（題擬）', '72181518-c771-4913-9493-4125e0beb58b', '唐', '["聖朝初出赤誌翁，醜杖旁扶赤誌翁。","（同前。","）。"]', '["聖朝初出赤誌翁，醜杖旁扶赤誌翁。","（同前。","）。"]', '诗', 'shi', '', NULL, '謝陶穀餉鴨卵及蓮枝一捻紅（題擬） 符昭遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96df7153-0acf-4043-8b28-4524234c2eb3', '貧家壁', '貧家壁', 'b85749d6-1dcc-4956-97cd-1a542f06c6bb', '唐', '["椒氣從何得？燈光鑿處分。","拖筵來藻飾，惟有篆愁君。","（同前。","）。"]', '["椒氣從何得？灯光鑿处分。","拖筵来藻飾，惟有篆愁君。","（同前。","）。"]', '诗', 'shi', '', NULL, '貧家壁 李善寧之子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da63fe74-ed34-4012-ba4b-09c27fb3abaf', '獻硯詩', '獻硯诗', 'e553916f-a430-4490-8606-4bee9d30727a', '唐', '["金稜玉海比連城，假借文章取盛名。","（同前卷下。","）。"]', '["金稜玉海比連城，假借文章取盛名。","（同前卷下。","）。"]', '诗', 'shi', '', NULL, '獻硯詩 方爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c88130d1-e8e2-4612-8df1-08bc01d03dea', '效胡嶠飲茶詩', '效胡嶠饮茶诗', 'db994f34-9f66-487c-9b25-bf7d5fda74ae', '唐', '["生涼好喚雞蘇佛，回味宜稱橄欖仙。","（同前。","）（按：《清異錄》一書，題陶穀撰，今人指出書中部分內容爲陶穀身後事，因疑非其所撰。","今檢全書，可斷定出自宋初人之手，頗疑陶穀本有此稿，後人整理時又夾雜入其他內容。","自游士藻以下九人事迹無考，其生活時代，大致可確定在五代至宋初之十數年間，故統附於此。","）。"]', '["生涼好喚雞蘇佛，回味宜稱橄欖仙。","（同前。","）（按：《清異錄》一书，題陶穀撰，今人指出书中部分內容爲陶穀身後事，因疑非其所撰。","今檢全书，可斷定出自宋初人之手，頗疑陶穀本有此稿，後人整理时又夾杂入其他內容。","自游士藻以下九人事迹無考，其生活时代，大致可確定在五代至宋初之十數年间，故統附於此。","）。"]', '诗', 'shi', '', NULL, '效胡嶠飲茶詩 陶彝之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d9361a-5d88-4040-9660-e0b79d3ac5a1', '', '', '03a79ac0-0a72-4c1d-81bc-7af21e8d445d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 歸曉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0af18fd-0e31-4f68-b7de-7fc83625a207', '至安陸竺乾盛會', '至安陸竺乾盛會', '03a79ac0-0a72-4c1d-81bc-7af21e8d445d', '唐', '["有時途路上，見□□□□。","野□有霜宿，孤峰無水齋。","白雲隨步步，黃葉落挨挨。","若遇杉松裏，風寒□碧崖。","（《八瓊室金石補正》卷八六收潘平撰《大宋襄州鳳山延慶禪院傳法惠廣大師壽塔碑銘》引。","）（按：此詩爲其入宋前作。","）。"]', '["有时途路上，见□□□□。","野□有霜宿，孤峰無水斋。","白云隨步步，黄葉落挨挨。","若遇杉松裏，风寒□碧崖。","（《八瓊室金石補正》卷八六收潘平撰《大宋襄州鳳山延慶禪院傳法惠廣大師壽塔碑銘》引。","）（按：此诗爲其入宋前作。","）。"]', '诗', 'shi', '', NULL, '至安陸竺乾盛會 歸曉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fddac6ec-6273-4e8e-b748-a4bf73245067', '書翠崖（一作「巖」）寺壁', '书翠崖（一作「巖」）寺壁', '73abfe32-66b5-4e36-a7b4-1043c6cc6e8c', '唐', '["迎笑堂前九節筇，閑來無事得從容，時聞雷護千年橘，夜聽風傳萬壑松。","茅屋人家芳草合（一作「外」），竹房僧住翠微濃（一作「中」）。","一蓑煙雨歸來晚，遙聽雲間起暮鐘。","（見《江西詩微》卷三。","）（按：今人編選之《滕王閣詩選》，自道光三十年刊涂闌玉輯《西山志》中錄該詩，略有異文，注一作者即據該書。","《西山志》未見。","）。"]', '["迎笑堂前九節筇，闲来無事得從容，时闻雷護千年橘，夜听风傳万壑松。","茅屋人家芳草合（一作「外」），竹房僧住翠微濃（一作「中」）。","一蓑煙雨归来晚，遙听云间起暮鐘。","（见《江西诗微》卷三。","）（按：今人編選之《滕王閣诗選》，自道光三十年刊涂闌玉輯《西山志》中錄該诗，略有異文，注一作者即據該书。","《西山志》未见。","）。"]', '诗', 'shi', '', NULL, '書翠崖（一作「巖」）寺壁 歐陽持 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3bb30e-90ac-4d24-b570-7e591abc391f', '送池陽徐守', '送池陽徐守', 'e83b2174-c129-457e-9196-e9c0de3ce816', '唐', '["四時風雨隨旌旗，八面溪山捧郡樓。","（見《輿地紀勝》卷二十二《池州》。","）。"]', '["四时风雨隨旌旗，八面溪山捧郡楼。","（见《輿地紀勝》卷二十二《池州》。","）。"]', '诗', 'shi', '', NULL, '送池陽徐守 殷文圭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('372971b5-ce11-4721-96e6-be94fdce7db8', '落星寺詩', '落星寺诗', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["是嶽皆遊遍，南來吳楚間。","偶登湖裏寺，疑到（《大典》作「是」）海中山。","獨樹蒨蘿（《廬山記》作「倩羅」，今從《大典》。","）濕，遙汀白鳥閑。","終須謝浮世，高臥聽潺潺。","（見《吉石盦叢書》影宋抄《廬山記》卷四，僅署名「同前」，其前缺一頁，但存修睦《簡寂觀》詩之後半。","《永樂大典》卷八七八二引《九江府志》正作修睦詩。","）。"]', '["是嶽皆游遍，南来吳楚间。","偶登湖裏寺，疑到（《大典》作「是」）海中山。","独樹蒨蘿（《廬山記》作「倩羅」，今從《大典》。","）濕，遙汀白鸟闲。","終須謝浮世，高臥听潺潺。","（见《吉石盦叢书》影宋抄《廬山記》卷四，僅署名「同前」，其前缺一頁，但存修睦《簡寂观》诗之後半。","《永乐大典》卷八七八二引《九江府志》正作修睦诗。","）。"]', '诗', 'shi', '', NULL, '落星寺詩 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f01a5a59-9427-43e2-a41c-83b6dbbbacdf', '山北東林詩', '山北东林诗', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["二林乘興往，幾日見歸程。","有翼便歸程。","有翼便飛去，何勞更此生。","川長雲迤邐，溪靜月分明。","果熟僧相待，庭閑鶴自行。","搘頤檉櫛穩，遠夢石牀平。","是院水皆到，無窗書不盈。","登樓雙眼飽，倚檜片心清。","夜永蓮花漏，殿高神運名。","參空寒嶠色，壓雨古松聲。","早晚攜瓶入，孤吟猨鳥情。","（見《永樂大典》卷八七八二引《九江府志》。","二詩皆據《古籍整理出版情況簡報》一五六期張忱石先生《〈永樂大典〉續印本印象記》轉錄。","）。"]', '["二林乘兴往，幾日见归程。","有翼便归程。","有翼便飞去，何勞更此生。","川长云迤邐，溪静月分明。","果熟僧相待，庭闲鹤自行。","搘頤檉櫛穩，远梦石牀平。","是院水皆到，無窗书不盈。","登楼雙眼飽，倚檜片心清。","夜永蓮花漏，殿高神運名。","參空寒嶠色，壓雨古松声。","早晚携瓶入，孤吟猨鸟情。","（见《永乐大典》卷八七八二引《九江府志》。","二诗皆據《古籍整理出版情況簡報》一五六期張忱石先生《〈永乐大典〉續印本印象記》轉錄。","）。"]', '诗', 'shi', '', NULL, '山北東林詩 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('278e2299-0553-4145-be5e-c791c82c11f7', '廬山（題擬）', '廬山（題擬）', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["底事[匡]（康）廬住忘回，其如幽致勝天台。","僧閑吟倚六朝樹，客思晚行三徑苔。","（見《輿地紀勝》卷三十《江州》。","）。"]', '["底事[匡]（康）廬住忘回，其如幽致勝天台。","僧闲吟倚六朝樹，客思晚行三徑苔。","（见《輿地紀勝》卷三十《江州》。","）。"]', '诗', 'shi', '', NULL, '廬山（題擬） 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b117e3-2c41-4566-9c29-102b42b1dafd', '', '', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c463b1f-41b4-48c3-a94f-7145f702ff7e', '冰賦附詩', '冰賦附诗', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["深山窮谷[凌]（陵）人鑿，頒賜從來天下聞。","別有川池捐棄者，統思采斵獻明君。","（《文苑英華》卷三八。","）。"]', '["深山窮谷[凌]（陵）人鑿，頒賜從来天下闻。","別有川池捐棄者，統思采斵獻明君。","（《文苑英华》卷三八。","）。"]', '诗', 'shi', '', NULL, '冰賦附詩 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('554fbeb3-2110-4ede-9da2-7ed4890ed41d', '題東林二首 一', '題东林二首 一', 'ebb7b34e-4e5f-40c6-914a-bae03f6556ad', '唐', '["東林佳景一何長，蘭蕙生多地亦香，堪歎世人來不得，便隨雲樹老何妨。","倚天蒼翠晴當戶，落[石]潺湲夜遶廊。","到此秪除重結社，自餘閑事莫思量。"]', '["东林佳景一何长，蘭蕙生多地亦香，堪歎世人来不得，便隨云樹老何妨。","倚天蒼翠晴當戶，落[石]潺湲夜遶廊。","到此秪除重結社，自餘闲事莫思量。"]', '诗', 'shi', '', NULL, '題東林二首 一 匡白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de94a54-0931-4046-89b7-b83305600f0f', '題東林二首 二', '題东林二首 二', 'ebb7b34e-4e5f-40c6-914a-bae03f6556ad', '唐', '["東林繼四絕，物象更清幽。","社客去不返，鐘峰雲也（《永樂大典》作「色」）秋。","松枯羣狖散，溪大蠹槎流。","待卜歸休計，重來臥石樓。","（見《吉石庵叢書》本《廬山記》卷四，以《永樂大典》卷八七八二引《九江府志》參校。","）（按：《殷禮在斯堂叢書》校排本《廬山記》二詩題作《天祚二年三月十六日偶與幕客門館僧道，閑遊題東林二首》，係將徐知證等聯句詩末題記誤植於匡白詩題，另詳後徐知證條。","）。"]', '["东林繼四絕，物象更清幽。","社客去不返，鐘峰云也（《永乐大典》作「色」）秋。","松枯羣狖散，溪大蠹槎流。","待卜归休計，重来臥石楼。","（见《吉石庵叢书》本《廬山記》卷四，以《永乐大典》卷八七八二引《九江府志》參校。","）（按：《殷禮在斯堂叢书》校排本《廬山記》二诗題作《天祚二年三月十六日偶與幕客门館僧道，闲游題东林二首》，係將徐知證等聯句诗末題記誤植於匡白诗題，另詳後徐知證條。","）。"]', '诗', 'shi', '', NULL, '題東林二首 二 匡白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d96cf607-91d3-4702-b943-f1adc4cb7caa', '', '', '0d796de5-0677-4c17-ad48-9e956de30bb0', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 謝建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a284ab45-9669-465d-a553-cbbb403dd4ff', '題牆上畫相撲者', '題牆上畫相撲者', '0d796de5-0677-4c17-ad48-9e956de30bb0', '唐', '["愚漢勾卻白漢項，白人捉卻愚人骰。","如人莫辨輪贏者，直待墻隤始一交。","（宋調露子《角力記》。","）。"]', '["愚漢勾卻白漢項，白人捉卻愚人骰。","如人莫辨輪贏者，直待墻隤始一交。","（宋調露子《角力記》。","）。"]', '诗', 'shi', '', NULL, '題牆上畫相撲者 謝建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8833e2a-30cd-41c2-856c-e63079f1cb4a', '句 一', '句 一', '3904289e-b309-4a15-83ab-f4168c4983c8', '唐', '["蛟髩鳳釵慵不整。","（胡偉《宮詞》）。"]', '["蛟髩鳳釵慵不整。","（胡偉《宮词》）。"]', '诗', 'shi', '', NULL, '句 一 李昪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0165065e-7689-4c78-b797-82a1d49a1eaa', '句 二', '句 二', '3904289e-b309-4a15-83ab-f4168c4983c8', '唐', '["朱扉盡日鎮長扃。","（同前。","）。"]', '["朱扉尽日鎮长扃。","（同前。","）。"]', '诗', 'shi', '', NULL, '句 二 李昪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f451479b-2d0d-458e-9b32-65067ff26b41', '答謝建偈（題擬）', '答謝建偈（題擬）', 'ae6292cd-5ab3-4bff-91ca-13f3818f7aa0', '唐', '["將知善事多磨，今日礙緣特八。","煩我火頭金剛，別告大權菩薩。","（宋調露子《角力記》。","）。"]', '["將知善事多磨，今日礙緣特八。","煩我火头金剛，別告大權菩薩。","（宋調露子《角力記》。","）。"]', '诗', 'shi', '', NULL, '答謝建偈（題擬） 彥光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc93ec7d-4d15-4f5c-84d0-d194eeed5b60', '', '', 'd9e93f9f-5a5b-4f55-826a-daccfa01fa2f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 徐知證 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b53bfa78-87bc-4854-a630-f318a9a3fc49', '題東林寺聯句', '題东林寺聯句', 'd9e93f9f-5a5b-4f55-826a-daccfa01fa2f', '唐', '["（徐知證虔修李玄李□王三□孟拱辰〖《崇文總目》卷五有《孟拱辰文集》三卷。","《宋史·藝文志》作《鳳苑集》〗鍾敬倫〖《全唐詩》無虔修等六人詩〗）古殿巍峨鎮碧峰，晉朝靈應顯神蹤。","林間野鳥驚寅（《大典》作「朝」）梵，嶺上孤猿聽晚（《大典》作「曉」）鐘。","（節度使[特]〖時〗進檢校太尉平章事徐知證。","）鴈[□]冷雲生曉檻，虎溪秋月照寒松。","（賜紫僧虔修。","）香飛寶殿籠金像，檜倚松窗覆玉容。","（道士李玄。","）蝶戀半巖花灼灼，鹿眠深谷草茸茸。","（觀察推官賜紫金魚袋李□。","）遊僧駐錫心皆佛，老樹擎煙勢似龍。","（觀察推官賜緋魚袋王三□。","）竹蔭禪扉（《大典》作「扃」）青靄合，嵐（《大典》作「風」）蒸幽（李壁引作「山」）逕綠苔封。","（司理參軍掌表奏孟拱辰。","）流泉遶砌清聲遠，列巘趍門更憧憧。","高吟況愛無塵境（《大典》作「老來欲脫塵寰境」），吟（《大典》作「閑」）訪空關不厭重。","（管[勾]〖旬〗官賜紫金魚袋鍾敬倫（鍾）。","見《吉石盦叢書》本影印日本高山寺藏宋鈔陳舜俞《廬山記》卷四。","）（按：詩末原題一行云：「天祚二年三月十六日偶與幕客門館僧閑遊聯題。","」《全唐詩續補遺》卷十五據《永樂大典》卷六六九七引《九江府志》、卷六六九九引《江州志》收本詩，題作《東林寺天祚二年聯句》，缺第三、第四、第八聯，又聯句者姓名均不著明，統歸知證名下，實誤。","異文頗多，已出校。","李壁《王荆文公詩箋注》卷二八《和蔡樞密種山藥》注引徐知證《棗林聯句》「嵐蒸山徑綠苔封」一句。","「棗林」爲「東林」之誤。","其餘校改，所據爲羅振玉《殷禮在斯堂叢書》校排本《廬山記》、同人《貞松老人遺稿·〈廬山記〉校勘記》，羅氏曾參據日本元祿本《廬山記》。","惟《殷禮在斯堂叢書》本將詩末原題一行誤植於匡白詩題之上，當改正。","）。"]', '["（徐知證虔修李玄李□王三□孟拱辰〖《崇文總目》卷五有《孟拱辰文集》三卷。","《宋史·藝文志》作《鳳苑集》〗鍾敬倫〖《全唐诗》無虔修等六人诗〗）古殿巍峨鎮碧峰，晉朝靈應显神蹤。","林间野鸟驚寅（《大典》作「朝」）梵，嶺上孤猿听晚（《大典》作「晓」）鐘。","（節度使[特]〖时〗進檢校太尉平章事徐知證。","）鴈[□]冷云生晓檻，虎溪秋月照寒松。","（賜紫僧虔修。","）香飞寶殿籠金像，檜倚松窗覆玉容。","（道士李玄。","）蝶戀半巖花灼灼，鹿眠深谷草茸茸。","（观察推官賜紫金鱼袋李□。","）游僧駐錫心皆佛，老樹擎煙勢似龙。","（观察推官賜緋鱼袋王三□。","）竹蔭禪扉（《大典》作「扃」）青靄合，嵐（《大典》作「风」）蒸幽（李壁引作「山」）逕綠苔封。","（司理參軍掌表奏孟拱辰。","）流泉遶砌清声远，列巘趍门更憧憧。","高吟況愛無塵境（《大典》作「老来欲脫塵寰境」），吟（《大典》作「闲」）訪空关不厭重。","（管[勾]〖旬〗官賜紫金鱼袋鍾敬倫（鍾）。","见《吉石盦叢书》本影印日本高山寺藏宋鈔陳舜俞《廬山記》卷四。","）（按：诗末原題一行云：「天祚二年三月十六日偶與幕客门館僧闲游聯題。","」《全唐诗續補遺》卷十五據《永乐大典》卷六六九七引《九江府志》、卷六六九九引《江州志》收本诗，題作《东林寺天祚二年聯句》，缺第三、第四、第八聯，又聯句者姓名均不著明，統归知證名下，實誤。","異文頗多，已出校。","李壁《王荆文公诗箋注》卷二八《和蔡樞密種山藥》注引徐知證《棗林聯句》「嵐蒸山徑綠苔封」一句。","「棗林」爲「东林」之誤。","其餘校改，所據爲羅振玉《殷禮在斯堂叢书》校排本《廬山記》、同人《貞松老人遺稿·〈廬山記〉校勘記》，羅氏曾參據日本元祿本《廬山記》。","惟《殷禮在斯堂叢书》本將诗末原題一行誤植於匡白诗題之上，當改正。","）。"]', '诗', 'shi', '', NULL, '題東林寺聯句 徐知證 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad9da7f-53db-4866-8ff0-38fa42f6255c', '題鍾隱畫鶡子鳥', '題鍾隐畫鶡子鸟', 'a6c08b51-ea00-4a0b-8846-73d2e426fe4e', '唐', '["多厭翻翔下葦叢，戢翰側腦思何窮？","侍童莫便褰簾過，只恐驚飛入碧空。","（見宋劉道醇《五代名畫補遺》。","）。"]', '["多厭翻翔下葦叢，戢翰側腦思何窮？","侍童莫便褰簾過，只恐驚飞入碧空。","（见宋劉道醇《五代名畫補遺》。","）。"]', '诗', 'shi', '', NULL, '題鍾隱畫鶡子鳥 金昌宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e3d787-c4a8-4c2f-a82c-51ba35cc11dd', '簡寂觀', '簡寂观', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["[廊]（郎）殿與雲連，紫霄蒼翠邊。","自然應有藥，誰敢道無仙？","蘚色吞崖徑，松聲讓瀑泉。","未能長息去，豈便是前緣！（見《吉石盦叢書》本《廬山記》卷四。","「廊」字從《殷禮在斯堂叢書》本改。","）。"]', '["[廊]（郎）殿與云連，紫霄蒼翠邊。","自然應有藥，誰敢道無仙？","蘚色吞崖徑，松声讓瀑泉。","未能长息去，豈便是前緣！（见《吉石盦叢书》本《廬山記》卷四。","「廊」字從《殷禮在斯堂叢书》本改。","）。"]', '诗', 'shi', '', NULL, '簡寂觀 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e3ce53-d9bb-451c-a95a-cf1b3a8383d1', '重開衡陽寺古迹詩刻', '重开衡陽寺古迹诗刻', 'bd14d3c9-435a-4bbd-a9f0-6933e2c25b46', '唐', '["古迹重聞一朗興，斸煙尋得寶階層。","只應雲鶴知前事，爲問齊梁舊住僧。","廢井荒池猶浸月，短松低栢欲遮燈。","淳于道士真高達，拋卻林泉便上昇。","（見《至元金陵新志》卷十一「衡陽寺」條引《慶元志》。","）（按：《慶元志》云：「寺舊有齊己、牟儒二上人《重開衡陽寺古迹詩刻》云〖詩略〗。","保大七年題。","」唐詩僧齊己卒於天福初，未活至保大年，今亦無證可定爲一人，姑分列。","《全唐詩》無牟儒詩。","）。"]', '["古迹重闻一朗兴，斸煙尋得寶階層。","只應云鹤知前事，爲问齊梁旧住僧。","廢井荒池猶浸月，短松低栢欲遮灯。","淳于道士真高達，拋卻林泉便上昇。","（见《至元金陵新志》卷十一「衡陽寺」條引《慶元志》。","）（按：《慶元志》云：「寺旧有齊己、牟儒二上人《重开衡陽寺古迹诗刻》云〖诗略〗。","保大七年題。","」唐诗僧齊己卒於天福初，未活至保大年，今亦無證可定爲一人，姑分列。","《全唐诗》無牟儒诗。","）。"]', '诗', 'shi', '', NULL, '重開衡陽寺古迹詩刻 齊己　牟儒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60069783-4d42-4779-9253-9a634848d343', '示徒頌', '示徒頌', '7d46ad0e-6c84-4dc5-adb8-1f179569b2b8', '唐', '["匡山路，匡山路，巖崖嶮峻人難措。","遊人擬議隔千山，一句分明超佛祖。"]', '["匡山路，匡山路，巖崖嶮峻人难措。","游人擬議隔千山，一句分明超佛祖。"]', '诗', 'shi', '', NULL, '示徒頌 匡山和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e91ca2d-2f45-4be3-bf13-71ee7def0da2', '白牛頌', '白牛頌', '7d46ad0e-6c84-4dc5-adb8-1f179569b2b8', '唐', '["我有古壇真白牛，父子藏來經幾秋。","出門直透孤峰頂，迴來暫跨虎谿頭。","（均見《景德傳燈錄》卷二十三、《五燈會元》卷八。","）（按：貫休有《寄匡山大願和尚詩》，未知與匡山和尚是一人否。","）。"]', '["我有古壇真白牛，父子藏来經幾秋。","出门直透孤峰頂，迴来暫跨虎谿头。","（均见《景德傳灯錄》卷二十三、《五灯會元》卷八。","）（按：貫休有《寄匡山大願和尚诗》，未知與匡山和尚是一人否。","）。"]', '诗', 'shi', '', NULL, '白牛頌 匡山和尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac87b84-4618-4b9f-b121-14c39dfe2163', '', '', 'a51fdab5-3e4a-421c-9961-1a2dd4b53de5', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 江文蔚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c2d5ff5-5599-4d21-a653-2638adefecf6', '句', '句', 'a51fdab5-3e4a-421c-9961-1a2dd4b53de5', '唐', '["屈平（《輿》作「原」）若遇高堂在，應不懷沙獨葬魚（《輿》作「終不懷沙吊汨羅」。","見徐鉉《徐公文集》卷十五《唐故左諫議大夫翰林學士江君墓誌銘》，以《輿地紀勝》卷一二九《福寧府》所引對校。","）。"]', '["屈平（《輿》作「原」）若遇高堂在，應不懷沙独葬鱼（《輿》作「終不懷沙吊汨羅」。","见徐鉉《徐公文集》卷十五《唐故左諫議大夫翰林学士江君墓誌銘》，以《輿地紀勝》卷一二九《福寧府》所引对校。","）。"]', '诗', 'shi', '', NULL, '句 江文蔚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07298ab8-838f-4494-b77a-5d448bf01804', '瀑布', '瀑布', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["廬山正南面，瀑布古來聞。","萬里朝滄海，千尋出白雲。","寒聲終自遠，靈派孰爲分。","除却天台後，平流莫可羣。","（錄自《吉石盦叢書》本宋陳舜俞《廬山記》卷四。","）。"]', '["廬山正南面，瀑布古来闻。","万里朝滄海，千尋出白云。","寒声終自远，靈派孰爲分。","除却天台後，平流莫可羣。","（錄自《吉石盦叢书》本宋陳舜俞《廬山記》卷四。","）。"]', '诗', 'shi', '', NULL, '瀑布 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d665196-78ec-4e33-a05b-5447d5c5ea66', '簡寂觀', '簡寂观', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["纔入玄都解鬱陶，羽人相伴遍遊遨。","溪橫洞口紅塵斷，嶽聳天心紫氣高。","金井泉秋光瀲灧，石壇松古韻蕭騷。","吟餘却歎浮生事，盡[□□□□□□]。","（同前書卷四。","影抄本僅抄至「盡」字，空框從羅振玉《殷禮在斯堂叢書》校排本《廬山記》補。","）。"]', '["纔入玄都解鬱陶，羽人相伴遍游遨。","溪橫洞口紅塵斷，嶽聳天心紫氣高。","金井泉秋光瀲灧，石壇松古韻蕭騷。","吟餘却歎浮生事，尽[□□□□□□]。","（同前书卷四。","影抄本僅抄至「尽」字，空框從羅振玉《殷禮在斯堂叢书》校排本《廬山記》補。","）。"]', '诗', 'shi', '', NULL, '簡寂觀 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee065db-eeab-49fe-825c-50defa761a7e', '簡寂觀', '簡寂观', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["錢燼滿庭人醮罷，西峰凉影月沉沉。","到來往事碑中說，壇畔徘徊秋正深。","（同前書卷四。","）。"]', '["錢燼满庭人醮罷，西峰凉影月沉沉。","到来往事碑中说，壇畔徘徊秋正深。","（同前书卷四。","）。"]', '诗', 'shi', '', NULL, '簡寂觀 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7d9c93-a855-4b05-9ac5-4d35647c1cc8', '贈天台僧', '贈天台僧', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["白髮經年復白眉，齋身多病已無機。","曾來越客留詩板，舊識蕃人送衲衣。","巖竇夜禪雲樹濕，石橋秋望海山微。","結庵更擬尋華頂，晚歲應容叩竹扉。","（見《四庫珍本初集》本宋林師蒧《天台續集》卷下。","）（按：《天台續集》二卷，爲林師蒧據宋李庚原本編成，所收「皆宋初迄宣、政間人之詩」〖《四庫全書總目》卷一八七〗，清陸心源《宋詩紀事補遺》卷四因據以錄入。","其實，江爲幷未入宋。","陶岳《五代史補》卷五、龍袞《江南野錄》卷八、馬令《南唐書》卷十四、陸游《南唐書》卷十二、吳任臣《十國春秋》卷九七所載爲傳，均云爲於南唐元宗時因事被誅。","其時宋尚未立國，作宋詩未當。","）。"]', '["白髮經年复白眉，斋身多病已無機。","曾来越客留诗板，旧識蕃人送衲衣。","巖竇夜禪云樹濕，石橋秋望海山微。","結庵更擬尋华頂，晚歲應容叩竹扉。","（见《四庫珍本初集》本宋林師蒧《天台續集》卷下。","）（按：《天台續集》二卷，爲林師蒧據宋李庚原本編成，所收「皆宋初迄宣、政间人之诗」〖《四庫全书總目》卷一八七〗，清陸心源《宋诗紀事補遺》卷四因據以錄入。","其實，江爲幷未入宋。","陶岳《五代史補》卷五、龙袞《江南野錄》卷八、马令《南唐书》卷十四、陸游《南唐书》卷十二、吳任臣《十国春秋》卷九七所載爲傳，均云爲於南唐元宗时因事被誅。","其时宋尚未立国，作宋诗未當。","）。"]', '诗', 'shi', '', NULL, '贈天台僧 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2772b4d3-f708-4cdf-9f02-6d7da9aad47f', '句 一', '句 一', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["亦同元亮舊生涯。","（史鑄《百菊集譜》卷六集句引。","）。"]', '["亦同元亮旧生涯。","（史鑄《百菊集譜》卷六集句引。","）。"]', '诗', 'shi', '', NULL, '句 一 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53d7e4f-3e10-4014-bb81-301b9260e338', '句 二', '句 二', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["城頭初角送殘暉。","（《江湖小集》卷六紹嵩《江浙紀行集句詩》引）。"]', '["城头初角送殘暉。","（《江湖小集》卷六紹嵩《江浙紀行集句诗》引）。"]', '诗', 'shi', '', NULL, '句 二 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d06b9b-333b-4b2b-9020-0df3648926c5', '鷺鷥詩', '鷺鷥诗', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["青山藏不得，明月合相容。","（見《吟窗雜錄》卷十四正字王玄《詩中旨格》。","）。"]', '["青山藏不得，明月合相容。","（见《吟窗杂錄》卷十四正字王玄《诗中旨格》。","）。"]', '诗', 'shi', '', NULL, '鷺鷥詩 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a159d8-975a-4a1d-8a70-980ef067849d', '羅剎石（題擬）', '羅剎石（題擬）', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["何年遺禹鑿，半里大江中。","（見《盛淳臨安志》卷二十三、明田汝成《西湖遊覽志》卷二十四《浙江勝蹟》。","）。"]', '["何年遺禹鑿，半里大江中。","（见《盛淳臨安志》卷二十三、明田汝成《西湖游覽志》卷二十四《浙江勝蹟》。","）。"]', '诗', 'shi', '', NULL, '羅剎石（題擬） 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('183906e8-e6ae-4fe0-953d-70187b75d500', '登落星灣水心寺題水軒（題擬）', '登落星灣水心寺題水軒（題擬）', '9359d36a-4f10-4822-95c5-2a2d67196079', '唐', '["分飛南渡春風晚，却返家林事業空。","無限離情似楊柳，萬條垂向水當中。","（見《增修詩話總龜》卷三。","）。"]', '["分飞南渡春风晚，却返家林事業空。","無限離情似楊柳，万條垂向水當中。","（见《增修诗話總龟》卷三。","）。"]', '诗', 'shi', '', NULL, '登落星灣水心寺題水軒（題擬） 臨川小吏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b24e1e2-9f7e-4321-acde-138b824d8038', '華嚴六相義頌', '华嚴六相義頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["華嚴六相義，同中還有異。","異若異於同，全非諸佛意。","諸佛意總別，何曾有同異。","男子身中入定時，女子身中不留意。","不留意，絕名字，萬象明明無理事。"]', '["华嚴六相義，同中還有異。","異若異於同，全非諸佛意。","諸佛意總別，何曾有同異。","男子身中入定时，女子身中不留意。","不留意，絕名字，万象明明無理事。"]', '诗', 'shi', '', NULL, '華嚴六相義頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26ef7424-58d6-48ce-8765-43e482e261fd', '瞻須菩提頌', '瞻須菩提頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["須菩提，貌古奇，說空法，法不離。","信不及，又懷疑。","信得及，復何之。","倚笻杖，視東西。"]', '["須菩提，貌古奇，说空法，法不離。","信不及，又懷疑。","信得及，复何之。","倚笻杖，視东西。"]', '诗', 'shi', '', NULL, '瞻須菩提頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c335ed-ddd5-43dc-b784-46a996d382f2', '街鼓鳴頌', '街鼓鳴頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["鼓鼕鼕，運大功。","滿朝人，道路通。","道路通，何所至？","達者莫言登寶地。"]', '["鼓鼕鼕，運大功。","满朝人，道路通。","道路通，何所至？","達者莫言登寶地。"]', '诗', 'shi', '', NULL, '街鼓鳴頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78cd084e-3cf6-4ebd-b6e3-f0731199c046', '示捨棄慕道頌', '示捨棄慕道頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["東堂不折桂，南華不學僊，却來乾竺寺，披衣效坐禪。","禪若效坐得，非想亦何偏。","（經刼守閑，不出生死。","）爲報參禪者，須悟道中玄。","如何道中玄，真規自宛然。","。"]', '["东堂不折桂，南华不学僊，却来乾竺寺，披衣效坐禪。","禪若效坐得，非想亦何偏。","（經刼守闲，不出生死。","）爲報參禪者，須悟道中玄。","如何道中玄，真規自宛然。","。"]', '诗', 'shi', '', NULL, '示捨棄慕道頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36fcf890-93d4-463b-9d5f-6bc83433bcd0', '僧問隨色摩尼珠頌', '僧问隨色摩尼珠頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["摩尼不隨色，色裏勿摩尼。","摩尼與衆色，不合不分離。"]', '["摩尼不隨色，色裏勿摩尼。","摩尼與衆色，不合不分離。"]', '诗', 'shi', '', NULL, '僧問隨色摩尼珠頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3635183-630c-4fb3-a340-ba5fd4660965', '牛頭庵頌', '牛头庵頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["國城南，祖師庵。","庵舊址，依雲嵐。","獸馴淑，人相參。","忽有心，終不堪。"]', '["国城南，祖師庵。","庵旧址，依云嵐。","獸馴淑，人相參。","忽有心，終不堪。"]', '诗', 'shi', '', NULL, '牛頭庵頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd212ac-d2c4-40bd-ab7b-225c7634f220', '因僧看經頌', '因僧看經頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["今人看古教，不免心中鬧。","欲免心中鬧，但知看古教。"]', '["今人看古教，不免心中鬧。","欲免心中鬧，但知看古教。"]', '诗', 'shi', '', NULL, '因僧看經頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45d82f49-aaa4-4677-a8ae-320ea40727c0', '庭栢盆蓮頌', '庭栢盆蓮頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["一朶菡萏蓮，兩株青瘦栢。","長向僧家庭，何勞問高格。"]', '["一朶菡萏蓮，兩株青瘦栢。","长向僧家庭，何勞问高格。"]', '诗', 'shi', '', NULL, '庭栢盆蓮頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588a71e3-173a-4f5a-96d2-a5240cd23fc0', '正月偶示頌', '正月偶示頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["正月春，順時節。","情有無，皆含悅。","君要知，得誰力。","更問誰，教誰決。"]', '["正月春，順时節。","情有無，皆含悅。","君要知，得誰力。","更问誰，教誰決。"]', '诗', 'shi', '', NULL, '正月偶示頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1006582f-7a4f-4b28-8c25-30dd4e124981', '寄鍾陵光僧正頌', '寄鍾陵光僧正頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["西山巍巍兮聳碧，漳水澄澄兮練色，對現分明有何極。","（以上十首均見《景德傳燈錄》卷二十九。","）。"]', '["西山巍巍兮聳碧，漳水澄澄兮練色，对現分明有何極。","（以上十首均见《景德傳灯錄》卷二十九。","）。"]', '诗', 'shi', '', NULL, '寄鍾陵光僧正頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b61268d6-57ab-46e3-9c11-dbd050655941', '頌', '頌', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["理極忘情謂，如何有喻齊？","到頭霜夜月，任情（《林間錄》作「運」）落前溪。","菓熟猿兼（《林間錄》作「兼猿」）重，山長似路迷。","舉頭殘照在，元是住居西。","（《卍續藏經》本《大法眼文益禪師語錄》，又見《林間錄》卷下。","）。"]', '["理極忘情謂，如何有喻齊？","到头霜夜月，任情（《林间錄》作「運」）落前溪。","菓熟猿兼（《林间錄》作「兼猿」）重，山长似路迷。","舉头殘照在，元是住居西。","（《卍續藏經》本《大法眼文益禪師語錄》，又见《林间錄》卷下。","）。"]', '诗', 'shi', '', NULL, '頌 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1269c9-9ea4-4db2-8cd9-eceec6fa544f', '偈', '偈', 'b8b1ab98-0955-40a1-83e5-805b4c13ea3b', '唐', '["見山不是山，見非何曾別。","山河與大地，都是一輪月。","（《五燈會元》卷十一《三交智嵩禪師》引。","）。"]', '["见山不是山，见非何曾別。","山河與大地，都是一輪月。","（《五灯會元》卷十一《三交智嵩禪師》引。","）。"]', '诗', 'shi', '', NULL, '偈 文益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1791761c-01e4-4226-bd3e-b7e20ee8420e', '偈', '偈', 'cfc721e3-c38f-4f3f-9d5c-c7b98cf9db92', '唐', '["南山路仄（《五燈會元》作「側」）東山低（《祖庭事苑》作「東山路側西山低」），新到莫辭三轉（一作「擔」）泥。","嗟汝在途經日久，明明不曉（《祖庭事苑》作「向道」）却成迷。","（見《景德傳燈錄》卷二十、《五燈會元》卷六《祖庭事苑》卷二。","）。"]', '["南山路仄（《五灯會元》作「側」）东山低（《祖庭事苑》作「东山路側西山低」），新到莫辞三轉（一作「擔」）泥。","嗟汝在途經日久，明明不晓（《祖庭事苑》作「向道」）却成迷。","（见《景德傳灯錄》卷二十、《五灯會元》卷六《祖庭事苑》卷二。","）。"]', '诗', 'shi', '', NULL, '偈 善道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad27cbb-c3c2-4953-a602-c7daa25bdf5e', '頌 一', '頌 一', '754be6f3-f04b-4816-bed6-e542b147fcec', '唐', '["風動心搖樹，雲生性起塵。","若明今日事，昧却本來人。"]', '["风动心搖樹，云生性起塵。","若明今日事，昧却本来人。"]', '诗', 'shi', '', NULL, '頌 一 紹修 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80aada41-9d65-4e3f-83fb-a20da48489e1', '頌 二', '頌 二', '754be6f3-f04b-4816-bed6-e542b147fcec', '唐', '["欲識解脫道，諸法不相到。","眼耳絕見聞，聲色鬧浩浩。"]', '["欲識解脫道，諸法不相到。","眼耳絕见闻，声色鬧浩浩。"]', '诗', 'shi', '', NULL, '頌 二 紹修 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d7ac27-2f09-4961-8904-6f02b922c3b2', '頌 三', '頌 三', '754be6f3-f04b-4816-bed6-e542b147fcec', '唐', '["初心未入道，不得鬧浩浩。","鐘聲裏薦取，鼓聲裏顛倒。"]', '["初心未入道，不得鬧浩浩。","鐘声裏薦取，鼓声裏顛倒。"]', '诗', 'shi', '', NULL, '頌 三 紹修 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f16c748a-9f30-43d6-aaf8-32ab3602673f', '頌 諸佛不出世，四十九年說。祖師不西來，少林有妙訣。', '頌 諸佛不出世，四十九年说。祖師不西来，少林有妙訣。', '754be6f3-f04b-4816-bed6-e542b147fcec', '唐', '["萬法是心光，諸緣唯性曉。","本無迷悟人，秪要今日了。","（見《五燈會元》卷八。","）。"]', '["万法是心光，諸緣唯性晓。","本無迷悟人，秪要今日了。","（见《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '頌 諸佛不出世，四十九年說。祖師不西來，少林有妙訣。 紹修 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c78362-24f6-4b46-8faa-c5ff8e06707b', '頌 六', '頌 六', '754be6f3-f04b-4816-bed6-e542b147fcec', '唐', '["卷簾除却障，閉戶生窒礙。","祗這障與礙，古今無人會。","會得是障礙，不會不自在。","（同上。","）。"]', '["卷簾除却障，閉戶生窒礙。","祗這障與礙，古今無人會。","會得是障礙，不會不自在。","（同上。","）。"]', '诗', 'shi', '', NULL, '頌 六 紹修 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('777f8ac5-626b-4b60-bd91-caa003544c73', '詠馬（題擬）', '詠马（題擬）', '23e26056-a794-42a7-9a68-d081bb0092da', '唐', '["寶馬雕鞍貢紫庭，渥洼神駿舊傳名，四蹄蹀躞天階下，乍對龍顏不敢行。","（見《永樂大典》卷六八五一引《建安志》。","據《古籍整理出版情況簡報》一五六期刊張忱石先生《〈永樂大典〉續印本印象記》轉引。","）。"]', '["寶马雕鞍貢紫庭，渥洼神駿旧傳名，四蹄蹀躞天階下，乍对龙顏不敢行。","（见《永乐大典》卷六八五一引《建安志》。","據《古籍整理出版情況簡報》一五六期刊張忱石先生《〈永乐大典〉續印本印象記》轉引。","）。"]', '诗', 'shi', '', NULL, '詠馬（題擬） 王感化 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c551e3f-b0b7-4799-ac1c-ce8fab3f1942', '烈祖挽辭（題擬） 一', '烈祖挽辞（題擬） 一', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["宮砌無新樹。"]', '["宮砌無新樹。"]', '诗', 'shi', '', NULL, '烈祖挽辭（題擬） 一 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb67b39a-4717-4d8d-836a-86354d87ddaa', '烈祖挽辭（題擬） 二', '烈祖挽辞（題擬） 二', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["宮衣無組繡。"]', '["宮衣無組繡。"]', '诗', 'shi', '', NULL, '烈祖挽辭（題擬） 二 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8998d2aa-9216-4ea2-a414-cc3eb721ad24', '烈祖挽辭（題擬） 三', '烈祖挽辞（題擬） 三', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["宮樂盡塵埃。","（均見《知不足齋叢書》本佚名《五國故事》。","）。"]', '["宮乐尽塵埃。","（均见《知不足斋叢书》本佚名《五国故事》。","）。"]', '诗', 'shi', '', NULL, '烈祖挽辭（題擬） 三 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aeadd68-1c80-4529-9743-aa9f79051e59', '酒令 一', '酒令 一', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["先喫鱣魚，又喫旁蟹，一似拈虵弄蝎。","（使者。","）。"]', '["先喫鱣鱼，又喫旁蟹，一似拈虵弄蝎。","（使者。","）。"]', '诗', 'shi', '', NULL, '酒令 一 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb366a43-7d4c-4d62-84f0-8ed53c452368', '酒令 二', '酒令 二', 'cc18ac52-ef7c-48ef-8bf3-a5853dd72854', '唐', '["先喫乳酩，後喫喬團，一似噇膿灌血。","（齊丘。","見宋傅肱《蟹譜》卷下。","）（〖1〗《蟹譜》云：「藝祖時，嘗遣使至江表。","宋齊丘送於郊次，酒行語熟，使者啓令曰：須啗二物，各取南北所尚，復以二物，仍互用南北俚語。","使者曰〖略〗。","齊丘繼聲曰〖略〗。","時朝廷方草創，用度不給，倚江表爲外府，故齊丘及之。","左右以令逼使之太甚，相顧失色。","使者雅歎焉，故歸朝而間行。","」今按：齊入卒於宋立國前一年，此條所記恐有誤。","）。"]', '["先喫乳酩，後喫喬團，一似噇膿灌血。","（齊丘。","见宋傅肱《蟹譜》卷下。","）（〖1〗《蟹譜》云：「藝祖时，嘗遣使至江表。","宋齊丘送於郊次，酒行語熟，使者啓令曰：須啗二物，各取南北所尚，复以二物，仍互用南北俚語。","使者曰〖略〗。","齊丘繼声曰〖略〗。","时朝廷方草創，用度不給，倚江表爲外府，故齊丘及之。","左右以令逼使之太甚，相顧失色。","使者雅歎焉，故归朝而间行。","」今按：齊入卒於宋立国前一年，此條所記恐有誤。","）。"]', '诗', 'shi', '', NULL, '酒令 二 宋齊丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0747ec03-e256-4d8e-ae89-e1b64b005655', '句', '句', '2a74a08c-e5d6-48cb-8cc3-7c8818f9a515', '唐', '["夢斷海山遠，夜長風雨多。","（李中《碧雲集》卷二《哭舍弟二首》注引。","）（按：李中有《海城秋夕寄懷舍弟》、《哭舍弟二首》，其弟名未詳，據李中三詩看，知其能詩，上錄二句曾「傳至海上」。","歸故里後卒，李中稱其「夭枉」，身後有「遺稚」。","）。"]', '["梦斷海山远，夜长风雨多。","（李中《碧云集》卷二《哭舍弟二首》注引。","）（按：李中有《海城秋夕寄懷舍弟》、《哭舍弟二首》，其弟名未詳，據李中三诗看，知其能诗，上錄二句曾「傳至海上」。","归故里後卒，李中稱其「夭枉」，身後有「遺稚」。","）。"]', '诗', 'shi', '', NULL, '句 李□ shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf1e584f-e363-435f-97b5-232f87e42670', '偈', '偈', '3429bc2e-5ac1-46cb-b177-436cb84504e6', '唐', '["話道語下無聲，舉揚奧旨丁寧。","禪要如今會取，不須退後消停。","（《景德傳燈錄》卷十三、《五燈會元》卷九。","）。"]', '["話道語下無声，舉揚奧旨丁寧。","禪要如今會取，不須退後消停。","（《景德傳灯錄》卷十三、《五灯會元》卷九。","）。"]', '诗', 'shi', '', NULL, '偈 法滿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c3d7bc-4960-49a4-804f-a98189a63204', '句', '句', 'b9a684d8-93e4-497b-a82e-f19a3da55db9', '唐', '["卍字迴廊旋看月。","（沈雄《古今詞話·詞品》卷下引。","）。"]', '["卍字迴廊旋看月。","（沈雄《古今词話·词品》卷下引。","）。"]', '诗', 'shi', '', NULL, '句 馮延巳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa19910e-fb35-4973-a22c-6ef5d009671f', '十玄談（幷序） 心印', '十玄談（幷序） 心印', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["問君心印作何顏？心印何人敢授傳？歷劫坦然無異色，呼爲心印早虛言。","須知本自靈（《大正》本、《偈頌》作「體自虛」）空性，將喻紅罏焰（《大正》本、《偈頌》作「火」）裏蓮。","莫以（《大正》本作「莫謂」、《偈頌》作「勿謂」）無心便（《大正》本、《偈頌》作「云」）是道，無心猶隔一重關。"]', '["问君心印作何顏？心印何人敢授傳？歷劫坦然無異色，呼爲心印早虛言。","須知本自靈（《大正》本、《偈頌》作「體自虛」）空性，將喻紅罏焰（《大正》本、《偈頌》作「火」）裏蓮。","莫以（《大正》本作「莫謂」、《偈頌》作「勿謂」）無心便（《大正》本、《偈頌》作「云」）是道，無心猶隔一重关。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 心印 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f31e784-83ca-4359-a0cb-891f17304eea', '十玄談（幷序） 祖意', '十玄談（幷序） 祖意', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["祖意如空不是空，靈機爭墮有無功。","三賢固（《偈頌》作「尚」）未明斯旨，十聖那能達此宗。","透網金鱗猶滯水，回途石馬出沙（《偈頌》作「紗」）籠。","殷勤爲說西來意，莫問西來及與東。"]', '["祖意如空不是空，靈機爭墮有無功。","三賢固（《偈頌》作「尚」）未明斯旨，十聖那能達此宗。","透網金鱗猶滯水，回途石马出沙（《偈頌》作「紗」）籠。","殷勤爲说西来意，莫问西来及與东。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 祖意 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91000f28-648b-4b36-b3e3-7591d8609f08', '十玄談（幷序） 玄機', '十玄談（幷序） 玄機', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["迢迢空劫勿能收，豈爲塵機作繫留。","妙體本來無處所，通身何更問（《大正》本、《偈頌》作「有」）縱由？","靈然一句超羣象，迥出三乘不假修。","撒手那邊諸（《大正》本、《偈頌》作「千」）聖外，迴程堪作火中牛。"]', '["迢迢空劫勿能收，豈爲塵機作繫留。","妙體本来無处所，通身何更问（《大正》本、《偈頌》作「有」）縱由？","靈然一句超羣象，迥出三乘不假修。","撒手那邊諸（《大正》本、《偈頌》作「千」）聖外，迴程堪作火中牛。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 玄機 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b14787-b0b6-4c11-b44c-904c50098688', '十玄談（幷序） 塵異', '十玄談（幷序） 塵異', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["濁者自濁清者清，菩提煩惱等空平。","誰言卞璧無人鑒，我道驪珠到處晶。","萬法泯時全體現，三乘分處假（《大正》本、《偈頌》作「別假」）安名。","丈夫皆（《偈頌》作「自」）有衝天志，不（《大正》本、《偈頌》作「莫」）向如來行處行。"]', '["濁者自濁清者清，菩提煩惱等空平。","誰言卞璧無人鑒，我道驪珠到处晶。","万法泯时全體現，三乘分处假（《大正》本、《偈頌》作「別假」）安名。","丈夫皆（《偈頌》作「自」）有衝天志，不（《大正》本、《偈頌》作「莫」）向如来行处行。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 塵異 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de91852-680f-480c-af3c-b31c5b3ddc73', '十玄談（幷序） 佛教（《大正》本、《偈頌》作「演教」）', '十玄談（幷序） 佛教（《大正》本、《偈頌》作「演教」）', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["三時次第演金言，三世如來亦共宣。","初說有空人皆執，後非空有衆皆緣（《偈頌》作「捐」）。","龍宮滿藏（《偈頌》作「字」）醫方義，鶴樹終談理未玄。","真淨界中纔一念，閻浮早已八千年。"]', '["三时次第演金言，三世如来亦共宣。","初说有空人皆執，後非空有衆皆緣（《偈頌》作「捐」）。","龙宮满藏（《偈頌》作「字」）醫方義，鹤樹終談理未玄。","真淨界中纔一念，閻浮早已八千年。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 佛教（《大正》本、《偈頌》作「演教」） 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fedcff1-aeb4-4f53-b69f-4c6b668bf159', '十玄談（幷序） 鄉還曲（《大正》本、《偈頌》作「達本」）', '十玄談（幷序） 乡還曲（《大正》本、《偈頌》作「達本」）', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["勿於中路事空王，策杖咸須歸（《大正》本、《偈頌》作「還須達」）本鄉。","雲水隔時君莫住，雪山深處我非忙（《大正》本、《偈頌》作「忘」）。","尋思去日顏如玉，嗟歎迴來（《偈頌》作「時」）鬢似霜。","撒手到家人不識，更無一物獻尊堂。"]', '["勿於中路事空王，策杖咸須归（《大正》本、《偈頌》作「還須達」）本乡。","云水隔时君莫住，雪山深处我非忙（《大正》本、《偈頌》作「忘」）。","尋思去日顏如玉，嗟歎迴来（《偈頌》作「时」）鬢似霜。","撒手到家人不識，更無一物獻尊堂。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 鄉還曲（《大正》本、《偈頌》作「達本」） 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731915c9-eae9-40fa-9b7b-bba292dcd5c2', '十玄談（幷序） 破還鄉曲（《大正》本、《偈頌》作「還源」）', '十玄談（幷序） 破還乡曲（《大正》本、《偈頌》作「還源」）', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["返本還源事亦差，本來無住不名家。","萬年松徑雪深覆，一帶峰巒雲更遮。","賓主默時純（《大正》本、《偈頌》作「穆時全」）是妄，君臣道合（《大正》本、《偈頌》作「合處」）正中邪。","還鄉曲調如何物（《大正》、《偈頌》作「唱」）？","明月堂前枯木（《大正》本、《偈頌》作「樹」）華。"]', '["返本還源事亦差，本来無住不名家。","万年松徑雪深覆，一带峰巒云更遮。","賓主默时純（《大正》本、《偈頌》作「穆时全」）是妄，君臣道合（《大正》本、《偈頌》作「合处」）正中邪。","還乡曲調如何物（《大正》、《偈頌》作「唱」）？","明月堂前枯木（《大正》本、《偈頌》作「樹」）华。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 破還鄉曲（《大正》本、《偈頌》作「還源」） 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53857dec-e3bf-440f-bb1f-eb904c62b113', '十玄談（幷序） 轉位歸（《大正》本、《偈頌》作「迴機」）', '十玄談（幷序） 轉位归（《大正》本、《偈頌》作「迴機」）', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["湼槃城裏尚猶危，陌路相逢沒了（《大正》本作「沒定」、《偈頌》作「勿定」）期。","權掛垢衣云是佛，却裝珍御復名誰？木人夜半穿靴去，石女天明戴帽歸。","萬古碧潭空界月，再三澇（《大正》本、《偈頌》作「撈」）漉始應知。"]', '["湼槃城裏尚猶危，陌路相逢沒了（《大正》本作「沒定」、《偈頌》作「勿定」）期。","權掛垢衣云是佛，却裝珍御复名誰？木人夜半穿靴去，石女天明戴帽归。","万古碧潭空界月，再三澇（《大正》本、《偈頌》作「撈」）漉始應知。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 轉位歸（《大正》本、《偈頌》作「迴機」） 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71b38daa-4bc7-434d-89f1-3846c40b370f', '十玄談（幷序） 轉位', '十玄談（幷序） 轉位', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["披毛戴角入鄽來，優鉢羅花火裏開。","煩惱海中爲雨露，無明山上作雲雷。","鑊湯爐炭吹教滅，劍樹刀山喝使摧。","金鎖玄關留不住，行於異類且輪回。"]', '["披毛戴角入鄽来，優鉢羅花火裏开。","煩惱海中爲雨露，無明山上作云雷。","鑊湯爐炭吹教滅，劍樹刀山喝使摧。","金鎖玄关留不住，行於異類且輪回。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 轉位 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb239133-e8eb-4d96-8a51-7855bc557ac5', '十玄談（幷序） 正位前（《大正》本、《偈頌》作「一色」）', '十玄談（幷序） 正位前（《大正》本、《偈頌》作「一色」）', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["枯木巖前差路多，行人到此盡蹉𧿶。","鷺鷥立雪非同色，明月蘆華不似他。","了了了時無所（《大正》本、《偈頌》作「可」）了，玄玄玄處亦須呵。","殷勤爲唱玄中曲，空裏蟾光撮得麽？","（《四部叢刊三編》景宋本、《大正藏》本《景德傳燈錄》卷二九、《禪門諸祖師偈頌》卷上之上。","景宋本總題作「詩八首」，《十玄談》之題及《祖意》、《轉位》二首據《大正》本及《偈頌》補。","序僅見於《大正》本、有注云：「《卿公事苑》云：叢林所行《十玄談》皆無序引，愚曩游廬阜，得其序於同安影堂，今錄之云耳。","」《大正》本與景宋本之異，承張靖龍同志告知。","另可參《林間錄》卷下。","）。"]', '["枯木巖前差路多，行人到此尽蹉𧿶。","鷺鷥立雪非同色，明月蘆华不似他。","了了了时無所（《大正》本、《偈頌》作「可」）了，玄玄玄处亦須呵。","殷勤爲唱玄中曲，空裏蟾光撮得麽？","（《四部叢刊三編》景宋本、《大正藏》本《景德傳灯錄》卷二九、《禪门諸祖師偈頌》卷上之上。","景宋本總題作「诗八首」，《十玄談》之題及《祖意》、《轉位》二首據《大正》本及《偈頌》補。","序僅见於《大正》本、有注云：「《卿公事苑》云：叢林所行《十玄談》皆無序引，愚曩游廬阜，得其序於同安影堂，今錄之云耳。","」《大正》本與景宋本之異，承張靖龙同志告知。","另可參《林间錄》卷下。","）。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 正位前（《大正》本、《偈頌》作「一色」） 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ca5b173-c38c-4931-9200-93e5fb535de7', '十玄談（幷序） 搜玄吟', '十玄談（幷序） 搜玄吟', '4bd36ac4-87fb-4c1a-a689-c7f8dae9c759', '唐', '["三更初夜偏，日午月明前。","白雲覆幽石，青霄抱月圓，鷺鷥非雪覆，烏鵶豈漆漫。","紙馬通消息，知音白雀還。","夢手撃金鐘，覺來空把拳。","天明夜行人，無因行自先。","門門不迴互，迴互隔關山。","步空疑月色，湛寂皎非安。","龍吟明異寶，片玉鳳飛啣。","猿啼蔥嶺韻，鶴吐鷲峰烟。","金烏罩蓆帽，玉兔具靴形。","寒泉初夜後，古澗五更前。","黑白未分時，正是偏中圓。","露展幽林秀，雲收碧落閑。","空劫道人家，深宮蕩子嫌。","衣錦還鄉客，迴機面指南。","問我雪中吟，杲日耀澄潭。","無影桑樹子，玉女夜生蠶。","携籃日未出，摘菓月當軒。","手把寒天扇，身無五月衫。","採花入異鄉，將獻類中仙。","謹白參玄人，參禪莫守閑。","（《卍續藏經》本宋釋子昇、如祐編《禪門諸祖師偈頌》卷上之上。","）。"]', '["三更初夜偏，日午月明前。","白云覆幽石，青霄抱月圓，鷺鷥非雪覆，烏鵶豈漆漫。","紙马通消息，知音白雀還。","梦手撃金鐘，覺来空把拳。","天明夜行人，無因行自先。","门门不迴互，迴互隔关山。","步空疑月色，湛寂皎非安。","龙吟明異寶，片玉鳳飞啣。","猿啼蔥嶺韻，鹤吐鷲峰烟。","金烏罩蓆帽，玉兔具靴形。","寒泉初夜後，古澗五更前。","黑白未分时，正是偏中圓。","露展幽林秀，云收碧落闲。","空劫道人家，深宮蕩子嫌。","衣錦還乡客，迴機面指南。","问我雪中吟，杲日耀澄潭。","無影桑樹子，玉女夜生蠶。","携籃日未出，摘菓月當軒。","手把寒天扇，身無五月衫。","採花入異乡，將獻類中仙。","謹白參玄人，參禪莫守闲。","（《卍續藏經》本宋釋子昇、如祐編《禪门諸祖師偈頌》卷上之上。","）。"]', '诗', 'shi', '', NULL, '十玄談（幷序） 搜玄吟 常察 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa71b7ac-7729-4ca9-95f5-de725ac68bc2', '卦歌', '卦歌', '233e76f8-5aea-47f1-8822-f18350c62db0', '唐', '["水馬爲妻壻，不久下泉鄉。","命裏妨頭妻，再得口天娘。","（《新編分門古今類事》卷十六引《秘閣閑談》。","）（按：《秘閣閑談》云：吳淑之妹喪夫後，再配于馬淑。","「初，馬淑之先君在江南爲饒州副使，其前妻馮氏，方強壯之時，常使術士毛大仙者作卦歌。","其中曾述配偶之事曰〖歌略〗。","後馮卒，再娶吳氏。","」）。"]', '["水马爲妻壻，不久下泉乡。","命裏妨头妻，再得口天娘。","（《新編分门古今類事》卷十六引《秘閣闲談》。","）（按：《秘閣闲談》云：吳淑之妹喪夫後，再配于马淑。","「初，马淑之先君在江南爲饒州副使，其前妻馮氏，方強壯之时，常使術士毛大仙者作卦歌。","其中曾述配偶之事曰〖歌略〗。","後馮卒，再娶吳氏。","」）。"]', '诗', 'shi', '', NULL, '卦歌 毛大仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6feb8fe-d5f7-43d5-9d4c-e9ccb2f9eda5', '偈', '偈', '7f1a6117-0cd6-4afc-8ace-1238c8fea4b1', '唐', '["騰空正是時，應須眨上眉。","好茲出倫去，莫待白頭兒。","（《景德傳燈錄》卷二十三、《五燈會元》卷八。","）。"]', '["腾空正是时，應須眨上眉。","好茲出倫去，莫待白头兒。","（《景德傳灯錄》卷二十三、《五灯會元》卷八。","）。"]', '诗', 'shi', '', NULL, '偈 隱微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed196ea-0b0e-42c9-8b41-9c2fd391276b', '題遠大師塔', '題远大師塔', '997b4451-ed54-444e-b582-a6213eec23aa', '唐', '["元墓石稜稜，寒雲晚景凝。","空悲虎溪月，不見應門僧。","（《太平寰宇記》卷一一一《江州》。","）（按：《廬山記》卷四、《萬首唐人絕句》卷九五、《全唐詩》卷八一○收此詩爲僧靈澈作。","按《全唐詩》卷七五○李中有《送相里秀才之匡山國子監》詩，相里秀才即相里宗，身份、地點皆合，可知其爲南唐人。","《太平寰宇記》稱此詩爲「南進士相里宗題詩」，此書作者樂史爲南唐入宋之人，又爲江西人，其說當可信。","）。"]', '["元墓石稜稜，寒云晚景凝。","空悲虎溪月，不见應门僧。","（《太平寰宇記》卷一一一《江州》。","）（按：《廬山記》卷四、《万首唐人絕句》卷九五、《全唐诗》卷八一○收此诗爲僧靈澈作。","按《全唐诗》卷七五○李中有《送相里秀才之匡山国子監》诗，相里秀才即相里宗，身份、地点皆合，可知其爲南唐人。","《太平寰宇記》稱此诗爲「南進士相里宗題诗」，此书作者乐史爲南唐入宋之人，又爲江西人，其说當可信。","）。"]', '诗', 'shi', '', NULL, '題遠大師塔 相里宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4067d18a-a2ef-460d-94a9-4ac1d1dc7bdf', '歸國南轅之日答揆相贈詩（題擬）', '归国南轅之日答揆相贈诗（題擬）', 'f0c799a5-5bfa-4e55-9c87-f6617a159274', '唐', '["羅巾揮逸翰，送我出夷門。","保惜安懷袖，流傳與子孫。"]', '["羅巾揮逸翰，送我出夷门。","保惜安懷袖，流傳與子孫。"]', '诗', 'shi', '', NULL, '歸國南轅之日答揆相贈詩（題擬） 馮延魯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7941ee-04f1-4948-b1b9-c2a58b96a853', '贈李學士', '贈李学士', 'f0c799a5-5bfa-4e55-9c87-f6617a159274', '唐', '["鄰居纔十步，交分已三年。","（均見王禹偁《小畜集》卷二十《馮氏家集前序》引。","）。"]', '["鄰居纔十步，交分已三年。","（均见王禹偁《小畜集》卷二十《馮氏家集前序》引。","）。"]', '诗', 'shi', '', NULL, '贈李學士 馮延魯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bffe8500-b7b5-4af9-b033-66bbe3acf66f', '偈', '偈', 'e90d50ac-6e21-43f1-b001-1457a8e30368', '唐', '["年來（一作「來年」）二月二，別汝暫相棄。","爇（一作「燒」）灰散四林，勿（一作「免」）占檀那地。","（見《景德傳燈錄》卷二十二。","注一作者爲《五燈會元》卷八之異文。","）。"]', '["年来（一作「来年」）二月二，別汝暫相棄。","爇（一作「燒」）灰散四林，勿（一作「免」）占檀那地。","（见《景德傳灯錄》卷二十二。","注一作者爲《五灯會元》卷八之異文。","）。"]', '诗', 'shi', '', NULL, '偈 志端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77087618-a861-47db-a258-825fae8d7615', '簡寂觀', '簡寂观', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["山藏勝境當樓臺，[□□□□]洞府開。","白髮滿頭誰肯到，蒼苔盈步自偷來。","風帆閑事拋三日，玉液長生念一盃。","此路有心星月在，杏壇仙侶莫相猜。","（按：詩中首聯，影宋鈔本聯寫，無空格。","羅振玉《殷禮在斯堂叢書》校排本《廬山記》補四空格于「當」字下。","今詳詩韻及詩意，所缺當爲第二句之前四字。","）。"]', '["山藏勝境當楼台，[□□□□]洞府开。","白髮满头誰肯到，蒼苔盈步自偷来。","风帆闲事拋三日，玉液长生念一盃。","此路有心星月在，杏壇仙侶莫相猜。","（按：诗中首聯，影宋鈔本聯寫，無空格。","羅振玉《殷禮在斯堂叢书》校排本《廬山記》補四空格于「當」字下。","今詳诗韻及诗意，所缺當爲第二句之前四字。","）。"]', '诗', 'shi', '', NULL, '簡寂觀 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e909184-d0b0-4991-9894-a757f50526a7', '再到東林寺', '再到东林寺', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["十五年前還到此，池深苔蘚樹垂藤。","重遊數處心傷日，不見舊時頭白僧。","花有露含長夜月，殿無風動徹明燈。","堪驚此去老又老，未有更來能不能。"]', '["十五年前還到此，池深苔蘚樹垂藤。","重游數处心傷日，不见旧时头白僧。","花有露含长夜月，殿無风动徹明灯。","堪驚此去老又老，未有更来能不能。"]', '诗', 'shi', '', NULL, '再到東林寺 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f217941e-9d06-4b2b-bc45-bf35db2b9c47', '瀑布', '瀑布', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["瀉出嶽中源化水，噴成瀑布世還希（《殷禮在斯堂叢書》本「希」作「稀」）。","雖如仙女偷來織，不見山公採得歸。","萬古色嫌明月薄，千尋勇學白雲飛。","若言真箇堪裁剪，預被豪家買作衣。"]', '["瀉出嶽中源化水，噴成瀑布世還希（《殷禮在斯堂叢书》本「希」作「稀」）。","雖如仙女偷来织，不见山公採得归。","万古色嫌明月薄，千尋勇学白云飞。","若言真箇堪裁剪，預被豪家買作衣。"]', '诗', 'shi', '', NULL, '瀑布 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e16091-acc9-413a-84cd-d281787792e9', '望廬山', '望廬山', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["東過匡廬忍醉眠，雙眸盡日挂危巔。","壓低吳楚殽涵水，約破雲霞獨倚天。","一面峭來無鳥徑，數峰狂欲趁漁船。","江人莫笑偏凝望，卜隱長思瀑布前。","（以上四首均見《吉石盦叢書》影印日本高山寺藏宋抄本陳舜俞《廬山記》卷四。","）（按：《望廬山》三四兩句，《全唐詩》卷七四三已據《野客叢書》卷十七收入，「殽」作「遙」。","）。"]', '["东過匡廬忍醉眠，雙眸尽日挂危巔。","壓低吳楚殽涵水，約破云霞独倚天。","一面峭来無鸟徑，數峰狂欲趁漁船。","江人莫笑偏凝望，卜隐长思瀑布前。","（以上四首均见《吉石盦叢书》影印日本高山寺藏宋抄本陳舜俞《廬山記》卷四。","）（按：《望廬山》三四兩句，《全唐诗》卷七四三已據《野客叢书》卷十七收入，「殽」作「遙」。","）。"]', '诗', 'shi', '', NULL, '望廬山 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9184074c-ead2-43d1-8e56-ed3cbef2472a', '萍鄉春晚寓居（四首） 一', '萍乡春晚寓居（四首） 一', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["向隅書劍坐銷魂，心計艱難有淚痕。","三月不尋花下路，一春常閉雨中門。","閑時易得開書帙，貧手難求傍酒樽。","三十無成今四十，翊周安漢意空存。"]', '["向隅书劍坐銷魂，心計艱难有泪痕。","三月不尋花下路，一春常閉雨中门。","闲时易得开书帙，貧手难求傍酒樽。","三十無成今四十，翊周安漢意空存。"]', '诗', 'shi', '', NULL, '萍鄉春晚寓居（四首） 一 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfafaf6-4ac2-461b-9c53-57da42d15c96', '萍鄉春晚寓居（四首） 二', '萍乡春晚寓居（四首） 二', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["花替殘紅草綠深，江頭閒事豈堪尋。","雲山憶後思藏跡，家國話來長痛心。","戰地血流猶未服，侯門心熱更相歆。","求歸閑處無閑處。","三紀兵戈猶至今。"]', '["花替殘紅草綠深，江头閒事豈堪尋。","云山憶後思藏跡，家国話来长痛心。","戰地血流猶未服，侯门心熱更相歆。","求归闲处無闲处。","三紀兵戈猶至今。"]', '诗', 'shi', '', NULL, '萍鄉春晚寓居（四首） 二 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6beb704e-487a-4055-9e33-7b73369c5b00', '萍鄉春晚寓居（四首） 三', '萍乡春晚寓居（四首） 三', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["黃鳥垂楊一兩聲，流年流去不勝情。","已傷野徑鎖春色，空睡山窻愁月明。","金山真堪沽酒散，山河到了爲誰爭。","古人盡入平蕪去，虛對馮唐誇後生。"]', '["黄鸟垂楊一兩声，流年流去不勝情。","已傷野徑鎖春色，空睡山窻愁月明。","金山真堪沽酒散，山河到了爲誰爭。","古人尽入平蕪去，虛对馮唐誇後生。"]', '诗', 'shi', '', NULL, '萍鄉春晚寓居（四首） 三 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee08ced4-6557-4a01-a8fe-64daa24d7ee2', '萍鄉春晚寓居（四首） 四', '萍乡春晚寓居（四首） 四', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["葉老遊蜂不更忙，春殘去去好思量。","倚根託蒂花猶落，損力耗心誰可常。","江樹不能留野水，晚煙多共恨斜陽。","感時傷事皆頭白，幾箇漁竿遇帝主。","（見同治十一年刊錫榮纂《萍鄉縣志》卷六）（按：《萍鄉縣志》收沈詩爲宋初之作，誤。","民國間李有鋆纂《昭萍志略》卷十二已改歸唐代。","）。"]', '["葉老游蜂不更忙，春殘去去好思量。","倚根託蒂花猶落，損力耗心誰可常。","江樹不能留野水，晚煙多共恨斜陽。","感时傷事皆头白，幾箇漁竿遇帝主。","（见同治十一年刊錫榮纂《萍乡縣志》卷六）（按：《萍乡縣志》收沈诗爲宋初之作，誤。","民国间李有鋆纂《昭萍志略》卷十二已改归唐代。","）。"]', '诗', 'shi', '', NULL, '萍鄉春晚寓居（四首） 四 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6e057e-9cba-43e7-b8e1-f7633442de22', '句 一', '句 一', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["花片亂飛愁殺人。","（《永樂大典》卷八二二引《考古質疑》引葛次仲集句引。","）。"]', '["花片亂飞愁殺人。","（《永乐大典》卷八二二引《考古質疑》引葛次仲集句引。","）。"]', '诗', 'shi', '', NULL, '句 一 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('060cf73a-dc21-4376-93b3-b2581ff1c16d', '句 二', '句 二', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["更好碧溪深院靜。","（《江湖小集》卷七紹嵩《江浙紀行集句詩》引。","）。"]', '["更好碧溪深院静。","（《江湖小集》卷七紹嵩《江浙紀行集句诗》引。","）。"]', '诗', 'shi', '', NULL, '句 二 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ede5f25d-0450-45d8-b8a0-af29edfa6d3b', '句 三', '句 三', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["黛潑千山出蜀來。","（《小畜外集》卷七《仲咸因春游商山下行三怪石輦致郡下甚有幽趣序其始末題六十韻見示依韻和之》引。","）。"]', '["黛潑千山出蜀来。","（《小畜外集》卷七《仲咸因春游商山下行三怪石輦致郡下甚有幽趣序其始末題六十韻见示依韻和之》引。","）。"]', '诗', 'shi', '', NULL, '句 三 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4be9947e-a7d8-4c2c-b090-8cbc3bb371ab', '句', '句', 'a8506600-e0f6-4826-bfab-57f0ffaacd9b', '唐', '["醒眼看諸峰，白雲開又集。","（見《能改齋漫錄》卷八。","）（按：中華上編本《能改齋漫錄》引此作「五代時陳况詩」，「况」爲「貺」之誤，鄭方坤《五代詩話》卷三所引不誤。","）。"]', '["醒眼看諸峰，白云开又集。","（见《能改斋漫錄》卷八。","）（按：中华上編本《能改斋漫錄》引此作「五代时陳况诗」，「况」爲「貺」之誤，鄭方坤《五代诗話》卷三所引不誤。","）。"]', '诗', 'shi', '', NULL, '句 陳貺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24bf32f-4a14-4c0f-bc6d-68de849189ae', '懷海上故人', '懷海上故人', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["路遙滄海內，人隔此生中。"]', '["路遙滄海內，人隔此生中。"]', '诗', 'shi', '', NULL, '懷海上故人 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ae21fe-1b75-4531-9039-84a53592fbef', '落花', '落花', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["千家簾幕春空在，幾處樓臺月自明。","（均見《吟窗雜錄》卷十四王玄《詩中旨格》。","）。"]', '["千家簾幕春空在，幾处楼台月自明。","（均见《吟窗杂錄》卷十四王玄《诗中旨格》。","）。"]', '诗', 'shi', '', NULL, '落花 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08c1efbb-6674-4a66-bfeb-1312d040aae6', '', '', '51c45908-4c9a-4cd0-ba31-1fe584612e89', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 用虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b40041-9f81-4e58-92ee-e1149cdba647', '題棲霞寺詩（幷序）', '題棲霞寺诗（幷序）', '51c45908-4c9a-4cd0-ba31-1fe584612e89', '唐', '["寺居方外□□□□□寰中□□幽□勝好（下泐）名跡向茲休（按右詩是七律幽休韻。","）。"]', '["寺居方外□□□□□寰中□□幽□勝好（下泐）名跡向茲休（按右诗是七律幽休韻。","）。"]', '诗', 'shi', '', NULL, '題棲霞寺詩（幷序） 用虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b91514f-9a23-449c-9dd3-cb91781eda03', '宿（下泐。按是詩題下似是「千」字，當[是]〖時〗宿千佛巖詩。） 一', '宿（下泐。按是诗題下似是「千」字，當[是]〖时〗宿千佛巖诗。） 一', '51c45908-4c9a-4cd0-ba31-1fe584612e89', '唐', '["境占江南（下泐十三字幷四行。","按第四行當是第三詩題。","）。"]', '["境占江南（下泐十三字幷四行。","按第四行當是第三诗題。","）。"]', '诗', 'shi', '', NULL, '宿（下泐。按是詩題下似是「千」字，當[是]〖時〗宿千佛巖詩。） 一 用虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10d9941-0cb2-4daa-b6d0-cad738e72d10', '宿（下泐。按是詩題下似是「千」字，當[是]〖時〗宿千佛巖詩。） 二', '宿（下泐。按是诗題下似是「千」字，當[是]〖时〗宿千佛巖诗。） 二', '51c45908-4c9a-4cd0-ba31-1fe584612e89', '唐', '["力（按似「勞」字）迥中秋出（下泐十二字）彩分雖遠金（下泐十二字幷三行。","按第行當是第四詩題。","）。"]', '["力（按似「勞」字）迥中秋出（下泐十二字）彩分雖远金（下泐十二字幷三行。","按第行當是第四诗題。","）。"]', '诗', 'shi', '', NULL, '宿（下泐。按是詩題下似是「千」字，當[是]〖時〗宿千佛巖詩。） 二 用虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c218e291-bbf4-463c-98d8-b3637a3e9550', '宿（下泐。按是詩題下似是「千」字，當[是]〖時〗宿千佛巖詩。） 三', '宿（下泐。按是诗題下似是「千」字，當[是]〖时〗宿千佛巖诗。） 三', '51c45908-4c9a-4cd0-ba31-1fe584612e89', '唐', '["樂□□山（下泐十九字𠔍按似是「黃」字）梅敢比肩（下泐六字）畔看雲□□立庵前天台從（下泐六字）須（下泐。","按右詩似詠植物肩前韻。","見《江蘇通志稿·藝文志·金石》卷七引《續江寧石刻記》）（按：用虛詩刻石在上元攝山，摩崖泐甚，末題：「□〖按當是唐字〗上元甲子歲次〖下泐〗僧用虛〖下泐〗」《續江寧石刻記》跋云：「右詩刻剝泐太甚，搨本僅存六十八字，細宷當是七律四首。","前有序，在千佛巖，距無量殿不遠。","宋張敦頤《六朝事迹》、《攝山志》並著錄。","嚴記在待訪目，《江寧府志》云：『無量殿旁有正書石碣一，惜剝蝕太甚，莫能辨作者姓名，中存大唐上元歲數字。","』殆即指此。","遯甲三元術以唐興元元年甲子爲上元，會昌四年甲子爲中元，天祐元年甲子爲下元，宋乾[德]〖元〗二年甲子又上元也。","此詩當刻於乾德二年以後，時南唐奉宋正朔，故不署年號。","」此組詩殘泐太甚，已無從點斷。","）。"]', '["乐□□山（下泐十九字𠔍按似是「黄」字）梅敢比肩（下泐六字）畔看云□□立庵前天台從（下泐六字）須（下泐。","按右诗似詠植物肩前韻。","见《江蘇通志稿·藝文志·金石》卷七引《續江寧石刻記》）（按：用虛诗刻石在上元攝山，摩崖泐甚，末題：「□〖按當是唐字〗上元甲子歲次〖下泐〗僧用虛〖下泐〗」《續江寧石刻記》跋云：「右诗刻剝泐太甚，搨本僅存六十八字，細宷當是七律四首。","前有序，在千佛巖，距無量殿不远。","宋張敦頤《六朝事迹》、《攝山志》並著錄。","嚴記在待訪目，《江寧府志》云：『無量殿旁有正书石碣一，惜剝蝕太甚，莫能辨作者姓名，中存大唐上元歲數字。","』殆即指此。","遯甲三元術以唐兴元元年甲子爲上元，會昌四年甲子爲中元，天祐元年甲子爲下元，宋乾[德]〖元〗二年甲子又上元也。","此诗當刻於乾德二年以後，时南唐奉宋正朔，故不署年號。","」此組诗殘泐太甚，已無從点斷。","）。"]', '诗', 'shi', '', NULL, '宿（下泐。按是詩題下似是「千」字，當[是]〖時〗宿千佛巖詩。） 三 用虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da83d258-1f7e-4d24-b9de-b88c3eece05d', '', '', '46166e07-5cd4-4093-ba87-5f92936cf4b4', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 梅遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fe34a64-b675-4634-9fb9-1f91c4fc51da', '築居', '築居', '46166e07-5cd4-4093-ba87-5f92936cf4b4', '唐', '["昔居苕之南，今適宛之北。","溪山故繚繞，往來等鄉國。","愛此太古風，不但占林樾。","嵐氣敬亭浮，波光響潭接。","雖在城市傍，而與喧囂隔。","息心謝紛煩，投閒遺一切。","結構類茅茨，寧復事雕餙。","草堂亦易成，經營豈木石。","喜見野人來，漸與塵迹絕。","把我盈樽酒，妻兒同一啜。"]', '["昔居苕之南，今適宛之北。","溪山故繚繞，往来等乡国。","愛此太古风，不但占林樾。","嵐氣敬亭浮，波光响潭接。","雖在城市傍，而與喧囂隔。","息心謝紛煩，投閒遺一切。","結構類茅茨，寧复事雕餙。","草堂亦易成，經營豈木石。","喜见野人来，漸與塵迹絕。","把我盈樽酒，妻兒同一啜。"]', '诗', 'shi', '', NULL, '築居 梅遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997478ad-a649-4156-b5ab-7ddbbadbd838', '遷居', '遷居', '46166e07-5cd4-4093-ba87-5f92936cf4b4', '唐', '["百里猶鄉土，千年亦比鄰。","願言培世德，未敢詠維新。","（均見清施念曾、張汝霖編《宛雅三編》卷二、嘉慶廿八年刊洪亮吉等纂《寧國府志》卷二十四。","）（按：梅遠爲北宋著名詩人梅堯臣的曾祖。","《歐陽文忠公文集》卷三三《梅聖俞墓誌銘》云：「曾祖諱遠，祖諱邈，皆不仕。","」楊傑《無爲集》卷十三《故朝奉郎守殿中丞梅君〖正臣〗墓誌銘》云：「南唐末，曾祖遠爲宣城掾。","」正臣爲堯臣弟。","《宛雅三編》卷二引《梅氏詩譜》，謂遠字維明，光化間由吳興之宣城爲掾。","以宣之風土淳厚，遂築居於州學之西，著有《遷居草》。","今按：三書所記稍有出入。","考《歐陽文忠公文集》卷三十一《太子中舍梅君墓誌銘》，堯臣父梅讓卒於皇祐元年，年九十一，推其生年，爲顯德六年。","以此推測，梅遠約生於十世紀初，以仕南唐爲是。","《梅氏詩譜》有誤，今不取光化年仕宣說。","）。"]', '["百里猶乡土，千年亦比鄰。","願言培世德，未敢詠維新。","（均见清施念曾、張汝霖編《宛雅三編》卷二、嘉慶廿八年刊洪亮吉等纂《寧国府志》卷二十四。","）（按：梅远爲北宋著名诗人梅堯臣的曾祖。","《歐陽文忠公文集》卷三三《梅聖俞墓誌銘》云：「曾祖諱远，祖諱邈，皆不仕。","」楊傑《無爲集》卷十三《故朝奉郎守殿中丞梅君〖正臣〗墓誌銘》云：「南唐末，曾祖远爲宣城掾。","」正臣爲堯臣弟。","《宛雅三編》卷二引《梅氏诗譜》，謂远字維明，光化间由吳兴之宣城爲掾。","以宣之风土淳厚，遂築居於州学之西，著有《遷居草》。","今按：三书所記稍有出入。","考《歐陽文忠公文集》卷三十一《太子中舍梅君墓誌銘》，堯臣父梅讓卒於皇祐元年，年九十一，推其生年，爲显德六年。","以此推測，梅远約生於十世紀初，以仕南唐爲是。","《梅氏诗譜》有誤，今不取光化年仕宣说。","）。"]', '诗', 'shi', '', NULL, '遷居 梅遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb7ace2-5738-4104-90aa-6d5163a74249', '句 一', '句 一', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["直儗將心付杜康。","（見《野客叢書》卷六。","）。"]', '["直儗將心付杜康。","（见《野客叢书》卷六。","）。"]', '诗', 'shi', '', NULL, '句 一 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff2e207-0efa-4fc4-8c36-f0d122fa0223', '句 二', '句 二', '458918d8-a1b6-44cb-9338-181d6089e74f', '唐', '["荆溪百里水涵空。","（見《輿地紀勝》卷七《鎮江府》。","）（按：《紀勝》錄此句，作者爲「潘佐」，「佐」爲「佑」之誤。","潘佑《送人往宣城》，《萬首唐人絕句》卷九九、《全唐詩》卷七七○又收潘佐名下，可證。","）。"]', '["荆溪百里水涵空。","（见《輿地紀勝》卷七《鎮江府》。","）（按：《紀勝》錄此句，作者爲「潘佐」，「佐」爲「佑」之誤。","潘佑《送人往宣城》，《万首唐人絕句》卷九九、《全唐诗》卷七七○又收潘佐名下，可證。","）。"]', '诗', 'shi', '', NULL, '句 二 潘佑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22051356-1ac4-4e3f-bce7-7ef64f1bac28', '題天申宮三首 一', '題天申宮三首 一', 'c6bfaf53-a820-4d09-ae7c-5add210830de', '唐', '["殿闕（《宜興縣志》作「閣」）盤空壓巨鰲，洗然靈迹助風騷。","玉龍臥久洞雲冷，玄鶴唳頻山月高。","深谷羽童探石菌，曉堂真侶飲櫻（《宜興縣志》作「仙」）桃。","可憐不悟長生者，塵裏區區改鬢毛。"]', '["殿闕（《宜兴縣志》作「閣」）盤空壓巨鰲，洗然靈迹助风騷。","玉龙臥久洞云冷，玄鹤唳頻山月高。","深谷羽童探石菌，晓堂真侶饮櫻（《宜兴縣志》作「仙」）桃。","可怜不悟长生者，塵裏區區改鬢毛。"]', '诗', 'shi', '', NULL, '題天申宮三首 一 宋維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469d2691-0576-4636-97c3-b1527fb31a6e', '題天申宮三首 二', '題天申宮三首 二', 'c6bfaf53-a820-4d09-ae7c-5add210830de', '唐', '["中峰嘉樹綠陰陰，洞裏靈蹤已遍尋。","欲下山門又迴首，數聲清磬白雲深。"]', '["中峰嘉樹綠陰陰，洞裏靈蹤已遍尋。","欲下山门又迴首，數声清磬白云深。"]', '诗', 'shi', '', NULL, '題天申宮三首 二 宋維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('937414cb-7932-4be3-9170-771819bd28ac', '題天申宮三首 三', '題天申宮三首 三', 'c6bfaf53-a820-4d09-ae7c-5add210830de', '唐', '["雲嵐滿袖倚嵓扉，龍窟寒生夜睡遲。","一曲朱絃誰與聽，月斜風撼碧桃枝。","（見洪武刻本《咸淳毘陵志》卷二十二，嘉慶二年刊寧楷等纂《宜興縣志》卷十收第一首。","）（按：《四庫全書》本《江南通志》卷一一九錄宋乾德進士有宋維。","疑維初居江南，後北上應試。","《毘陵志》歸南唐，今從之。","）。"]', '["云嵐满袖倚嵓扉，龙窟寒生夜睡遲。","一曲朱絃誰與听，月斜风撼碧桃枝。","（见洪武刻本《咸淳毘陵志》卷二十二，嘉慶二年刊寧楷等纂《宜兴縣志》卷十收第一首。","）（按：《四庫全书》本《江南通志》卷一一九錄宋乾德進士有宋維。","疑維初居江南，後北上應試。","《毘陵志》归南唐，今從之。","）。"]', '诗', 'shi', '', NULL, '題天申宮三首 三 宋維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e73262e-7998-4b45-b57e-a6eb252caaf4', '', '', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('427b62e2-ae1c-4a2a-9121-35e13f333c36', '古鏡歌三首 一', '古镜歌三首 一', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["盡道古鏡不曾見，借你時人看一徧。","目前不覩一纖豪，湛湛冷光凝一片。","凝一片，無背面，嫫母臨妝不稱情，潘生迴首頻嘉歎。","何欣欣，何戚戚，好醜由來那箇是（《大正藏》本作「從來那是的」）？","只遮是，轉沈醉，演若晨窺怖走時，子細思量還有以。","我問顛狂不暫迴，淚流向予聲哀哀。","哽咽未能申吐得，你頭與影悠悠哉！悠悠哉，爾許多時那裡來？","迷雲開，行行攜手上高臺。"]', '["尽道古镜不曾见，借你时人看一徧。","目前不覩一纖豪，湛湛冷光凝一片。","凝一片，無背面，嫫母臨妝不稱情，潘生迴首頻嘉歎。","何欣欣，何戚戚，好醜由来那箇是（《大正藏》本作「從来那是的」）？","只遮是，轉沈醉，演若晨窺怖走时，子細思量還有以。","我问顛狂不暫迴，泪流向予声哀哀。","哽咽未能申吐得，你头與影悠悠哉！悠悠哉，爾許多时那裡来？","迷云开，行行携手上高台。"]', '诗', 'shi', '', NULL, '古鏡歌三首 一 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('166d7f05-0e01-481e-88b0-187a3b4e6937', '古鏡歌三首 二', '古镜歌三首 二', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["誰云古鏡無樣度，古人出入何門戶？","門戶君看不見時，即此爲君全顯露。","全顯露（《大正藏》本無此三字），與汝一生終保護。","若遇知音請益來，逢人不得輕分付。","但任作見面，不須生怕怖，看取當時演若多，直至如今成錯悮。","如今不省影分明，還是當時同一顧。","同一顧，苦苦苦！。"]', '["誰云古镜無樣度，古人出入何门戶？","门戶君看不见时，即此爲君全显露。","全显露（《大正藏》本無此三字），與汝一生終保護。","若遇知音請益来，逢人不得轻分付。","但任作见面，不須生怕怖，看取當时演若多，直至如今成錯悮。","如今不省影分明，還是當时同一顧。","同一顧，苦苦苦！。"]', '诗', 'shi', '', NULL, '古鏡歌三首 二 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b2a1e95-5dfe-4f60-aac8-26e3a2728970', '古鏡歌三首 三', '古镜歌三首 三', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["古鏡精明皎皎，皎皎徧照河沙。","到處安名題字，除儂更有誰家？","過去未來現在，諸佛鏡上纖瑕。","纖瑕垢盡無物，此真火裏蓮華。","蓮花千朵萬朵，朵朵端然釋迦。","誰云俱屍入滅？誰云穿膝蘆牙？不信鏡中看取，羊車鹿車牛車。","時人不識古鏡，盡道本地清淨。","祇看清淨是假，照得形容不正。","或圓或短或長，若有纖豪俱病。","勸君不如打破，鏡去瑕消可瑩。","亦見杜口毘[耶]，亦知圓通少剩。","（見景宋本《景德傳燈錄》卷三十。","「耶」字原缺，據《大正藏》本補）。"]', '["古镜精明皎皎，皎皎徧照河沙。","到处安名題字，除儂更有誰家？","過去未来現在，諸佛镜上纖瑕。","纖瑕垢尽無物，此真火裏蓮华。","蓮花千朵万朵，朵朵端然釋迦。","誰云俱屍入滅？誰云穿膝蘆牙？不信镜中看取，羊车鹿车牛车。","时人不識古镜，尽道本地清淨。","祇看清淨是假，照得形容不正。","或圓或短或长，若有纖豪俱病。","勸君不如打破，镜去瑕消可瑩。","亦见杜口毘[耶]，亦知圓通少剩。","（见景宋本《景德傳灯錄》卷三十。","「耶」字原缺，據《大正藏》本補）。"]', '诗', 'shi', '', NULL, '古鏡歌三首 三 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2587cab0-1157-4168-83e8-e900c7ed9d84', '擬寒山 一', '擬寒山 一', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["今古應無墜，分明在目前。","片雲生晚谷，孤鶴下遙天。","岸柳含煙翠，溪花帶雨（《註華嚴經題法界觀門頌》卷上作「露」）鮮。","誰人知此意？令我憶南泉。"]', '["今古應無墜，分明在目前。","片云生晚谷，孤鹤下遙天。","岸柳含煙翠，溪花带雨（《註华嚴經題法界观门頌》卷上作「露」）鲜。","誰人知此意？令我憶南泉。"]', '诗', 'shi', '', NULL, '擬寒山 一 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab3aee5-2626-4270-9d31-719f707e4543', '擬寒山 二', '擬寒山 二', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["幽鳥語如篁，柳垂金線長。","煙收山谷靜，風送杏花香。","永日蕭然坐，澄心萬慮亡。","欲言言不及，林下好商量。"]', '["幽鸟語如篁，柳垂金線长。","煙收山谷静，风送杏花香。","永日蕭然坐，澄心万慮亡。","欲言言不及，林下好商量。"]', '诗', 'shi', '', NULL, '擬寒山 二 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b51ca70-b83e-409a-a13c-4f7f25c95fb4', '擬寒山 三', '擬寒山 三', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["誰信天真佛，興悲幾萬般。","蓼花開古岸，白鷺立沙灘。","露滴庭莎長，雲收溪月寒。","頭頭垂示處，子細好生觀（《註華嚴經題法界觀門頌》卷上作「看」）。"]', '["誰信天真佛，兴悲幾万般。","蓼花开古岸，白鷺立沙灘。","露滴庭莎长，云收溪月寒。","头头垂示处，子細好生观（《註华嚴經題法界观门頌》卷上作「看」）。"]', '诗', 'shi', '', NULL, '擬寒山 三 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200995ae-d00d-4114-be20-37ea235cea03', '擬寒山 四', '擬寒山 四', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["閑步游南陌，唯便野興多。","傍花看蝶舞，近柳聽鶯歌。","稚子撈溪萊，山翁携蕨蘿。","問渠何處住，迴首指前坡。"]', '["闲步游南陌，唯便野兴多。","傍花看蝶舞，近柳听鶯歌。","稚子撈溪萊，山翁携蕨蘿。","问渠何处住，迴首指前坡。"]', '诗', 'shi', '', NULL, '擬寒山 四 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c6dc42-f331-45b1-8fb4-cb7c3667fb00', '擬寒山 五', '擬寒山 五', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["每思同道者，屈指有寒山。","得意千峯下，無人共往還。","朝看雲片片，暮聽水潺潺。","若問幽奇處，儂家住此間。"]', '["每思同道者，屈指有寒山。","得意千峯下，無人共往還。","朝看云片片，暮听水潺潺。","若问幽奇处，儂家住此间。"]', '诗', 'shi', '', NULL, '擬寒山 五 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5bf8532-5aeb-4bda-bfe3-c9757cbd10d0', '擬寒山 六', '擬寒山 六', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["三春媚景時，疊嶂含煙雨。","携藍採蕨歸，和米鐺中煮。","食罷展殘書，鶯鳥關關語。","此情孰可論，唯我能相許。"]', '["三春媚景时，叠嶂含煙雨。","携藍採蕨归，和米鐺中煮。","食罷展殘书，鶯鸟关关語。","此情孰可論，唯我能相許。"]', '诗', 'shi', '', NULL, '擬寒山 六 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c4e8cf-caef-48c5-8a62-fa69096554ba', '擬寒山 七', '擬寒山 七', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["幽巖我自悟，路險無人到。","寒燒帶葉柴，倦即和衣倒。","閒牕任月明，落葉從風掃。","住茲不計年，漸覺垂垂老。"]', '["幽巖我自悟，路險無人到。","寒燒带葉柴，倦即和衣倒。","閒牕任月明，落葉從风掃。","住茲不計年，漸覺垂垂老。"]', '诗', 'shi', '', NULL, '擬寒山 七 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c73ce34-9710-4ef4-a11a-b9bb8313a5ab', '擬寒山 八', '擬寒山 八', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["野老負薪歸，催婦連宵織。","看他家事忙，且道承誰力。","問渠渠不知，特地生疑惑。","傷嗟今古人，幾箇知恩德。"]', '["野老負薪归，催婦連宵织。","看他家事忙，且道承誰力。","问渠渠不知，特地生疑惑。","傷嗟今古人，幾箇知恩德。"]', '诗', 'shi', '', NULL, '擬寒山 八 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b5ee292-52aa-4fe4-9ab4-c3e1da7999b9', '擬寒山 九', '擬寒山 九', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["自住國清寺，因循經幾年。","不窮三藏教，匪學祖師禪。","一事攻燒火，餘閑任性眠。","生涯何所有？今古與人傳。"]', '["自住国清寺，因循經幾年。","不窮三藏教，匪学祖師禪。","一事攻燒火，餘闲任性眠。","生涯何所有？今古與人傳。"]', '诗', 'shi', '', NULL, '擬寒山 九 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8260b7d7-ddb1-47b2-8460-a04767cf26f5', '擬寒山 十', '擬寒山 十', '9935ed26-6560-41d5-aa29-43833a88984d', '唐', '["颯颯西風起，飄飄細雨飛。","前村孤嶺上，樵父擁蓑歸。","躡履尋荒徑，搘筇似力微。","時人應笑我，笑我者還稀。","（《卍續藏經》本宋釋子昇、如祐編《禪門諸祖師偈頌》卷上之上。","）。"]', '["颯颯西风起，飄飄細雨飞。","前村孤嶺上，樵父擁蓑归。","躡履尋荒徑，搘筇似力微。","时人應笑我，笑我者還稀。","（《卍續藏經》本宋釋子昇、如祐編《禪门諸祖師偈頌》卷上之上。","）。"]', '诗', 'shi', '', NULL, '擬寒山 十 泰欽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b206dbd-720e-4f75-87e1-a314d171a960', '柱杖頌', '柱杖頌', 'ea662771-3df8-446b-9600-3ff6b6d58c69', '唐', '["四面一條杖，當機驗龍象。","頭角稍低昂，電光臨背上。","（《天聖廣燈錄》卷二四、《五燈會元》卷十四。","）。"]', '["四面一條杖，當機驗龙象。","头角稍低昂，電光臨背上。","（《天聖廣灯錄》卷二四、《五灯會元》卷十四。","）。"]', '诗', 'shi', '', NULL, '柱杖頌 寶津 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e808bb7-f1cd-4284-9995-ed67df80608c', '偈', '偈', '36df5026-30ee-4cdc-90a2-dde7bd02851c', '唐', '["秋江煙島晴，鷗鷺行行立。","不念觀世音，爭知普門入。","（見《景德傳燈錄》卷二十六、《五燈會元》卷十。","）。"]', '["秋江煙島晴，鷗鷺行行立。","不念观世音，爭知普门入。","（见《景德傳灯錄》卷二十六、《五灯會元》卷十。","）。"]', '诗', 'shi', '', NULL, '偈 可勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8de43b0-b2d3-471c-9158-764b3e8d9294', '烏衣巷', '烏衣巷', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["閥閱淪亡梐枑移，年年舊燕亦雙歸。","茅簷葦萡無冠蓋，不見烏衣見白衣。","（《景定建康志》卷十六。","）。"]', '["閥閱淪亡梐枑移，年年旧燕亦雙归。","茅簷葦萡無冠蓋，不见烏衣见白衣。","（《景定建康志》卷十六。","）。"]', '诗', 'shi', '', NULL, '烏衣巷 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f796a5e-98d9-4dbf-b1ea-ea871d5d0303', '半陽湖', '半陽湖', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["江南龍節水爲鄉，水不純（《六朝事迹編類》作「絕」）陰又半陽。","一片湖光共深淺，兩般泉脉異溫涼。","（同前卷十八。","又見《六朝事跡編類》卷上。","）。"]', '["江南龙節水爲乡，水不純（《六朝事迹編類》作「絕」）陰又半陽。","一片湖光共深淺，兩般泉脉異溫涼。","（同前卷十八。","又见《六朝事跡編類》卷上。","）。"]', '诗', 'shi', '', NULL, '半陽湖 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ba2e0d-7aab-4ad6-ab97-a7dc0f76a283', '潮溝', '潮溝', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["流水東西傍帝臺，六朝重爲兩朝開。","曾有蠲首知高下，莫問魚皮識去來。","（同前卷十九。","）。"]', '["流水东西傍帝台，六朝重爲兩朝开。","曾有蠲首知高下，莫问鱼皮識去来。","（同前卷十九。","）。"]', '诗', 'shi', '', NULL, '潮溝 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60d4df28-6a83-4bec-8141-8001734d9cf2', '直瀆', '直瀆', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["晝役人功夜鬼功，陽開陰闔幾時終。","不聞擲土江中語，爭得盈流一水通。","（同前。","又見《六朝事迹編類》卷上。","）。"]', '["晝役人功夜鬼功，陽开陰闔幾时終。","不闻擲土江中語，爭得盈流一水通。","（同前。","又见《六朝事迹編類》卷上。","）。"]', '诗', 'shi', '', NULL, '直瀆 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99965f0e-f546-43f9-9a81-1240e6dda296', '運瀆', '運瀆', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["舳艫銜尾日無虛，更鑿都城引漕渠。","何事餒來貪雀穀，不知留得幾年儲？","（同前。","）。"]', '["舳艫銜尾日無虛，更鑿都城引漕渠。","何事餒来貪雀穀，不知留得幾年儲？","（同前。","）。"]', '诗', 'shi', '', NULL, '運瀆 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b671af-e723-4885-9888-8eaecaaf64fc', '鳳凰臺', '鳳凰台', 'bad50f1f-7129-472c-8ad2-4ebcd3d9d710', '唐', '["竹影桐陰滿舊山，鳳凰多載不飛還。","登臺只有吹簫者，爭得和鳴墮世間。","（同前卷二十二。","）（按：朱存《金陵古迹詩》四卷，《崇文總目》卷五著錄，惟作者訛作李存。","《景定建康志》卷四九云：「宋〖當作「朱」〗存，字闕，金陵人也。","嘗讀吳大帝而下六朝書，具詳歷代興亡成敗之迹，南唐時作《覽古詩》二百章，章四句。","沿初洎末，爛然棋布，閱詩者嘉其用心之勤云。","」今存者僅十六首。","另《景定建康志》卷十八云「陳軒《金陵集》有李建勳、朱存《迎擔湖詩》，今未見。","」又宋張惇頤《六朝事迹編類》收楊修詩四十八首，其中《新亭》、《秦淮》、《北渠》、《天闕山》、《三斷石》五首，《輿地紀勝》卷十七皆作朱存詩，僅《新亭》文字差異較大；《直瀆》、《半陽湖》二首，《景定建康志》也作朱存詩，《景定建康志》卷四九云：「楊備字修之，……慶曆中爲尚書虞部員外郎分司南京上輕車都尉，往復道出江上，賦百篇二韻，命曰《覽古百題詩》，各注其事於題之下，與南唐朱存詩並傳於世。","」知二人詩在宋時已有傳誤。","但應以孰是，尚難決斷。","楊詩除《六朝事迹編類》所收外，《景定建康志》存六十首，去其重復，約存八十餘首。","）。"]', '["竹影桐陰满旧山，鳳凰多載不飞還。","登台只有吹簫者，爭得和鳴墮世间。","（同前卷二十二。","）（按：朱存《金陵古迹诗》四卷，《崇文總目》卷五著錄，惟作者訛作李存。","《景定建康志》卷四九云：「宋〖當作「朱」〗存，字闕，金陵人也。","嘗读吳大帝而下六朝书，具詳歷代兴亡成敗之迹，南唐时作《覽古诗》二百章，章四句。","沿初洎末，爛然棋布，閱诗者嘉其用心之勤云。","」今存者僅十六首。","另《景定建康志》卷十八云「陳軒《金陵集》有李建勳、朱存《迎擔湖诗》，今未见。","」又宋張惇頤《六朝事迹編類》收楊修诗四十八首，其中《新亭》、《秦淮》、《北渠》、《天闕山》、《三斷石》五首，《輿地紀勝》卷十七皆作朱存诗，僅《新亭》文字差異較大；《直瀆》、《半陽湖》二首，《景定建康志》也作朱存诗，《景定建康志》卷四九云：「楊備字修之，……慶曆中爲尚书虞部員外郎分司南京上轻车都尉，往复道出江上，賦百篇二韻，命曰《覽古百題诗》，各注其事於題之下，與南唐朱存诗並傳於世。","」知二人诗在宋时已有傳誤。","但應以孰是，尚难決斷。","楊诗除《六朝事迹編類》所收外，《景定建康志》存六十首，去其重复，約存八十餘首。","）。"]', '诗', 'shi', '', NULL, '鳳凰臺 朱存 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93fffa6a-ad50-488b-8186-fabb83c797a2', '醉歌', '醉歌', 'e3c19ee9-5d4a-4605-aab7-de2101e160fc', '唐', '["藍採禾，藍採禾，（《江南野史》卷十首二句作「藍采采」一句，）塵世紛紛世更多。","爭如賣藥沽酒飲，歸去深崖拍手歌。","（見馬令《南唐書》卷十五。","）（〖1〗《江南野史》卷十《陳陶傳》：「開寶中常見一叟，角髮被褐，與一鍊師舁藥入城鬻之，獲貲則市鮮就爐，二人對飲且唱，旁若無人。","既醉且舞而歌曰〖略〗。","時人見其縱逸，姿貌非常，每飲酒食鮓，疑爲陶之夫婦焉。","竟不知所終，或云得仙矣。","」〖2〗馬令《南唐書》卷十五《陳陶傳》：「開寶中常見一叟，角髮被褐，與老媼貨藥於市，獲錢則市鮓對飲，旁若無人，既醉，行舞而歌曰〖略〗。","或疑爲陶之夫婦云。","」按：陳陶爲大中間人，今存其詩，事迹歷歷可考。","自大中至開寶，已逾百年。","得仙之說，固屬附會，陶即耆壽，恐亦難以存活一百數十年之久，何況當時即爲存疑，幷無必證，今列之，另以「開寶中江南叟」列目。","）。"]', '["藍採禾，藍採禾，（《江南野史》卷十首二句作「藍采采」一句，）塵世紛紛世更多。","爭如賣藥沽酒饮，归去深崖拍手歌。","（见马令《南唐书》卷十五。","）（〖1〗《江南野史》卷十《陳陶傳》：「开寶中常见一叟，角髮被褐，與一鍊師舁藥入城鬻之，獲貲則市鲜就爐，二人对饮且唱，旁若無人。","既醉且舞而歌曰〖略〗。","时人见其縱逸，姿貌非常，每饮酒食鮓，疑爲陶之夫婦焉。","竟不知所終，或云得仙矣。","」〖2〗马令《南唐书》卷十五《陳陶傳》：「开寶中常见一叟，角髮被褐，與老媼貨藥於市，獲錢則市鮓对饮，旁若無人，既醉，行舞而歌曰〖略〗。","或疑爲陶之夫婦云。","」按：陳陶爲大中间人，今存其诗，事迹歷歷可考。","自大中至开寶，已逾百年。","得仙之说，固屬附會，陶即耆壽，恐亦难以存活一百數十年之久，何況當时即爲存疑，幷無必證，今列之，另以「开寶中江南叟」列目。","）。"]', '诗', 'shi', '', NULL, '醉歌 開寶中江南叟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4000c4d8-cf8a-467c-8032-05af97128ee8', '游南雁蕩詩', '游南雁蕩诗', 'bbc8e560-c039-4ecb-bb3d-587079e66b9d', '唐', '["雁山遙與白雲連，六十奇峯半倚天。","金鼎雨花猿聽偈，石門迎月鶴參禪。","戲龍高躍青霄上，羣鳳齊飛赤日邊。","詩思憑空吟不了，那堪夙駕入星躔。","（見周喟《南雁蕩山志》卷一引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》等。","）（按：陳德誠逸詩及小傳，皆承張靖龍同志錄示。","）。"]', '["雁山遙與白云連，六十奇峯半倚天。","金鼎雨花猿听偈，石门迎月鹤參禪。","戲龙高躍青霄上，羣鳳齊飞赤日邊。","诗思憑空吟不了，那堪夙駕入星躔。","（见周喟《南雁蕩山志》卷一引陳玭《嘉靖南雁山志》、鄭思恭《崇禎南雁山志》等。","）（按：陳德誠逸诗及小傳，皆承張靖龙同志錄示。","）。"]', '诗', 'shi', '', NULL, '游南雁蕩詩 陳德誠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8278be13-ba08-4936-b627-56f2363b47b4', '贈孟賓于（題擬）', '贈孟賓于（題擬）', 'bf39613d-aabf-44e9-a1c1-c285697800f4', '唐', '["上國登科建業遊，鼎分蹤跡便淹留。","江干旅夢三千里，海內詩名四十秋。","華表柱邊人不識，爛柯山下水空流。","自從叔寶朝天後，贏得安閑養白頭。","（周本淳校點本《詩話總龜》卷二八引《雅言系述》。","）（按：此詩當作于南唐授士之次年，援舊例仍收入。","）。"]', '["上国登科建業游，鼎分蹤跡便淹留。","江干旅梦三千里，海內诗名四十秋。","华表柱邊人不識，爛柯山下水空流。","自從叔寶朝天後，贏得安闲養白头。","（周本淳校点本《诗話總龟》卷二八引《雅言系述》。","）（按：此诗當作于南唐授士之次年，援旧例仍收入。","）。"]', '诗', 'shi', '', NULL, '贈孟賓于（題擬） 趙晟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a0a0d4-da94-479c-91fe-81e1b2813b2c', '句 一', '句 一', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["吾祖幷州隔萬山，吾家多難謫郴連。"]', '["吾祖幷州隔万山，吾家多难謫郴連。"]', '诗', 'shi', '', NULL, '句 一 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4108610e-894a-45cb-934d-ee1a36fb5d68', '句 二', '句 二', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["十載戀明主。"]', '["十載戀明主。"]', '诗', 'shi', '', NULL, '句 二 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f756b725-bef2-4ee0-aa00-1924ef1029e6', '句 三', '句 三', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["兩京遊寺曾題牓，五舉逢知始看花。","（均見宋王禹偁《小畜集》卷二十《孟水部詩集序》引。","）。"]', '["兩京游寺曾題牓，五舉逢知始看花。","（均见宋王禹偁《小畜集》卷二十《孟水部诗集序》引。","）。"]', '诗', 'shi', '', NULL, '句 三 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e8be905-f108-4588-baca-0251bdeb01c3', '投贈張鴻（題擬）', '投贈張鴻（題擬）', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["自憐成事攀仙桂，誰似投閑向草萊。","（見康熙《連州志》卷五《張鴻傳》引。","又收入《粤詩蒐逸》卷一。","）。"]', '["自怜成事攀仙桂，誰似投闲向草萊。","（见康熙《連州志》卷五《張鴻傳》引。","又收入《粤诗蒐逸》卷一。","）。"]', '诗', 'shi', '', NULL, '投贈張鴻（題擬） 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ddd0c90-7ca9-4d42-9647-592b1fe75d20', '續父題壁（題擬）', '續父題壁（題擬）', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["他家養兒三四五，我家養兒獨且苦。","（賓于父。","）衆星不如孤月明，牛羊滿山畏獨虎。","（賓于）。","（見《小草齋詩話》卷四、康熙《連州志》卷五《孟賓于傳》）（〖1〗《連州志》：「父以家貧。","且賓于無他兄弟，題其壁云〖詩略〗。","賓于從鄉校歸，續曰〖詩略〗。","」）。"]', '["他家養兒三四五，我家養兒独且苦。","（賓于父。","）衆星不如孤月明，牛羊满山畏独虎。","（賓于）。","（见《小草斋诗話》卷四、康熙《連州志》卷五《孟賓于傳》）（〖1〗《連州志》：「父以家貧。","且賓于無他兄弟，題其壁云〖诗略〗。","賓于從乡校归，續曰〖诗略〗。","」）。"]', '诗', 'shi', '', NULL, '續父題壁（題擬） 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('575fa0ab-ad7f-4ef9-a468-c2e425e8239e', '', '', '61acac17-4cf7-4595-9d09-fcd31a4823d6', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王仲簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e12a10b-0a2c-4d44-a738-61a0d55265ca', '贈耿郎中', '贈耿郎中', '61acac17-4cf7-4595-9d09-fcd31a4823d6', '唐', '["得接英賢喜可知，人生能得幾多時。","自從別後顏容改，恰似庭前雨舊碑。","（見《增修詩話總龜前集》卷三三引《郡閣雅談》。","）（按：《郡閣雅談》云此詩爲仲簡卒後其兄仲偉夢莊客持書來附詩。","仲簡與耿振顯德中同官，此詩恐係當時作而後人附會入夢者。","今收錄，俟續考。","）。"]', '["得接英賢喜可知，人生能得幾多时。","自從別後顏容改，恰似庭前雨旧碑。","（见《增修诗話總龟前集》卷三三引《郡閣雅談》。","）（按：《郡閣雅談》云此诗爲仲簡卒後其兄仲偉梦莊客持书来附诗。","仲簡與耿振显德中同官，此诗恐係當时作而後人附會入梦者。","今收錄，俟續考。","）。"]', '诗', 'shi', '', NULL, '贈耿郎中 王仲簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8c6d72-edf5-490a-9fc4-e53ab4a0dff5', '寄徐鼎臣（題擬）', '寄徐鼎臣（題擬）', '19525b74-c9d2-4fdf-8065-e15f025daade', '唐', '["常思帝里奉交親，別後光陰屈指頻。","蘭佩却歸綸閣下，荆枝猶寄楚江濱。","十程山水勞幽夢，滿院煙花醉別人。","料得此生強健在，會須重賞昔年春。","（《徐公文集》卷三。","）（按：《徐公文集》卷三收此詩，題作《表弟包穎見寄》，題下注：「此子侍親在饒州，累年臥疾。","」詳詩意，此詩爲包穎寄徐鉉之作，詩題及題注爲徐鉉自編文集所加。","《全唐詩》卷七五三以此詩爲徐鉉作，而將徐鉉和詩收包穎名下，實誤，今爲移正之。","此則參《文史》二十五期曹汛先生文。","）。"]', '["常思帝里奉交親，別後光陰屈指頻。","蘭佩却归綸閣下，荆枝猶寄楚江濱。","十程山水勞幽梦，满院煙花醉別人。","料得此生強健在，會須重賞昔年春。","（《徐公文集》卷三。","）（按：《徐公文集》卷三收此诗，題作《表弟包穎见寄》，題下注：「此子侍親在饒州，累年臥疾。","」詳诗意，此诗爲包穎寄徐鉉之作，诗題及題注爲徐鉉自編文集所加。","《全唐诗》卷七五三以此诗爲徐鉉作，而將徐鉉和诗收包穎名下，實誤，今爲移正之。","此則參《文史》二十五期曹汛先生文。","）。"]', '诗', 'shi', '', NULL, '寄徐鼎臣（題擬） 包穎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13cc08d1-6cf1-45d1-a7dd-a43516bed7cf', '招徐鼎臣（題擬）', '招徐鼎臣（題擬）', '6184a4c7-a8b0-4561-be83-c1c147c2ca82', '唐', '["看看潘鬢二毛生，昨日林梢又轉鸎。","欲對春風忘世慮，敢言尊酒召時英。","假中西閣幸無事，筵中南威幸有情。","不得車公終不樂，已教紅袖出門迎。","（《徐公文集》卷二。","）（按：《徐公文集》此詩題作《寄鍾謨》，其次爲《正初答鍾郎中見招》，二詩皆用「鸎」、「英」、「情」、「迎」四韻。","詳詩意，前詩爲春初招人過訪之作，後詩爲答前詩之作。","因此，前詩應爲鍾謨作，後詩始爲徐鉉作。","《全唐詩》卷七五二以二詩皆歸徐鉉，未允，今爲移正。","以上參《文史》二十五期曹汛先生文。","）。"]', '["看看潘鬢二毛生，昨日林梢又轉鸎。","欲对春风忘世慮，敢言尊酒召时英。","假中西閣幸無事，筵中南威幸有情。","不得车公終不乐，已教紅袖出门迎。","（《徐公文集》卷二。","）（按：《徐公文集》此诗題作《寄鍾謨》，其次爲《正初答鍾郎中见招》，二诗皆用「鸎」、「英」、「情」、「迎」四韻。","詳诗意，前诗爲春初招人過訪之作，後诗爲答前诗之作。","因此，前诗應爲鍾謨作，後诗始爲徐鉉作。","《全唐诗》卷七五二以二诗皆归徐鉉，未允，今爲移正。","以上參《文史》二十五期曹汛先生文。","）。"]', '诗', 'shi', '', NULL, '招徐鼎臣（題擬） 鍾謨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee4e22b-5968-485c-ae15-eeaaf6a696e3', '偈', '偈', 'b11a59d6-49df-4a28-9077-3f619041cd9b', '唐', '["不要三乘要祖宗，三乘不要與君同。","君今欲會通宗旨，後夜猿啼在亂峰。"]', '["不要三乘要祖宗，三乘不要與君同。","君今欲會通宗旨，後夜猿啼在亂峰。"]', '诗', 'shi', '', NULL, '偈 道恒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ecde57-d70f-4e14-b9c3-4c840c543027', '頌 一', '頌 一', 'b11a59d6-49df-4a28-9077-3f619041cd9b', '唐', '["百丈有三訣，喫茶珍重歇。","直下便承當，敢保君未徹。"]', '["百丈有三訣，喫茶珍重歇。","直下便承當，敢保君未徹。"]', '诗', 'shi', '', NULL, '頌 一 道恒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a2a41cd-2496-4554-a695-4311cf8a5cb8', '頌 二', '頌 二', 'b11a59d6-49df-4a28-9077-3f619041cd9b', '唐', '["過去已過去，未來更莫算。","兀然無事坐，何曾有人喚？","（均見《五燈會元》卷十。","）。"]', '["過去已過去，未来更莫算。","兀然無事坐，何曾有人喚？","（均见《五灯會元》卷十。","）。"]', '诗', 'shi', '', NULL, '頌 二 道恒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d7318c6-1170-4dba-a687-9214ba179480', '金蓮步', '金蓮步', '16db2903-7d8c-48e4-9007-a544d8158917', '唐', '["金陵佳麗不虛傳，浦浦荷花水上仙。","未會與民同樂意，卻於宮裏看金蓮。","（見周密《浩然齋雅談》卷中。","）（按：《全唐詩》卷七九五收鎬詩二句。","但姓名誤爲齊鎬。","）。"]', '["金陵佳丽不虛傳，浦浦荷花水上仙。","未會與民同乐意，卻於宮裏看金蓮。","（见周密《浩然斋雅談》卷中。","）（按：《全唐诗》卷七九五收鎬诗二句。","但姓名誤爲齊鎬。","）。"]', '诗', 'shi', '', NULL, '金蓮步 唐鎬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2b93b1-948f-45fa-96d2-51f3f0bc6374', '桃花夫人廟', '桃花夫人廟', '7abd3cc2-c656-4047-95e3-cdc633bb1db0', '唐', '["一樹桃花發，桃花即是君。","空祠臨野水，何處覓閑雲。","事跡樵人說，爐香過客焚。","雨添碑上蘚，難讀古時文。","（見陸心源《宋詩紀事補遺》卷二引《續輯漢陽縣志》。","）。"]', '["一樹桃花發，桃花即是君。","空祠臨野水，何处覓闲云。","事跡樵人说，爐香過客焚。","雨添碑上蘚，难读古时文。","（见陸心源《宋诗紀事補遺》卷二引《續輯漢陽縣志》。","）。"]', '诗', 'shi', '', NULL, '桃花夫人廟 徐熙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d8208f9-f180-4183-b9d8-7c86b434d559', '題常州忠烈王廟', '題常州忠烈王廟', 'd6ae7b86-b47c-400b-acfc-6235fcc85643', '唐', '["松竹蕭蕭野笛悲，寂寥冰雪對旌旗。","前山月夜陰風起，神去神來人不知。","（見《增修詩話總龜》卷十五引《郡閣雅談》、《咸淳毗陵志》卷二十二。","）。"]', '["松竹蕭蕭野笛悲，寂寥冰雪对旌旗。","前山月夜陰风起，神去神来人不知。","（见《增修诗話總龟》卷十五引《郡閣雅談》、《咸淳毗陵志》卷二十二。","）。"]', '诗', 'shi', '', NULL, '題常州忠烈王廟 任右元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b20c802c-41b2-423e-a538-3bdea1525f72', '', '', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7830852c-3894-4785-85ba-1d27604e9fff', '幸後湖開宴賞荷花作（題擬）', '幸後湖开宴賞荷花作（題擬）', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["蓼稍蘸水火不滅，水鳥驚魚銀梭投。","滿目荷花千萬頃，紅碧相雜敷清流。","孫武已斬吳宮女，瑠璃池上佳人頭。","（見宋佚名《新編分門古今類事》卷十三引《翰苑名談》並《詩話》。","）（〖1〗《新編分門古今類事》云：「江南李後主嘗一日幸後湖，開宴賞荷花，忽作古詩云〖詩略〗。","當時識者咸謂吳宮中而有佳人頭，非吉兆也。","」後果應驗。","按：《增修詩話總龜》卷三一引《摭遺》謂此詩爲李璟作，《全唐詩》卷八因之，實誤。","《分門古今類事》同條後引李煜詩事甚詳，可證。","文長，恕不備錄。","）。"]', '["蓼稍蘸水火不滅，水鸟驚鱼銀梭投。","满目荷花千万頃，紅碧相杂敷清流。","孫武已斬吳宮女，瑠璃池上佳人头。","（见宋佚名《新編分门古今類事》卷十三引《翰苑名談》並《诗話》。","）（〖1〗《新編分门古今類事》云：「江南李後主嘗一日幸後湖，开宴賞荷花，忽作古诗云〖诗略〗。","當时識者咸謂吳宮中而有佳人头，非吉兆也。","」後果應驗。","按：《增修诗話總龟》卷三一引《摭遺》謂此诗爲李璟作，《全唐诗》卷八因之，實誤。","《分门古今類事》同條後引李煜诗事甚詳，可證。","文长，恕不備錄。","）。"]', '诗', 'shi', '', NULL, '幸後湖開宴賞荷花作（題擬） 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e799413a-259f-4516-a599-716af69cd078', '宿石頭清涼大道場（題擬）', '宿石头清涼大道場（題擬）', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["未能歸去宿龍宮。","（見《六朝事迹編類》卷下、《景定建康志》卷四六、《至元金陵新志》卷十一。","）。"]', '["未能归去宿龙宮。","（见《六朝事迹編類》卷下、《景定建康志》卷四六、《至元金陵新志》卷十一。","）。"]', '诗', 'shi', '', NULL, '宿石頭清涼大道場（題擬） 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7261ff-b632-4f3e-8ea3-086f2b338a9e', '句 一', '句 一', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["鉛砌美銀光，飾井雕葩植。","（見宋葉延珪纂《海錄碎事》卷三。","）。"]', '["鉛砌美銀光，飾井雕葩植。","（见宋葉延珪纂《海錄碎事》卷三。","）。"]', '诗', 'shi', '', NULL, '句 一 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf55714-6e0d-4b44-8894-8db23b34d089', '句 二', '句 二', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["一朝承凱澤，萬里荆荒陬。","（見同書卷四。","）。"]', '["一朝承凱澤，万里荆荒陬。","（见同书卷四。","）。"]', '诗', 'shi', '', NULL, '句 二 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6f94d84-0fdb-4af2-b439-02ec2d70bd97', '句 三', '句 三', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["玉俎且共甘，羽觴合同嘉。"]', '["玉俎且共甘，羽觴合同嘉。"]', '诗', 'shi', '', NULL, '句 三 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf862635-d37c-4df6-b349-6a9e4c3dd5ec', '句 四', '句 四', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["金缸（疑當作「釭」）明五夜，玉盤羅八珍。","（均見同書卷六。","）（按：《唐音統籤》卷七五四僅從《海錄碎事》卷一補入「日映仙雲薄，秋高天碧深」二句，《全唐詩》卷八仍之，以上八句均失收。","）。"]', '["金缸（疑當作「釭」）明五夜，玉盤羅八珍。","（均见同书卷六。","）（按：《唐音統籤》卷七五四僅從《海錄碎事》卷一補入「日映仙云薄，秋高天碧深」二句，《全唐诗》卷八仍之，以上八句均失收。","）。"]', '诗', 'shi', '', NULL, '句 四 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c39d23-2946-48a1-8110-1bfe2c02e111', '句 五', '句 五', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["別易會難無可奈。","（見《能改齋漫錄》卷十六。","）。"]', '["別易會难無可奈。","（见《能改斋漫錄》卷十六。","）。"]', '诗', 'shi', '', NULL, '句 五 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd425db2-cfb8-4f7d-9ebe-38321c11a204', '句 六', '句 六', 'e29a0a76-16b6-4227-9a65-351e2e8537ff', '唐', '["不堪閑坐細思量。","（胡偉《宮詞》。","）。"]', '["不堪闲坐細思量。","（胡偉《宮词》。","）。"]', '诗', 'shi', '', NULL, '句 六 李煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ecce34a-f816-48a9-b909-d3a9430238ce', '丙寅歲與徐鉉同賦（題擬）', '丙寅歲與徐鉉同賦（題擬）', '22693b0d-d8ce-407e-ac3e-692765e33efe', '唐', '["學《易》寧無道，知非素有心。","（《徐公文集》卷二十九《大宋故尚書兵部員外郎江君墓誌銘》。","）。"]', '["学《易》寧無道，知非素有心。","（《徐公文集》卷二十九《大宋故尚书兵部員外郎江君墓誌銘》。","）。"]', '诗', 'shi', '', NULL, '丙寅歲與徐鉉同賦（題擬） 江直木 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22cce179-2291-4553-a5de-8319c3412861', '題棺木 一', '題棺木 一', 'cfe7ffe6-d23d-49ae-8d8c-a6fb6baadf73', '唐', '["久久終需要，而（《類說》作「如」）今未要君。","有時閑憶者，大是要知聞。","（《宋朝事實類苑》卷六三引《楊文公談苑》。","《類說》卷五三僅引前二句。","）。"]', '["久久終需要，而（《類说》作「如」）今未要君。","有时闲憶者，大是要知闻。","（《宋朝事實類苑》卷六三引《楊文公談苑》。","《類说》卷五三僅引前二句。","）。"]', '诗', 'shi', '', NULL, '題棺木 一 朱貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d66df83-edae-4d71-84e9-2a595bd221a2', '題棺木 二', '題棺木 二', 'cfe7ffe6-d23d-49ae-8d8c-a6fb6baadf73', '唐', '["一夜小園開似雪。","（《江湖小集》卷八紹嵩《江浙紀行集句詩》。","）（按：朱貞白，《全唐詩》卷八七○作李貞白。","《增修詩話總龜前集》卷二十引《談苑》作李正白，「正」爲諱改。","《類說》引作朱貞白。","今從《宋朝事實類苑》列目。","）。"]', '["一夜小园开似雪。","（《江湖小集》卷八紹嵩《江浙紀行集句诗》。","）（按：朱貞白，《全唐诗》卷八七○作李貞白。","《增修诗話總龟前集》卷二十引《談苑》作李正白，「正」爲諱改。","《類说》引作朱貞白。","今從《宋朝事實類苑》列目。","）。"]', '诗', 'shi', '', NULL, '題棺木 二 朱貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8528b6a1-60e4-4f11-b449-772990351feb', '題胡氏華林書院（題擬）', '題胡氏华林书院（題擬）', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["盡說靈蹤好畫圖，幽奇高尚義羣居。","山林總是神仙隱，禮樂爰修周孔書。","解駕十年惟壯士，担簦千里結名廬。","功成霄漢非常事，對此那堪不我欺。","（見宣統元年刊《甘竹胡氏十修族譜》，轉引自《文學遺產》一九八四年第三期刊謝先模《宋人佚詩一束》。","）。"]', '["尽说靈蹤好畫圖，幽奇高尚義羣居。","山林總是神仙隐，禮乐爰修周孔书。","解駕十年惟壯士，担簦千里結名廬。","功成霄漢非常事，对此那堪不我欺。","（见宣統元年刊《甘竹胡氏十修族譜》，轉引自《文学遺產》一九八四年第三期刊謝先模《宋人佚诗一束》。","）。"]', '诗', 'shi', '', NULL, '題胡氏華林書院（題擬） 許堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f5488a-4cbb-4647-9ee7-90b6110856b8', '查公山詩', '查公山诗', '90db44a4-0efa-4cab-a42b-a6bacf335249', '唐', '["大道貴知止，昔賢稱二疏。","今來我季方，退身茲有餘。","瀟灑去桎梏，放蕩狎樵漁。","疏泉離遠竇，鑿石構層廬。","溪禽拂窗牖，山花滿庭除。","寒藤繫舴艋，碧潭澄素舒。","覩茲塵𡏖，始見仁智居。","痛哉方散適，溘然歸丘墟。","恨不同老彭，其樂永只且。","自古干祿輩，知進不知退。","立事名雖揚，全身理何昧。","茂先賦《鷦鷯》，體物知顯晦。","一旦悔自速，臨刑無以對。","李斯戀富貴，下包周身智。","及憶東門犬，已棄咸陽市。","平子著《歸田》，淵明捨彭澤，後來區區人，誰復掛書冊。","我喜從今去，吾宗有逋客。","山號查公山，嵽嵲雲漢間。","山下查公塚，溪聲長潺潺。","高臺好悵望，絕磴堪躋攀。","他年謝簪紱，永此繼閑閑。","（見弘治《徽州府志》卷二、《新安文獻志》卷五十一、《宋詩紀事補遺》卷二。","）。"]', '["大道貴知止，昔賢稱二疏。","今来我季方，退身茲有餘。","瀟灑去桎梏，放蕩狎樵漁。","疏泉離远竇，鑿石構層廬。","溪禽拂窗牖，山花满庭除。","寒藤繫舴艋，碧潭澄素舒。","覩茲塵𡏖，始见仁智居。","痛哉方散適，溘然归丘墟。","恨不同老彭，其乐永只且。","自古干祿輩，知進不知退。","立事名雖揚，全身理何昧。","茂先賦《鷦鷯》，體物知显晦。","一旦悔自速，臨刑無以对。","李斯戀富貴，下包周身智。","及憶东门犬，已棄咸陽市。","平子著《归田》，淵明捨彭澤，後来區區人，誰复掛书冊。","我喜從今去，吾宗有逋客。","山號查公山，嵽嵲云漢间。","山下查公塚，溪声长潺潺。","高台好悵望，絕磴堪躋攀。","他年謝簪紱，永此繼闲闲。","（见弘治《徽州府志》卷二、《新安文獻志》卷五十一、《宋诗紀事補遺》卷二。","）。"]', '诗', 'shi', '', NULL, '查公山詩 查元方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0de2d1e7-ca75-4aba-8d24-94a1cc0859fd', '謁聖林', '謁聖林', '25df1125-5945-45ce-91ac-2cdc7e59f368', '唐', '["悠悠往古繼來今，天地無窮照孔林。","兩到金絲堂下拜，門生無負百年心。","（見《宋詩紀事補遺》卷二引《闕里志》。","）。"]', '["悠悠往古繼来今，天地無窮照孔林。","兩到金絲堂下拜，门生無負百年心。","（见《宋诗紀事補遺》卷二引《闕里志》。","）。"]', '诗', 'shi', '', NULL, '謁聖林 楊文郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70f0754a-b507-4e26-afdd-8d7cfe3c9da2', '題越臺', '題越台', 'f5ca5e09-6f67-4e2a-a078-d9990a07ae2d', '唐', '["我愛真人居，高臺倚寥泬。","洞天開兩扉，邈爾與世絕。","縹緲乘鸞女，華顏映綠髮。","舉手拂煙虹，吹笙弄松月，森蘿窺萬像，境異趣亦別。","何必服金丹，飛身向蓬闕。","（見《會稽掇英總集》卷十五。","）。"]', '["我愛真人居，高台倚寥泬。","洞天开兩扉，邈爾與世絕。","縹緲乘鸾女，华顏映綠髮。","舉手拂煙虹，吹笙弄松月，森蘿窺万像，境異趣亦別。","何必服金丹，飞身向蓬闕。","（见《會稽掇英總集》卷十五。","）。"]', '诗', 'shi', '', NULL, '題越臺 張洎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87cfa9ae-0280-4628-83ac-8d52d91c9204', '句', '句', 'f5ca5e09-6f67-4e2a-a078-d9990a07ae2d', '唐', '["風物一堆灰。","（見《紺珠集》卷十一引《金坡遺事》。","）（〖1〗《金坡遺事》：「張洎文章清贍。","在江南日，將命入貢。","還作十詩以訾詆京師，有『風物一堆灰』句。","」）。"]', '["风物一堆灰。","（见《紺珠集》卷十一引《金坡遺事》。","）（〖1〗《金坡遺事》：「張洎文章清贍。","在江南日，將命入貢。","還作十诗以訾詆京師，有『风物一堆灰』句。","」）。"]', '诗', 'shi', '', NULL, '句 張洎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b9259e1-e009-4464-ad79-6f0afb5253e0', '由皖口歸昇州作（題擬）', '由皖口归昇州作（題擬）', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["一夜黃星照官渡，本初何面見田豐？","（《徐公文集》附《徐鉉行狀》引。","）。"]', '["一夜黄星照官渡，本初何面见田豐？","（《徐公文集》附《徐鉉行狀》引。","）。"]', '诗', 'shi', '', NULL, '由皖口歸昇州作（題擬） 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18371479-b5f0-4041-b45c-2bd21ccce050', '和表弟包穎見寄', '和表弟包穎见寄', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["平生中表最情親，浮世那堪聚散頻。","謝眺却吟歸省閣，劉楨猶自臥漳濱。","舊游半是前生事，要路多達後進人。","且喜新吟報強健，明年相望杏園春。","（《徐公文集》卷三。","）（按：《徐公文集》卷三收《表弟包穎見寄》，爲包穎寄徐鉉之作；其次爲和詩一首，爲徐鉉和包穎之作。","《全唐詩》誤以包穎詩收徐鉉名下，而以徐和詩錄歸包穎名下。","今爲分別移正之。","此則參《文史》二十五輯曹汛先生文。","）。"]', '["平生中表最情親，浮世那堪聚散頻。","謝眺却吟归省閣，劉楨猶自臥漳濱。","旧游半是前生事，要路多達後進人。","且喜新吟報強健，明年相望杏园春。","（《徐公文集》卷三。","）（按：《徐公文集》卷三收《表弟包穎见寄》，爲包穎寄徐鉉之作；其次爲和诗一首，爲徐鉉和包穎之作。","《全唐诗》誤以包穎诗收徐鉉名下，而以徐和诗錄归包穎名下。","今爲分別移正之。","此則參《文史》二十五輯曹汛先生文。","）。"]', '诗', 'shi', '', NULL, '和表弟包穎見寄 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4531378c-4887-476e-8bd9-04e1d1dcf954', '天柱峰（題擬）', '天柱峰（題擬）', '2ac92c9d-1227-4652-87e5-f4f22e12de2c', '唐', '["天柱一峰藏日月，洞門千仞鎖雲雷。","（見《輿地紀勝》卷四六《安慶府》。","）（按：《天柱山志》收白居易《題天柱峰》，其三四兩句與此同，詳本書卷二八。","）。"]', '["天柱一峰藏日月，洞门千仞鎖云雷。","（见《輿地紀勝》卷四六《安慶府》。","）（按：《天柱山志》收白居易《題天柱峰》，其三四兩句與此同，詳本书卷二八。","）。"]', '诗', 'shi', '', NULL, '天柱峰（題擬） 李明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('003b59e7-0ccb-44b1-9193-a77c280b78c7', '鐘山寺', '鐘山寺', '87210b0b-afdf-45de-ae70-df1624523c36', '唐', '["千峰夾一徑，一徑花枕泉。","聽泉復看花，行到鐘山前。","古寺雲生屋，高僧月伴禪。","自慙留一宿，匹馬又朝天。","（見厲鶚《宋詩紀事》卷三引《撫州府志》、影印文淵閣《四庫全書》本《江西通志》卷一四八。","）。"]', '["千峰夾一徑，一徑花枕泉。","听泉复看花，行到鐘山前。","古寺云生屋，高僧月伴禪。","自慙留一宿，匹马又朝天。","（见厲鶚《宋诗紀事》卷三引《撫州府志》、影印文淵閣《四庫全书》本《江西通志》卷一四八。","）。"]', '诗', 'shi', '', NULL, '鐘山寺 樂史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03d7863c-9636-4b7c-8b2c-e0c0614e9e79', '青青河畔草', '青青河畔草', 'a4b2c775-fdb8-400e-a4dd-ea7cb7d4ced9', '唐', '["王孫歸不歸，翠色和春老。","（宋胡宿《文恭集》卷三六《宋故左龍武衛大將軍李公墓誌銘》引。","）。"]', '["王孫归不归，翠色和春老。","（宋胡宿《文恭集》卷三六《宋故左龙武衛大將軍李公墓誌銘》引。","）。"]', '诗', 'shi', '', NULL, '青青河畔草 李從謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f83ff9-7162-481f-878b-966850561c70', '殘絲曲', '殘絲曲', '01728a42-6b40-4e5e-8878-9156e380ff65', '唐', '["春風駘蕩吹人衣，殘絲罥花曳空飛。","閒愁十丈斷不得，雄蜂雌蝶相因依。","高樓夾路淩雲起，瑣窗鸞柱彈《流水》。","鶯聲啼老楊柳煙，香夢濛濛隔千里。","（見清朱緒曾編《金陵詩徴》卷五。","）。"]', '["春风駘蕩吹人衣，殘絲罥花曳空飞。","閒愁十丈斷不得，雄蜂雌蝶相因依。","高楼夾路淩云起，瑣窗鸾柱彈《流水》。","鶯声啼老楊柳煙，香梦濛濛隔千里。","（见清朱緒曾編《金陵诗徴》卷五。","）。"]', '诗', 'shi', '', NULL, '殘絲曲 盧郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b1822c-0b69-4c3a-b083-87e70cd13d19', '缺題 一', '缺題 一', '1b0614f1-7c7f-42b3-8a10-6396eff28a1b', '唐', '["分飛南渡春風晚，却返家林舊業空。"]', '["分飞南渡春风晚，却返家林旧業空。"]', '诗', 'shi', '', NULL, '缺題 一 王操 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38dc030d-1e6f-4e74-8be4-100142525789', '缺題 二', '缺題 二', '1b0614f1-7c7f-42b3-8a10-6396eff28a1b', '唐', '["無限離情似楊柳，萬條懸放楚江原。","（見《吟窗雜錄》卷二九《歷代吟譜》。","）。"]', '["無限離情似楊柳，万條懸放楚江原。","（见《吟窗杂錄》卷二九《歷代吟譜》。","）。"]', '诗', 'shi', '', NULL, '缺題 二 王操 shi');
